INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (1, 1, 1, '¿Cuál es el puntaje FICO mínimo con el que un solicitante cumple automáticamente el requisito de responsabilidad financiera ante el CILB?', 'What is the minimum FICO score with which an applicant automatically meets the financial responsibility requirement before the CILB?', 'Con 660 o más se cumple la responsabilidad financiera. Por debajo de 660, la solicitud solo avanza tras completar el curso aprobado de responsabilidad financiera de 14 horas.', 'With 660 or more, financial responsibility is met. Below 660, the application only moves forward after completing the approved 14-hour financial responsibility course.', 'Florida Contractors Manual · Requisitos CILB');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (1, 1, '580', '580', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (1, 2, '620', '620', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (1, 3, '660', '660', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (1, 4, '700', '700', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (2, 1, 2, 'Un proveedor de materiales sin contrato directo con el dueño de la obra quiere conservar su derecho de gravamen (lien). ¿Qué documento debe enviar y en qué plazo?', 'A material supplier with no direct contract with the owner of the project wants to preserve its lien right. What document must it send and within what deadline?', 'El Notice to Owner (NTO) es el aviso que protege el derecho de lien de subcontratistas y proveedores sin contrato directo con el dueño. Debe enviarse dentro de los 45 días desde el primer trabajo o la primera entrega de material.', 'The Notice to Owner (NTO) is the notice that protects the lien right of subcontractors and suppliers with no direct contract with the owner. It must be sent within 45 days from the first work or the first delivery of material.', 'Florida Contractors Manual · Cap. 713, Lien Law');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (2, 1, 'Claim of Lien, dentro de 30 días', 'Claim of Lien, within 30 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (2, 2, 'Notice to Owner, dentro de 45 días desde el primer trabajo o entrega', 'Notice to Owner, within 45 days from the first work or delivery', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (2, 3, 'Notice of Commencement, antes de empezar la obra', 'Notice of Commencement, before starting the work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (2, 4, 'Affidavit del contratista, al pago final', 'Contractor''s affidavit, at final payment', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (3, 1, 3, '¿Dentro de qué plazo debe registrarse un Claim of Lien en Florida para que sea válido?', 'Within what deadline must a Claim of Lien be recorded in Florida for it to be valid?', 'El Claim of Lien debe registrarse a más tardar 90 días después del último día de trabajo o de la última entrega de materiales o servicios en el proyecto.', 'The Claim of Lien must be recorded no later than 90 days after the last day of work or the last delivery of materials or services on the project.', 'Florida Contractors Manual · Cap. 713, Lien Law');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (3, 1, '45 días desde la primera entrega', '45 days from the first delivery', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (3, 2, '60 días desde la firma del contrato', '60 days from the signing of the contract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (3, 3, '90 días desde el último trabajo o la última entrega de material', '90 days from the last work or the last delivery of material', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (3, 4, '1 año desde el inicio de la obra', '1 year from the start of the work', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (4, 1, 4, '¿Quién registra el Notice of Commencement y cuándo?', 'Who records the Notice of Commencement and when?', 'El Notice of Commencement lo registra el dueño (o su agente autorizado) en los registros del condado antes de comenzar la obra; de él depende el cómputo de varios plazos del lien.', 'The Notice of Commencement is recorded by the owner (or the owner''s authorized agent) in the county records before the work begins; the computation of several lien deadlines depends on it.', 'Florida Contractors Manual · Cap. 713');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (4, 1, 'El contratista, al recibir el primer pago', 'The contractor, upon receiving the first payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (4, 2, 'El dueño de la propiedad, antes de que comience la construcción', 'The property owner, before construction begins', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (4, 3, 'El arquitecto, al emitir el permiso', 'The architect, when issuing the permit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (4, 4, 'El subcontratista, dentro de 45 días', 'The subcontractor, within 45 days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (5, 1, 5, 'Un contratista tiene un contrato de $800.000, costos totales estimados de $640.000 y costos incurridos a la fecha de $320.000. Con el método de porcentaje de avance, ¿cuánta ganancia bruta reconoce a la fecha?', 'A contractor has a contract of $800,000, total estimated costs of $640,000 and costs incurred to date of $320,000. Under the percentage-of-completion method, how much gross profit does the contractor recognize to date?', 'Porcentaje de avance = 320.000 ÷ 640.000 = 50%. Ingreso reconocido = 50% × 800.000 = 400.000. Ganancia bruta = 400.000 − 320.000 = $80.000.', 'Percentage of completion = 320,000 ÷ 640,000 = 50%. Revenue recognized = 50% × 800,000 = 400,000. Gross profit = 400,000 − 320,000 = $80,000.', 'Builder''s Guide to Accounting · Percentage-of-completion');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (5, 1, '$40.000', '$40,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (5, 2, '$80.000', '$80,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (5, 3, '$160.000', '$160,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (5, 4, '$320.000', '$320,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (6, 1, 6, '¿Cómo se calcula el capital de trabajo (working capital) de una empresa?', 'How is a company''s working capital calculated?', 'Working capital = activos corrientes − pasivos corrientes. Es la cifra que bancos y afianzadoras usan para medir si la empresa puede sostener la operación de sus proyectos.', 'Working capital = current assets − current liabilities. It is the figure that banks and sureties use to measure whether the company can sustain the operation of its projects.', 'Builder''s Guide to Accounting');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (6, 1, 'Activos totales menos patrimonio', 'Total assets minus equity', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (6, 2, 'Activos corrientes menos pasivos corrientes', 'Current assets minus current liabilities', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (6, 3, 'Ingresos menos costos de obra', 'Revenue minus job costs', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (6, 4, 'Pasivos corrientes entre activos corrientes', 'Current liabilities divided by current assets', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (7, 1, 7, 'Si una empresa tiene activos corrientes de $150.000 y pasivos corrientes de $100.000, su razón corriente (current ratio) es:', 'If a company has current assets of $150,000 and current liabilities of $100,000, its current ratio is:', 'Current ratio = activos corrientes ÷ pasivos corrientes = 150.000 ÷ 100.000 = 1,50. Mide la capacidad de pagar las obligaciones de corto plazo.', 'Current ratio = current assets ÷ current liabilities = 150,000 ÷ 100,000 = 1.50. It measures the ability to pay short-term obligations.', 'Builder''s Guide to Accounting');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (7, 1, '0,67', '0.67', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (7, 2, '1,00', '1.00', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (7, 3, '1,50', '1.50', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (7, 4, '2,50', '2.50', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (8, 1, 8, 'En la nómina de la construcción, los impuestos FICA corresponden a:', 'In construction payroll, FICA taxes correspond to:', 'FICA financia el Seguro Social y Medicare. El empleador retiene la parte del empleado de su salario y aporta una parte igual por cuenta propia. El desempleo es FUTA (federal) y SUTA (estatal), conceptos distintos.', 'FICA funds Social Security and Medicare. The employer withholds the employee''s share from the employee''s wages and contributes an equal share on its own. Unemployment is FUTA (federal) and SUTA (state), which are different concepts.', 'Florida Contractors Manual · Nómina e impuestos');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (8, 1, 'El seguro de desempleo federal y estatal', 'Federal and state unemployment insurance', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (8, 2, 'Seguro Social y Medicare, con aporte del empleado y del empleador', 'Social Security and Medicare, with contributions from the employee and the employer', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (8, 3, 'Un impuesto estatal de Florida sobre la obra', 'A Florida state tax on the project', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (8, 4, 'La prima de workers'' compensation', 'The workers'' compensation premium', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (9, 1, 9, '¿Quién paga la prima del seguro de compensación de trabajadores (workers'' compensation)?', 'Who pays the workers'' compensation insurance premium?', 'La prima de workers'' compensation la paga íntegramente el empleador; no puede descontarse del salario del empleado. El contratista debe además verificar que sus subcontratistas tengan su cobertura vigente.', 'The workers'' compensation premium is paid entirely by the employer; it cannot be deducted from the employee''s wages. The contractor must also verify that its subcontractors have their coverage in force.', 'Florida Contractors Manual · Seguros');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (9, 1, 'El empleado, por descuento de nómina', 'The employee, through a payroll deduction', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (9, 2, 'El empleador', 'The employer', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (9, 3, 'El dueño del proyecto', 'The project owner', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (9, 4, 'Se reparte 50/50 entre empleador y empleado', 'It is split 50/50 between employer and employee', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (10, 1, 10, 'La ecuación contable fundamental que sostiene todo balance general es:', 'The fundamental accounting equation underlying every balance sheet is:', 'Activos = Pasivos + Patrimonio. Todo el balance general se construye sobre esa igualdad; si no cuadra, hay un error en los registros.', 'Assets = Liabilities + Equity. Every balance sheet is built on that equality; if it does not balance, there is an error in the records.', 'Builder''s Guide to Accounting');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (10, 1, 'Ingresos = gastos + utilidad', 'Revenue = expenses + profit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (10, 2, 'Activos = pasivos + patrimonio', 'Assets = liabilities + equity', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (10, 3, 'Activos fijos = depreciación + valor en libros', 'Fixed assets = depreciation + book value', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (10, 4, 'Patrimonio = ingresos − retiros', 'Equity = revenue − withdrawals', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (11, 1, 11, 'Un contrato de $1.500.000 tiene un costo total estimado de $1.200.000 y costos incurridos a la fecha de $360.000. Con el método de porcentaje de avance (costo a costo), ¿cuánto ingreso acumulado debe reconocerse a la fecha?', 'A $1,500,000 contract has an estimated total cost of $1,200,000 and costs incurred to date of $360,000. Under the percentage-of-completion method (cost-to-cost), how much cumulative revenue should be recognized to date?', 'Porcentaje de avance = 360.000 ÷ 1.200.000 = 30%. Ingreso acumulado = 30% × 1.500.000 = $450.000. Lo facturado al dueño no determina el ingreso reconocido bajo este método.', 'Percent complete = 360,000 ÷ 1,200,000 = 30%. Cumulative revenue = 30% × 1,500,000 = $450,000. The amount billed to the owner does not determine the revenue recognized under this method.', 'Builder''s Guide to Accounting · Percentage-of-completion');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (11, 1, '$360.000', '$360,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (11, 2, '$450.000', '$450,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (11, 3, '$540.000', '$540,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (11, 4, '$1.050.000', '$1,050,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (12, 1, 12, 'En un contrato de $2.400.000 contabilizado por porcentaje de avance, el contratista reconoció $600.000 de ingreso en el primer año. Al cierre del segundo año el avance acumulado es 55%. ¿Cuánto ingreso corresponde reconocer en el segundo año?', 'On a $2,400,000 contract accounted for under percentage-of-completion, the contractor recognized $600,000 of revenue in the first year. At the end of the second year, cumulative progress is 55%. How much revenue should be recognized in the second year?', 'Ingreso acumulado al año 2 = 55% × 2.400.000 = 1.320.000. Ingreso del segundo año = 1.320.000 − 600.000 ya reconocido = $720.000. Cada período reconoce solo el incremento sobre lo acumulado.', 'Cumulative revenue at year 2 = 55% × 2,400,000 = 1,320,000. Second-year revenue = 1,320,000 − 600,000 already recognized = $720,000. Each period recognizes only the increase over the cumulative amount.', 'Builder''s Guide to Accounting · Percentage-of-completion');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (12, 1, '$660.000', '$660,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (12, 2, '$720.000', '$720,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (12, 3, '$1.320.000', '$1,320,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (12, 4, '$600.000', '$600,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (13, 1, 13, 'Un contrato de $900.000 lleva costos incurridos de $500.000, pero el costo total estimado se revisó y subió a $750.000. Con el método de porcentaje de avance, ¿cuánto ingreso acumulado se reconoce?', 'A $900,000 contract has incurred costs of $500,000, but the estimated total cost was revised upward to $750,000. Under the percentage-of-completion method, how much cumulative revenue is recognized?', 'Con el estimado revisado, el avance = 500.000 ÷ 750.000 = 66,67%. Ingreso acumulado = 66,67% × 900.000 = $600.000. Las revisiones del costo total estimado se incorporan al cálculo acumulado del período.', 'With the revised estimate, percent complete = 500,000 ÷ 750,000 = 66.67%. Cumulative revenue = 66.67% × 900,000 = $600,000. Revisions to the estimated total cost are incorporated into the cumulative calculation for the period.', 'Builder''s Guide to Accounting · Percentage-of-completion');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (13, 1, '$562.500', '$562,500', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (13, 2, '$500.000', '$500,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (13, 3, '$675.000', '$675,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (13, 4, '$600.000', '$600,000', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (14, 1, 14, 'En un contrato de $1.000.000 ya se incurrieron $300.000 y el costo estimado para terminar subió a $800.000, para un costo total esperado de $1.100.000. ¿Cómo se trata la pérdida esperada de $100.000 bajo el método de porcentaje de avance?', 'On a $1,000,000 contract, $300,000 has already been incurred and the estimated cost to complete has risen to $800,000, for an expected total cost of $1,100,000. How is the expected $100,000 loss treated under the percentage-of-completion method?', 'Costo total esperado 1.100.000 − precio 1.000.000 = pérdida esperada de $100.000. Cuando un contrato de construcción resultará en pérdida, la pérdida total anticipada se reconoce de inmediato en el período en que se conoce, no en proporción al avance.', 'Expected total cost 1,100,000 − price 1,000,000 = expected loss of $100,000. When a construction contract will result in a loss, the entire anticipated loss is recognized immediately in the period in which it becomes known, not in proportion to progress.', 'Builder''s Guide to Accounting · Percentage-of-completion · Pérdidas anticipadas');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (14, 1, 'Se reconoce solo la parte proporcional al avance, $30.000', 'It is recognized only in proportion to progress, $30,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (14, 2, 'Se difiere hasta terminar la obra', 'It is deferred until the work is finished', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (14, 3, 'Se reconoce de inmediato y por completo, $100.000', 'It is recognized immediately and in full, $100,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (14, 4, 'Se compensa con ganancias de otros contratos', 'It is offset against profits from other contracts', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (15, 1, 15, 'Un contrato en curso acumula costos incurridos de $420.000 y ganancia bruta reconocida de $80.000, pero solo se han facturado $440.000 al dueño. ¿Cómo se presenta la diferencia de $60.000 en el balance general?', 'A contract in progress has accumulated incurred costs of $420,000 and recognized gross profit of $80,000, but only $440,000 has been billed to the owner. How is the $60,000 difference presented on the balance sheet?', 'Construcción en proceso = 420.000 + 80.000 = 500.000. Como ese saldo supera lo facturado (440.000), la diferencia de $60.000 es un activo corriente (subfacturación): se ganó más de lo que se ha facturado.', 'Construction in progress = 420,000 + 80,000 = 500,000. Because that balance exceeds billings (440,000), the $60,000 difference is a current asset (underbilling): more was earned than has been billed.', 'Builder''s Guide to Accounting · Percentage-of-completion · WIP');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (15, 1, 'Como un pasivo corriente: facturación en exceso de costos', 'As a current liability: billings in excess of costs', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (15, 2, 'Como un ingreso adicional del período', 'As additional revenue for the period', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (15, 3, 'No se presenta hasta cobrarla', 'It is not presented until collected', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (15, 4, 'Como un activo corriente: costos e ingresos en exceso de facturación', 'As a current asset: costs and earnings in excess of billings', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (16, 1, 16, 'En otro contrato, la construcción en proceso suma $300.000 (costos de $260.000 más ganancia reconocida de $40.000) y las facturaciones al dueño llegan a $375.000. ¿Cómo se presentan los $75.000 de diferencia?', 'On another contract, construction in progress totals $300,000 (costs of $260,000 plus recognized profit of $40,000) and billings to the owner reach $375,000. How is the $75,000 difference presented?', 'Facturado 375.000 − construcción en proceso 300.000 = $75.000. Cuando lo facturado supera el ingreso ganado, la diferencia es un pasivo corriente (sobrefacturación): se facturó más de lo ejecutado y ganado.', 'Billed 375,000 − construction in progress 300,000 = $75,000. When billings exceed earned revenue, the difference is a current liability (overbilling): more was billed than was performed and earned.', 'Builder''s Guide to Accounting · Percentage-of-completion · WIP');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (16, 1, 'Como un pasivo corriente: facturación en exceso de costos e ingresos', 'As a current liability: billings in excess of costs and earnings', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (16, 2, 'Como un activo corriente por cobrar', 'As a current receivable asset', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (16, 3, 'Como ganancia adicional del período', 'As additional profit for the period', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (16, 4, 'Como una reducción del precio del contrato', 'As a reduction of the contract price', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (17, 1, 17, 'Una empresa usa el método de contrato terminado (completed-contract). Tiene una obra de $600.000 con ganancia esperada de $90.000 y un avance físico del 80% al cierre del año, pero la obra aún no termina. ¿Cuánto ingreso y cuánta ganancia reconoce ese año?', 'A company uses the completed-contract method. It has a $600,000 job with expected profit of $90,000 and physical progress of 80% at year-end, but the job is not yet finished. How much revenue and how much profit does it recognize that year?', 'Con el método de contrato terminado, el ingreso y la ganancia bruta se reconocen únicamente cuando el contrato se completa o está sustancialmente terminado. Mientras tanto, los costos se acumulan en construcción en proceso sin reconocer utilidad.', 'Under the completed-contract method, revenue and gross profit are recognized only when the contract is completed or substantially completed. In the meantime, costs accumulate in construction in progress with no profit recognized.', 'Builder''s Guide to Accounting · Completed-contract method');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (17, 1, '$480.000 de ingreso y $72.000 de ganancia', '$480,000 of revenue and $72,000 of profit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (17, 2, '$600.000 de ingreso y $90.000 de ganancia', '$600,000 of revenue and $90,000 of profit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (17, 3, 'Solo el ingreso, $480.000, sin ganancia', 'Revenue only, $480,000, with no profit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (17, 4, '$0 de ingreso y $0 de ganancia', '$0 of revenue and $0 of profit', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (18, 1, 18, '¿Cuál de las siguientes partidas se clasifica como pasivo corriente en el balance general de una constructora?', 'Which of the following items is classified as a current liability on a construction company''s balance sheet?', 'Los pasivos corrientes vencen dentro del año o del ciclo operativo. La retención por pagar a subcontratistas corresponde a trabajo ya recibido y se liquida al completar esas partidas, por lo que es corriente; la hipoteca a 10 años es no corriente.', 'Current liabilities come due within the year or the operating cycle. Retainage payable to subcontractors corresponds to work already received and is settled when those items are completed, so it is current; the 10-year mortgage is non-current.', 'Builder''s Guide to Accounting · Estados financieros');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (18, 1, 'Una hipoteca sobre el edificio de oficinas con vencimiento a 10 años', 'A mortgage on the office building maturing in 10 years', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (18, 2, 'La retención por pagar a subcontratistas por trabajos ya ejecutados', 'Retainage payable to subcontractors for work already performed', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (18, 3, 'El equipo pesado de la empresa', 'The company''s heavy equipment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (18, 4, 'El capital social aportado por los dueños', 'The capital contributed by the owners', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (19, 1, 19, 'Los ingresos por contratos de una constructora en el año fueron $1.250.000 y el costo de obra (cost of construction) fue $875.000. ¿Cuál es la utilidad bruta del año?', 'A construction company''s contract revenues for the year were $1,250,000 and the cost of construction was $875,000. What is the gross profit for the year?', 'Utilidad bruta = ingresos − costo de obra = 1.250.000 − 875.000 = $375.000. Los gastos de administración y los intereses se restan después, no forman parte del costo de obra.', 'Gross profit = revenues − cost of construction = 1,250,000 − 875,000 = $375,000. Administrative expenses and interest are deducted afterward; they are not part of the cost of construction.', 'Builder''s Guide to Accounting · Estado de resultados');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (19, 1, '$275.000', '$275,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (19, 2, '$400.000', '$400,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (19, 3, '$375.000', '$375,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (19, 4, '$875.000', '$875,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (20, 1, 20, 'Una constructora reporta ingresos de $960.000 y utilidad bruta de $240.000. ¿Cuál es su margen de utilidad bruta?', 'A construction company reports revenues of $960,000 and gross profit of $240,000. What is its gross profit margin?', 'Margen bruto = utilidad bruta ÷ ingresos = 240.000 ÷ 960.000 = 25%. El margen siempre se expresa sobre el precio o ingreso, no sobre el costo (eso sería markup).', 'Gross margin = gross profit ÷ revenues = 240,000 ÷ 960,000 = 25%. Margin is always expressed on the price or revenue, not on cost (that would be markup).', 'Builder''s Guide to Accounting · Estado de resultados');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (20, 1, '20%', '20%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (20, 2, '33,3%', '33.3%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (20, 3, '25%', '25%', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (20, 4, '75%', '75%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (21, 1, 21, 'Con ingresos de $1.250.000, costo de obra de $875.000, gastos generales y administrativos de $190.000 y gastos de intereses de $25.000, ¿cuál es la utilidad antes de impuestos?', 'With revenues of $1,250,000, cost of construction of $875,000, general and administrative expenses of $190,000, and interest expense of $25,000, what is the income before taxes?', '1.250.000 − 875.000 = 375.000 de utilidad bruta; 375.000 − 190.000 = 185.000 de utilidad operativa; 185.000 − 25.000 de intereses = $160.000 antes de impuestos.', '1,250,000 − 875,000 = 375,000 of gross profit; 375,000 − 190,000 = 185,000 of operating income; 185,000 − 25,000 of interest = $160,000 before taxes.', 'Builder''s Guide to Accounting · Estado de resultados');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (21, 1, '$160.000', '$160,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (21, 2, '$135.000', '$135,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (21, 3, '$185.000', '$185,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (21, 4, '$375.000', '$375,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (22, 1, 22, '¿Cómo se presenta en el balance general la retención que el dueño de la obra le tiene retenida al contratista general?', 'How is the retainage that the project owner withholds from the general contractor presented on the balance sheet?', 'La retención por cobrar es un derecho del contratista sobre trabajo ya ejecutado y facturado; solo está pendiente de cobro hasta completar la obra. Por eso se presenta como activo corriente, normalmente junto a las cuentas por cobrar de contratos.', 'Retainage receivable is a right of the contractor over work already performed and billed; it is merely pending collection until the work is completed. It is therefore presented as a current asset, usually together with contract accounts receivable.', 'Builder''s Guide to Accounting · Estados financieros');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (22, 1, 'Como un gasto del período', 'As an expense for the period', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (22, 2, 'Como un pasivo corriente', 'As a current liability', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (22, 3, 'Como ingreso diferido', 'As deferred revenue', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (22, 4, 'Como un activo corriente, dentro de las cuentas por cobrar', 'As a current asset, within accounts receivable', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (23, 1, 23, 'Una constructora tiene activos corrientes de $480.000 y pasivos corrientes de $300.000. Su razón corriente (current ratio) es:', 'A construction company has current assets of $480,000 and current liabilities of $300,000. Its current ratio is:', 'Current ratio = activos corrientes ÷ pasivos corrientes = 480.000 ÷ 300.000 = 1,60. Significa que por cada dólar de deuda de corto plazo hay $1,60 de activos corrientes.', 'Current ratio = current assets ÷ current liabilities = 480,000 ÷ 300,000 = 1.60. It means that for every dollar of short-term debt there are $1.60 of current assets.', 'Builder''s Guide to Accounting · Razones financieras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (23, 1, '0,63', '0.63', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (23, 2, '1,60', '1.60', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (23, 3, '1,25', '1.25', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (23, 4, '2,10', '2.10', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (24, 1, 24, 'Con efectivo de $30.000, inversiones temporales de $20.000, cuentas por cobrar de $75.000, inventarios de $85.000 y pasivos corrientes de $100.000, la razón rápida (quick ratio o acid test) es:', 'With cash of $30,000, short-term investments of $20,000, accounts receivable of $75,000, inventories of $85,000, and current liabilities of $100,000, the quick ratio (acid test) is:', 'Razón rápida = (efectivo + inversiones temporales + cuentas por cobrar) ÷ pasivos corrientes = (30.000 + 20.000 + 75.000) ÷ 100.000 = 1,25. El inventario se excluye porque no se convierte en efectivo de inmediato.', 'Quick ratio = (cash + short-term investments + accounts receivable) ÷ current liabilities = (30,000 + 20,000 + 75,000) ÷ 100,000 = 1.25. Inventory is excluded because it does not convert into cash immediately.', 'Builder''s Guide to Accounting · Razones financieras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (24, 1, '1,25', '1.25', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (24, 2, '0,75', '0.75', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (24, 3, '1,75', '1.75', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (24, 4, '2,10', '2.10', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (25, 1, 25, 'Las ventas netas a crédito de una constructora fueron $1.460.000 en el año y su saldo promedio de cuentas por cobrar fue $146.000. ¿Cuál es su rotación de cuentas por cobrar?', 'A construction company''s net credit sales were $1,460,000 for the year and its average accounts receivable balance was $146,000. What is its accounts receivable turnover?', 'Rotación de cuentas por cobrar = ventas netas a crédito ÷ cuentas por cobrar promedio = 1.460.000 ÷ 146.000 = 10 veces al año. Indica cuántas veces se cobra la cartera en el período.', 'Accounts receivable turnover = net credit sales ÷ average accounts receivable = 1,460,000 ÷ 146,000 = 10 times per year. It indicates how many times the receivables are collected during the period.', 'Builder''s Guide to Accounting · Razones financieras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (25, 1, '5 veces', '5 times', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (25, 2, '8 veces', '8 times', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (25, 3, '12 veces', '12 times', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (25, 4, '10 veces', '10 times', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (26, 1, 26, 'Si la rotación de cuentas por cobrar de una empresa es 8 veces al año, ¿cuál es su período promedio de cobro?', 'If a company''s accounts receivable turnover is 8 times per year, what is its average collection period?', 'Período promedio de cobro = 365 ÷ rotación = 365 ÷ 8 = 45,6 días. Es el tiempo promedio que la empresa tarda en convertir sus cuentas por cobrar en efectivo.', 'Average collection period = 365 ÷ turnover = 365 ÷ 8 = 45.6 days. It is the average time the company takes to convert its accounts receivable into cash.', 'Builder''s Guide to Accounting · Razones financieras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (26, 1, '30,4 días', '30.4 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (26, 2, '45,6 días', '45.6 days', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (26, 3, '60,8 días', '60.8 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (26, 4, '73 días', '73 days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (27, 1, 27, 'Una empresa tiene pasivos totales de $540.000 y activos totales de $900.000. Su razón de endeudamiento (debt ratio) es:', 'A company has total liabilities of $540,000 and total assets of $900,000. Its debt ratio is:', 'Debt ratio = pasivos totales ÷ activos totales = 540.000 ÷ 900.000 = 0,60, es decir, 60%. El 60% de los activos está financiado por terceros y el 40% restante por los dueños.', 'Debt ratio = total liabilities ÷ total assets = 540,000 ÷ 900,000 = 0.60, that is, 60%. 60% of the assets is financed by third parties and the remaining 40% by the owners.', 'Builder''s Guide to Accounting · Razones financieras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (27, 1, '40%', '40%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (27, 2, '50%', '50%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (27, 3, '66,7%', '66.7%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (27, 4, '60%', '60%', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (28, 1, 28, 'Con pasivos totales de $540.000 y patrimonio de $360.000, la razón de deuda a patrimonio (debt-to-equity) es:', 'With total liabilities of $540,000 and equity of $360,000, the debt-to-equity ratio is:', 'Debt-to-equity = pasivos totales ÷ patrimonio = 540.000 ÷ 360.000 = 1,50. Por cada dólar aportado por los dueños, los acreedores han financiado $1,50.', 'Debt-to-equity = total liabilities ÷ equity = 540,000 ÷ 360,000 = 1.50. For every dollar contributed by the owners, creditors have financed $1.50.', 'Builder''s Guide to Accounting · Razones financieras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (28, 1, '0,67', '0.67', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (28, 2, '1,50', '1.50', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (28, 3, '1,00', '1.00', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (28, 4, '2,50', '2.50', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (29, 1, 29, 'La utilidad neta de una constructora fue $72.000 sobre ingresos de $1.200.000. Su margen de utilidad neta es:', 'A construction company''s net income was $72,000 on revenues of $1,200,000. Its net profit margin is:', 'Margen neto = utilidad neta ÷ ingresos = 72.000 ÷ 1.200.000 = 6%. Mide cuánto queda de cada dólar de ingreso después de costos de obra, gastos, intereses e impuestos.', 'Net margin = net income ÷ revenues = 72,000 ÷ 1,200,000 = 6%. It measures how much remains from each dollar of revenue after construction costs, expenses, interest, and taxes.', 'Builder''s Guide to Accounting · Razones financieras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (29, 1, '6%', '6%', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (29, 2, '4%', '4%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (29, 3, '8%', '8%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (29, 4, '16,7%', '16.7%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (30, 1, 30, 'Si la utilidad antes de intereses e impuestos (EBIT) es $180.000 y el gasto de intereses del año es $30.000, la cobertura de intereses (times interest earned) es:', 'If earnings before interest and taxes (EBIT) are $180,000 and the year''s interest expense is $30,000, the interest coverage (times interest earned) is:', 'Cobertura de intereses = EBIT ÷ gasto de intereses = 180.000 ÷ 30.000 = 6 veces. La utilidad operativa cubre seis veces el costo de la deuda, un indicador clave para bancos y afianzadoras.', 'Interest coverage = EBIT ÷ interest expense = 180,000 ÷ 30,000 = 6 times. Operating income covers the cost of debt six times, a key indicator for banks and sureties.', 'Builder''s Guide to Accounting · Razones financieras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (30, 1, '3 veces', '3 times', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (30, 2, '5 veces', '5 times', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (30, 3, '9 veces', '9 times', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (30, 4, '6 veces', '6 times', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (31, 1, 31, 'Una constructora tiene activos corrientes de $615.000 y pasivos corrientes de $410.000. Su capital de trabajo es:', 'A construction company has current assets of $615,000 and current liabilities of $410,000. Its working capital is:', 'Capital de trabajo = activos corrientes − pasivos corrientes = 615.000 − 410.000 = $205.000. Es el colchón de corto plazo con el que la empresa sostiene la operación de sus obras.', 'Working capital = current assets − current liabilities = 615,000 − 410,000 = $205,000. It is the short-term cushion with which the company supports the operation of its jobs.', 'Builder''s Guide to Accounting · Capital de trabajo');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (31, 1, '$105.000', '$105,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (31, 2, '$205.000', '$205,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (31, 3, '$410.000', '$410,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (31, 4, '$1.025.000', '$1,025,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (32, 1, 32, 'Una constructora paga $50.000 de cuentas por pagar a proveedores usando efectivo del banco. ¿Qué efecto tiene ese pago sobre su capital de trabajo?', 'A construction company pays $50,000 of accounts payable to suppliers using cash from the bank. What effect does that payment have on its working capital?', 'El pago reduce el efectivo (activo corriente) en $50.000 y reduce las cuentas por pagar (pasivo corriente) en la misma cantidad. Como ambos lados bajan igual, el capital de trabajo no cambia.', 'The payment reduces cash (current asset) by $50,000 and reduces accounts payable (current liability) by the same amount. Because both sides decrease equally, working capital does not change.', 'Builder''s Guide to Accounting · Capital de trabajo');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (32, 1, 'Aumenta en $50.000', 'It increases by $50,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (32, 2, 'Disminuye en $50.000', 'It decreases by $50,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (32, 3, 'Aumenta en $100.000', 'It increases by $100,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (32, 4, 'No cambia', 'It does not change', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (33, 1, 33, '¿Cuál de los siguientes es un gasto que no representa salida de efectivo en el período?', 'Which of the following is an expense that does not represent a cash outflow in the period?', 'La depreciación distribuye en varios años el costo de un activo que ya se pagó al comprarlo; no implica desembolso en el período. Por eso se suma de vuelta al calcular el flujo de caja operativo por el método indirecto.', 'Depreciation spreads over several years the cost of an asset that was already paid for when purchased; it involves no disbursement in the period. That is why it is added back when computing operating cash flow under the indirect method.', 'Builder''s Guide to Accounting · Flujo de caja');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (33, 1, 'La depreciación de los equipos', 'Depreciation of the equipment', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (33, 2, 'La nómina semanal de campo', 'The weekly field payroll', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (33, 3, 'La compra de materiales pagada de contado', 'The purchase of materials paid in cash', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (33, 4, 'El pago de intereses del préstamo', 'The payment of loan interest', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (34, 1, 34, 'Una constructora cierra el año con utilidad neta positiva, pero no le alcanza el efectivo para cubrir la nómina. La explicación más probable es:', 'A construction company closes the year with positive net income, but does not have enough cash to cover payroll. The most likely explanation is:', 'Bajo el método devengado se reconoce ingreso por avance de obra aunque el dueño pague a 30 o más días y retenga un porcentaje de cada pago. La utilidad en papel puede coexistir con caja vacía si el cobro va muy por detrás del costo.', 'Under the accrual method, revenue is recognized based on job progress even though the owner pays at 30 or more days and withholds a percentage of each payment. Paper profit can coexist with an empty cash position if collections lag far behind costs.', 'Builder''s Guide to Accounting · Flujo de caja de la construcción');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (34, 1, 'Su depreciación anual es demasiado baja', 'Its annual depreciation is too low', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (34, 2, 'Gran parte de su ingreso está atrapada en cuentas por cobrar y en retenciones aún no cobradas', 'Much of its revenue is tied up in accounts receivable and in retainage not yet collected', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (34, 3, 'Tiene demasiado capital de trabajo acumulado', 'It has too much accumulated working capital', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (34, 4, 'Sus costos indirectos son menores que los de la competencia', 'Its indirect costs are lower than those of the competition', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (35, 1, 35, 'Por el método indirecto, una empresa parte de una utilidad neta de $100.000, suma depreciación de $25.000 y registra un aumento de $40.000 en cuentas por cobrar. Su flujo de caja de operación es:', 'Under the indirect method, a company starts with net income of $100,000, adds depreciation of $25,000, and records an increase of $40,000 in accounts receivable. Its operating cash flow is:', '100.000 + 25.000 (la depreciación no es salida de caja) − 40.000 (el aumento en cuentas por cobrar es ingreso aún no cobrado) = $85.000 de flujo operativo.', '100,000 + 25,000 (depreciation is not a cash outflow) − 40,000 (the increase in accounts receivable is revenue not yet collected) = $85,000 of operating cash flow.', 'Builder''s Guide to Accounting · Flujo de caja');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (35, 1, '$65.000', '$65,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (35, 2, '$115.000', '$115,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (35, 3, '$85.000', '$85,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (35, 4, '$165.000', '$165,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (36, 1, 36, '¿Cuál de los siguientes es un costo directo de una obra específica?', 'Which of the following is a direct cost of a specific job?', 'Un costo directo se puede identificar y medir sobre una sola obra, como los materiales incorporados a ella. La renta de la oficina, la contabilidad general y la publicidad son costos indirectos o gastos generales de la empresa.', 'A direct cost can be identified and measured on a single job, such as the materials incorporated into it. Office rent, general accounting, and advertising are indirect costs or general expenses of the company.', 'Builder''s Guide to Accounting · Job costing');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (36, 1, 'La renta de la oficina principal de la empresa', 'The rent of the company''s main office', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (36, 2, 'El salario del contador general', 'The general accountant''s salary', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (36, 3, 'El concreto vertido en la losa de esa obra', 'The concrete poured into that job''s slab', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (36, 4, 'La publicidad institucional de la constructora', 'The construction company''s institutional advertising', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (37, 1, 37, '¿Cuál de los siguientes es un gasto general (overhead) de la empresa y no un costo cargable directamente a una obra?', 'Which of the following is a general expense (overhead) of the company and not a cost chargeable directly to a job?', 'El overhead general sostiene a toda la empresa y no se puede atribuir a una sola obra: oficina principal, administración, seguros generales. Se recupera distribuyéndolo entre los proyectos mediante una tasa, no cargándolo directo.', 'General overhead supports the entire company and cannot be attributed to a single job: main office, administration, general insurance. It is recovered by allocating it among the projects through a rate, not by charging it directly.', 'Builder''s Guide to Accounting · Job costing');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (37, 1, 'Los materiales instalados en el proyecto', 'The materials installed on the project', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (37, 2, 'El subcontrato de plomería de la obra', 'The job''s plumbing subcontract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (37, 3, 'La mano de obra de campo del proyecto', 'The project''s field labor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (37, 4, 'La renta de la oficina principal', 'The rent of the main office', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (38, 1, 38, 'Una obra registra materiales por $145.000, mano de obra directa por $96.000, equipos por $38.000 y subcontratos por $210.000. ¿Cuál es el costo directo total de la obra?', 'A job records materials of $145,000, direct labor of $96,000, equipment of $38,000, and subcontracts of $210,000. What is the total direct cost of the job?', '145.000 + 96.000 + 38.000 + 210.000 = $489.000. Esos cuatro componentes forman el costo directo acumulado en la hoja de costos (job cost sheet) de la obra.', '145,000 + 96,000 + 38,000 + 210,000 = $489,000. Those four components make up the direct cost accumulated on the job''s cost sheet (job cost sheet).', 'Builder''s Guide to Accounting · Job costing');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (38, 1, '$379.000', '$379,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (38, 2, '$489.000', '$489,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (38, 3, '$441.000', '$441,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (38, 4, '$525.000', '$525,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (39, 1, 39, 'Una constructora estima gastos generales anuales de $240.000 y un costo anual de mano de obra directa de $800.000, que usa como base de distribución. Su tasa predeterminada de overhead es:', 'A construction company estimates annual general expenses of $240,000 and an annual direct labor cost of $800,000, which it uses as the allocation base. Its predetermined overhead rate is:', 'Tasa predeterminada = overhead estimado ÷ base estimada = 240.000 ÷ 800.000 = 30%. Se fija al inicio del período para cargar los indirectos a cada obra de manera uniforme durante el año.', 'Predetermined rate = estimated overhead ÷ estimated base = 240,000 ÷ 800,000 = 30%. It is set at the beginning of the period to charge indirect costs to each job uniformly throughout the year.', 'Builder''s Guide to Accounting · Job costing · Tasa predeterminada');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (39, 1, '20% del costo de mano de obra directa', '20% of the direct labor cost', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (39, 2, '25% del costo de mano de obra directa', '25% of the direct labor cost', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (39, 3, '33,3% del costo de mano de obra directa', '33.3% of the direct labor cost', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (39, 4, '30% del costo de mano de obra directa', '30% of the direct labor cost', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (40, 1, 40, 'Con una tasa predeterminada de overhead del 30% sobre el costo de mano de obra directa, ¿cuánto overhead se aplica a una obra cuya mano de obra directa real fue $150.000?', 'With a predetermined overhead rate of 30% of the direct labor cost, how much overhead is applied to a job whose actual direct labor was $150,000?', 'Overhead aplicado = 30% × 150.000 = $45.000. Se usa la tasa predeterminada con la actividad real de la obra, aunque el overhead real de la empresa se conozca después.', 'Applied overhead = 30% × 150,000 = $45,000. The predetermined rate is used with the job''s actual activity, even though the company''s actual overhead is known later.', 'Builder''s Guide to Accounting · Job costing · Tasa predeterminada');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (40, 1, '$30.000', '$30,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (40, 2, '$50.000', '$50,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (40, 3, '$45.000', '$45,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (40, 4, '$60.000', '$60,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (41, 1, 41, 'Una partida de excavación costó en total $68.000 y produjo 8.500 metros cúbicos. ¿Cuál es el costo unitario real de la partida?', 'An excavation line item cost a total of $68,000 and produced 8,500 cubic meters. What is the actual unit cost of the item?', 'Costo unitario = costo total de la partida ÷ cantidad producida = 68.000 ÷ 8.500 = $8,00 por m³. Comparar ese costo unitario real contra el estimado es la base del control de costos y de futuros estimados.', 'Unit cost = total cost of the item ÷ quantity produced = 68,000 ÷ 8,500 = $8.00 per m³. Comparing that actual unit cost against the estimate is the basis of cost control and of future estimates.', 'Builder''s Guide to Accounting · Job costing');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (41, 1, '$6,50 por m³', '$6.50 per m³', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (41, 2, '$9,25 por m³', '$9.25 per m³', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (41, 3, '$12,50 por m³', '$12.50 per m³', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (41, 4, '$8,00 por m³', '$8.00 per m³', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (42, 1, 42, 'Un estimador aplica un markup del 25% sobre el costo de una partida. ¿A qué margen sobre el precio de venta equivale ese markup?', 'An estimator applies a 25% markup on the cost of a line item. What margin on the selling price is that markup equivalent to?', 'Con costo 100 y markup 25%, el precio es 125 y la ganancia 25. Margen = 25 ÷ 125 = 20%. Markup y margen describen la misma ganancia, pero el markup se calcula sobre el costo y el margen sobre el precio.', 'With cost 100 and a 25% markup, the price is 125 and the profit is 25. Margin = 25 ÷ 125 = 20%. Markup and margin describe the same profit, but markup is calculated on cost and margin on price.', 'Builder''s Guide to Accounting · Markup y margen');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (42, 1, '25%', '25%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (42, 2, '20%', '20%', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (42, 3, '15%', '15%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (42, 4, '33,3%', '33.3%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (43, 1, 43, 'Una partida cuesta $150.000 y la empresa quiere obtener un margen bruto del 20% sobre el precio de venta. ¿Qué precio debe cotizar?', 'A line item costs $150,000 and the company wants to obtain a gross margin of 20% on the selling price. What price should it quote?', 'Precio = costo ÷ (1 − margen deseado) = 150.000 ÷ 0,80 = $187.500. Sumar simplemente el 20% al costo daría $180.000, que es un markup del 20% y deja un margen real de solo 16,7%.', 'Price = cost ÷ (1 − desired margin) = 150,000 ÷ 0.80 = $187,500. Simply adding 20% to the cost would give $180,000, which is a 20% markup and leaves an actual margin of only 16.7%.', 'Builder''s Guide to Accounting · Markup y margen');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (43, 1, '$180.000', '$180,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (43, 2, '$190.000', '$190,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (43, 3, '$187.500', '$187,500', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (43, 4, '$195.000', '$195,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (44, 1, 44, 'Una obra costó $64.000 y se vendió en $80.000. ¿Cuál fue el markup aplicado sobre el costo?', 'A job cost $64,000 and was sold for $80,000. What markup was applied on the cost?', 'Markup = ganancia ÷ costo = (80.000 − 64.000) ÷ 64.000 = 16.000 ÷ 64.000 = 25%. El 20% sería el margen, porque se calcula sobre el precio: 16.000 ÷ 80.000.', 'Markup = profit ÷ cost = (80,000 − 64,000) ÷ 64,000 = 16,000 ÷ 64,000 = 25%. 20% would be the margin, because it is calculated on the price: 16,000 ÷ 80,000.', 'Builder''s Guide to Accounting · Markup y margen');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (44, 1, '20%', '20%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (44, 2, '28%', '28%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (44, 3, '25%', '25%', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (44, 4, '33,3%', '33.3%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (45, 1, 45, 'Un estimador suma 50% al costo de una partida convencido de que así obtiene un margen del 50%. ¿Qué margen real obtiene sobre el precio de venta?', 'An estimator adds 50% to the cost of a line item, convinced that this way he obtains a 50% margin. What actual margin does he obtain on the selling price?', 'Con costo 100, el precio queda en 150 y la ganancia en 50. Margen real = 50 ÷ 150 = 33,3%. Para lograr un margen del 50% habría que duplicar el costo, es decir, un markup del 100%.', 'With cost 100, the price becomes 150 and the profit 50. Actual margin = 50 ÷ 150 = 33.3%. To achieve a 50% margin, the cost would have to be doubled, that is, a 100% markup.', 'Builder''s Guide to Accounting · Markup y margen');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (45, 1, '50%', '50%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (45, 2, '40%', '40%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (45, 3, '25%', '25%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (45, 4, '33,3%', '33.3%', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (46, 1, 46, 'Un equipo costó $95.000, tiene un valor residual estimado de $5.000 y una vida útil de 6 años. Por el método de línea recta, ¿cuál es la depreciación anual?', 'A piece of equipment cost $95,000, has an estimated residual value of $5,000, and a useful life of 6 years. Under the straight-line method, what is the annual depreciation?', 'Depreciación anual = (costo − valor residual) ÷ vida útil = (95.000 − 5.000) ÷ 6 = 90.000 ÷ 6 = $15.000. Dividir los $95.000 completos entre 6 daría $15.833, pero el valor residual no se deprecia.', 'Annual depreciation = (cost − residual value) ÷ useful life = (95,000 − 5,000) ÷ 6 = 90,000 ÷ 6 = $15,000. Dividing the full $95,000 by 6 would give $15,833, but the residual value is not depreciated.', 'Builder''s Guide to Accounting · Depreciación');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (46, 1, '$15.000', '$15,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (46, 2, '$13.500', '$13,500', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (46, 3, '$15.833', '$15,833', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (46, 4, '$18.000', '$18,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (47, 1, 47, 'Un activo fijo costó $95.000 y su depreciación acumulada al cierre es $60.000. ¿Cuál es su valor en libros?', 'A fixed asset cost $95,000 and its accumulated depreciation at closing is $60,000. What is its book value?', 'Valor en libros = costo − depreciación acumulada = 95.000 − 60.000 = $35.000. La depreciación acumulada es una cuenta correctora del activo, no un fondo de efectivo.', 'Book value = cost − accumulated depreciation = 95,000 − 60,000 = $35,000. Accumulated depreciation is a contra account to the asset, not a cash fund.', 'Builder''s Guide to Accounting · Depreciación');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (47, 1, '$20.000', '$20,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (47, 2, '$35.000', '$35,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (47, 3, '$30.000', '$30,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (47, 4, '$45.000', '$45,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (48, 1, 48, 'Contablemente, la depreciación acumulada de los equipos se clasifica como:', 'For accounting purposes, accumulated depreciation on equipment is classified as:', 'La depreciación acumulada se presenta restando del costo del activo dentro del balance, reduciendo su valor en libros. No es un pasivo ni un fondo de caja: la depreciación es una distribución del costo, no una valuación ni un ahorro.', 'Accumulated depreciation is presented by deducting it from the cost of the asset on the balance sheet, reducing its book value. It is neither a liability nor a cash fund: depreciation is an allocation of cost, not a valuation or a savings.', 'Builder''s Guide to Accounting · Depreciación');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (48, 1, 'Un pasivo a largo plazo', 'A long-term liability', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (48, 2, 'Un gasto del período', 'An expense for the period', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (48, 3, 'Una cuenta correctora (contra-activo) que reduce el valor del activo', 'A contra account (contra-asset) that reduces the value of the asset', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (48, 4, 'Un fondo de efectivo reservado para reemplazar el equipo', 'A cash fund reserved to replace the equipment', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (49, 1, 49, 'En el estimado de una obra, la partida de contingencia (contingency) tiene como propósito:', 'In the estimate for a job, the purpose of the contingency line item is to:', 'La contingencia es una reserva del estimado para condiciones desconocidas, cambios menores y riesgos del proyecto. No es utilidad ni overhead: si no ocurre el imprevisto, simplemente no se consume.', 'Contingency is an estimate reserve for unknown conditions, minor changes, and project risks. It is neither profit nor overhead: if the unforeseen event does not occur, it is simply not consumed.', 'Builder''s Guide to Accounting · Estimados y presupuesto');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (49, 1, 'Ser la utilidad neta esperada del contratista', 'Be the contractor''s expected net profit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (49, 2, 'Cubrir costos imprevistos y riesgos propios del proyecto', 'Cover unforeseen costs and risks specific to the project', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (49, 3, 'Pagar los gastos generales de la oficina principal', 'Pay the general expenses of the main office', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (49, 4, 'Sustituir el análisis de costos unitarios', 'Replace unit cost analysis', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (50, 1, 50, 'Una partida se estimó en $50.000 y su costo real al completarla fue $57.500. ¿Cuál fue la variación de costo de la partida?', 'A line item was estimated at $50,000 and its actual cost upon completion was $57,500. What was the cost variance of the item?', 'Variación = (57.500 − 50.000) ÷ 50.000 = 7.500 ÷ 50.000 = 15% por encima de lo estimado. Detectar y explicar estas variaciones por código de costo es la función del reporte de costos de obra (job cost report).', 'Variance = (57,500 − 50,000) ÷ 50,000 = 7,500 ÷ 50,000 = 15% above the estimate. Detecting and explaining these variances by cost code is the function of the job cost report.', 'Builder''s Guide to Accounting · Job costing · Control de costos');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (50, 1, 'Sobrecosto del 7,5%', 'Cost overrun of 7.5%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (50, 2, 'Sobrecosto del 15%', 'Cost overrun of 15%', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (50, 3, 'Ahorro del 13%', 'Savings of 13%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (50, 4, 'Sobrecosto del 13%', 'Cost overrun of 13%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (51, 1, 51, 'El costo directo estimado de una obra es $400.000 y los costos indirectos asignados son $40.000. Si la empresa quiere una utilidad del 10% sobre el costo total, ¿cuál debe ser el precio de la oferta?', 'The estimated direct cost of a job is $400,000 and the allocated indirect costs are $40,000. If the company wants a profit of 10% on the total cost, what should the bid price be?', 'Costo total = 400.000 + 40.000 = 440.000. Precio = 440.000 × 1,10 = $484.000. La utilidad se aplica sobre el costo total de la obra, no solo sobre el costo directo.', 'Total cost = 400,000 + 40,000 = 440,000. Price = 440,000 × 1.10 = $484,000. The profit is applied on the total cost of the job, not only on the direct cost.', 'Builder''s Guide to Accounting · Estimados y presupuesto');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (51, 1, '$440.000', '$440,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (51, 2, '$484.000', '$484,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (51, 3, '$480.000', '$480,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (51, 4, '$460.000', '$460,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (52, 1, 52, 'La solicitud de pago del mes certifica trabajo ejecutado por $240.000 y el contrato fija una retención del 10%. ¿Cuánto se retiene en este pago?', 'The month''s payment application certifies work performed of $240,000 and the contract sets a retainage of 10%. How much is withheld on this payment?', 'Retención = 10% × 240.000 = $24.000, y el pago neto del período es $216.000. La retención se acumula como garantía del cumplimiento y se libera al cumplirse las condiciones de cierre del contrato.', 'Retainage = 10% × 240,000 = $24,000, and the net payment for the period is $216,000. Retainage accumulates as a guarantee of performance and is released when the contract closeout conditions are met.', 'Florida Contractors Manual · Pagos por avance y retención');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (52, 1, '$12.000', '$12,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (52, 2, '$20.000', '$20,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (52, 3, '$26.400', '$26,400', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (52, 4, '$24.000', '$24,000', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (53, 1, 53, 'En un contrato de construcción con una entidad pública de Florida, una vez superado el 50% de avance de la obra, la retención sobre cada pago por avance posterior debe reducirse a:', 'On a construction contract with a Florida public entity, once the work has passed 50% completion, the retainage on each subsequent progress payment must be reduced to:', 'El Estatuto de Florida 255.078 permite retener hasta 10% de cada pago por avance hasta el 50% de avance, y exige reducir la retención a 5% en los pagos posteriores a ese punto.', 'Florida Statute 255.078 allows withholding up to 10% of each progress payment until 50% completion, and requires reducing the retainage to 5% on payments after that point.', 'Estatutos de Florida 255.078 · Retención en obra pública');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (53, 1, '0%', '0%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (53, 2, '5%', '5%', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (53, 3, '2%', '2%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (53, 4, '10%', '10%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (54, 1, 54, '¿Cuál es la función de la tabla de valores (schedule of values) en la administración de pagos de una obra?', 'What is the function of the schedule of values in the administration of payments on a job?', 'El schedule of values reparte el precio total del contrato entre sus partidas principales. Cada solicitud de pago mide el avance contra esas partidas, por lo que es el documento base de los pagos por avance.', 'The schedule of values divides the total contract price among its main line items. Each payment application measures progress against those items, so it is the base document for progress payments.', 'Florida Contractors Manual · Pagos por avance');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (54, 1, 'Servir como el presupuesto interno de costos del contratista', 'To serve as the contractor''s internal cost budget', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (54, 2, 'Listar a todos los subcontratistas aprobados del proyecto', 'To list all the approved subcontractors on the project', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (54, 3, 'Establecer el cronograma de ejecución semana a semana', 'To establish the execution schedule week by week', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (54, 4, 'Descomponer el monto del contrato en partidas contra las cuales se certifica y paga el avance', 'To break down the contract amount into line items against which progress is certified and paid', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (55, 1, 55, '¿Cuándo se libera típicamente al contratista la retención acumulada de una obra?', 'When is the accumulated retainage on a job typically released to the contractor?', 'La retención garantiza que el contratista complete y corrija la obra; por eso se libera al final, tras la aceptación, el cierre de la lista de pendientes (punch list) y la entrega de los documentos de cierre exigidos por el contrato.', 'Retainage guarantees that the contractor completes and corrects the work; that is why it is released at the end, after acceptance, closeout of the punch list, and delivery of the closeout documents required by the contract.', 'Florida Contractors Manual · Pagos por avance y retención');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (55, 1, 'Con cada pago por avance, en partes iguales', 'With each progress payment, in equal parts', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (55, 2, 'Automáticamente al llegar al 50% de avance', 'Automatically upon reaching 50% completion', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (55, 3, 'Al completarse la obra y cumplirse las condiciones de cierre y aceptación final', 'When the work is completed and the closeout and final acceptance conditions are met', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (55, 4, 'Nunca, queda como garantía permanente del dueño', 'Never, it remains as the owner''s permanent guarantee', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (56, 1, 56, 'Un contratista opera como empresario individual (sole proprietorship) y su empresa acumula una deuda grande con un proveedor. ¿Quién responde por esa deuda?', 'A contractor operates as a sole proprietor (sole proprietorship) and his company accumulates a large debt to a supplier. Who is liable for that debt?', 'La sole proprietorship no crea una entidad separada: el dueño y el negocio son la misma persona ante la ley, así que el dueño responde personalmente por todas las deudas y obligaciones de la empresa.', 'The sole proprietorship does not create a separate entity: the owner and the business are the same person under the law, so the owner is personally liable for all of the business''s debts and obligations.', 'SBA · Choose a business structure (sole proprietorship)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (56, 1, 'Solo el negocio, porque es una entidad separada del dueño', 'The business alone, because it is an entity separate from the owner', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (56, 2, 'Los empleados de la empresa, en partes iguales', 'The company''s employees, in equal shares', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (56, 3, 'El cliente de la obra donde se generó la deuda', 'The client on the project where the debt originated', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (56, 4, 'El dueño personalmente, con su patrimonio, porque no hay separación legal entre él y el negocio', 'The owner personally, with his own assets, because there is no legal separation between him and the business', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (57, 1, 57, 'En una sociedad colectiva general (general partnership), ¿cómo se tratan las ganancias y la responsabilidad entre los socios?', 'In a general partnership, how are profits and liability treated among the partners?', 'En la general partnership las utilidades y pérdidas ''pasan'' (pass-through) a las declaraciones individuales de los socios, y cada socio es personalmente responsable de las obligaciones financieras de la sociedad.', 'In a general partnership, profits and losses "pass through" to the partners'' individual returns, and each partner is personally responsible for the financial obligations of the partnership.', 'SBA · Choose a business structure (partnership)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (57, 1, 'Las ganancias pasan a las declaraciones personales de los socios y cada socio responde personalmente por las obligaciones del negocio', 'Profits pass through to the partners'' personal tax returns and each partner is personally liable for the obligations of the business', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (57, 2, 'La sociedad paga el impuesto y los socios no responden personalmente', 'The partnership pays the tax and the partners are not personally liable', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (57, 3, 'Solo el socio mayoritario responde por las deudas', 'Only the majority partner is liable for the debts', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (57, 4, 'Los socios responden solo hasta el monto de su inversión inicial', 'The partners are liable only up to the amount of their initial investment', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (58, 1, 58, 'La principal desventaja fiscal de una corporación tipo C (C corporation) frente a otras formas de organización es:', 'The main tax disadvantage of a C corporation compared to other business structures is:', 'La corporación es una entidad legal separada, lo que protege a los dueños de la responsabilidad personal, pero el C corp sufre doble tributación: primero a nivel corporativo y luego sobre los dividendos de los accionistas.', 'The corporation is a separate legal entity, which protects the owners from personal liability, but the C corp suffers double taxation: first at the corporate level and then on the shareholders'' dividends.', 'SBA · Choose a business structure (corporation)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (58, 1, 'Que no puede emitir acciones', 'It cannot issue stock', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (58, 2, 'Que sus dueños responden personalmente por las deudas', 'Its owners are personally liable for its debts', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (58, 3, 'La doble tributación: la corporación paga impuesto sobre su ingreso y los accionistas pagan de nuevo sobre los dividendos', 'Double taxation: the corporation pays tax on its income and the shareholders pay again on dividends', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (58, 4, 'Que no puede tener más de diez accionistas', 'It cannot have more than ten shareholders', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (59, 1, 59, '¿Qué combinación de ventajas ofrece típicamente una LLC a un contratista pequeño?', 'What combination of advantages does an LLC typically offer a small contractor?', 'La LLC combina la protección de responsabilidad limitada de una corporación con el tratamiento fiscal de paso de una sociedad: por defecto las ganancias se reportan en las declaraciones de los miembros y no a nivel de la entidad.', 'The LLC combines the limited-liability protection of a corporation with the pass-through tax treatment of a partnership: by default, profits are reported on the members'' returns and not at the entity level.', 'SBA · Choose a business structure (LLC) · IRS, clasificación fiscal de LLC');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (59, 1, 'Responsabilidad ilimitada del dueño y tributación corporativa doble', 'Unlimited owner liability and double corporate taxation', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (59, 2, 'Responsabilidad personal limitada de los miembros y, por defecto, tributación de paso (pass-through) a los dueños', 'Limited personal liability for the members and, by default, pass-through taxation to the owners', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (59, 3, 'Exención total de impuestos federales', 'Total exemption from federal taxes', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (59, 4, 'Capacidad de emitir acciones en la bolsa sin registrarse', 'The ability to issue shares on the stock exchange without registering', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (60, 1, 60, 'Un contratista ejerce como sole proprietorship usando un nombre ficticio (DBA). Según la s. 489.119(1), ¿a quién únicamente puede emitirse la certificación o el registro?', 'A contractor practices as a sole proprietorship using a fictitious name (DBA). Under s. 489.119(1), to whom only may the certification or registration be issued?', 'La s. 489.119(1) dispone que cuando el individuo ejerce en su propio nombre, o en un nombre ficticio como sole proprietorship, la certificación o el registro solo puede emitirse a ese individuo.', 'Section 489.119(1) provides that when the individual practices in his own name, or under a fictitious name as a sole proprietorship, the certification or registration may be issued only to that individual.', 'Estatutos de Florida, s. 489.119(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (60, 1, 'Al nombre ficticio, como si fuera una persona jurídica', 'To the fictitious name, as if it were a legal person', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (60, 2, 'Al individuo, porque opera en su propio nombre o como empresario individual con nombre ficticio', 'To the individual, because he operates in his own name or as a sole proprietor under a fictitious name', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (60, 3, 'A la empresa como entidad separada', 'To the company as a separate entity', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (60, 4, 'Al contador de la empresa', 'To the company''s accountant', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (61, 1, 61, '¿Quién emite el número de identificación de empleador (EIN) que un contratista necesita para reportar su nómina, y cuánto cuesta obtenerlo?', 'Who issues the employer identification number (EIN) a contractor needs to report his payroll, and how much does it cost to obtain?', 'El EIN es un número federal de nueve dígitos que asigna el IRS; la solicitud (Formulario SS-4 o en línea en irs.gov) es gratuita y el número se requiere para contratar empleados, abrir cuentas bancarias del negocio y presentar declaraciones federales.', 'The EIN is a nine-digit federal number assigned by the IRS; the application (Form SS-4 or online at irs.gov) is free, and the number is required to hire employees, open business bank accounts, and file federal returns.', 'IRS · Formulario SS-4 y solicitud de EIN');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (61, 1, 'La División de Corporaciones de Florida, por $70', 'The Florida Division of Corporations, for $70', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (61, 2, 'El condado donde opera la empresa, por $25', 'The county where the business operates, for $25', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (61, 3, 'El DBPR, como parte de la solicitud de licencia', 'The DBPR, as part of the license application', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (61, 4, 'El IRS, sin costo, mediante la solicitud en línea o el Formulario SS-4', 'The IRS, at no cost, through the online application or Form SS-4', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (62, 1, 62, '¿En qué ventana deben las corporaciones y LLC de Florida presentar su informe anual (annual report) ante la División de Corporaciones (Sunbiz), y qué recargo se impone si se presenta después del 1 de mayo?', 'During what window must Florida corporations and LLCs file their annual report with the Division of Corporations (Sunbiz), and what late fee is imposed if it is filed after May 1?', 'El informe anual mantiene activa a la entidad en Sunbiz y se presenta entre el 1 de enero y el 1 de mayo; la presentación tardía genera un recargo de $400 y la falta reiterada de presentación lleva a la disolución administrativa.', 'The annual report keeps the entity active in Sunbiz and is filed between January 1 and May 1; late filing incurs a $400 late fee, and repeated failure to file leads to administrative dissolution.', 'Departamento de Estado de Florida · División de Corporaciones (Sunbiz), informe anual');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (62, 1, 'Del 1 de enero al 1 de mayo, con un recargo de $400 por atraso', 'From January 1 to May 1, with a $400 late fee', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (62, 2, 'Del 1 de junio al 30 de junio, con un recargo de $50', 'From June 1 to June 30, with a $50 late fee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (62, 3, 'En cualquier mes del año, sin recargo', 'In any month of the year, with no fee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (62, 4, 'Solo cuando cambia el agente registrado, con un recargo de $100', 'Only when the registered agent changes, with a $100 fee', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (63, 1, 63, 'Además de la licencia estatal, el contratista debe obtener el recibo de impuesto comercial local (local business tax receipt) antes de dedicarse al negocio. ¿Quién emite ese recibo?', 'In addition to the state license, the contractor must obtain a local business tax receipt before engaging in business. Who issues that receipt?', 'El Capítulo 205 regula el impuesto comercial local: el recibo lo expide el condado o el municipio (antes llamado licencia ocupacional) y su renovación vence el 30 de septiembre.', 'Chapter 205 regulates the local business tax: the receipt is issued by the county or municipality (formerly called an occupational license), and its renewal is due September 30.', 'Estatutos de Florida, Cap. 205 (local business tax)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (63, 1, 'El DBPR', 'The DBPR', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (63, 2, 'El Departamento de Estado en Sunbiz', 'The Department of State through Sunbiz', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (63, 3, 'El gobierno local: el condado o el municipio donde opera el negocio', 'Local government: the county or municipality where the business operates', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (63, 4, 'La afianzadora que emite sus fianzas', 'The surety that issues his bonds', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (64, 1, 64, 'Un rayo incendia parte de la estructura en construcción y se roban materiales guardados en la obra. ¿Qué póliza responde por esos daños físicos a la obra en curso?', 'Lightning sets fire to part of the structure under construction and materials stored at the site are stolen. Which policy responds to that physical damage to the work in progress?', 'El builder''s risk es un seguro de propiedad para la etapa de construcción: protege la estructura en curso, los materiales y equipos incorporables contra riesgos como incendio, robo, vandalismo y viento hasta que la obra se completa y se entrega.', 'Builder''s risk is a property policy for the construction stage: it protects the structure under construction, materials, and equipment to be incorporated against perils such as fire, theft, vandalism, and wind until the project is completed and delivered.', 'Florida Contractors Manual · Seguros (builder''s risk)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (64, 1, 'La responsabilidad civil general (general liability)', 'Commercial general liability', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (64, 2, 'La póliza umbrella', 'The umbrella policy', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (64, 3, 'El seguro builder''s risk, que cubre la estructura en construcción y los materiales en el sitio contra incendio, robo, vandalismo y eventos climáticos durante la obra', 'Builder''s risk insurance, which covers the structure under construction and materials on site against fire, theft, vandalism, and weather events during construction', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (64, 4, 'La payment bond del proyecto', 'The project''s payment bond', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (65, 1, 65, '¿Para qué sirve una póliza umbrella (excess liability) en el programa de seguros de un contratista?', 'What is the purpose of an umbrella (excess liability) policy in a contractor''s insurance program?', 'La póliza umbrella se coloca sobre las pólizas primarias y entra en juego cuando un reclamo de responsabilidad excede los límites de esas pólizas, aportando una capa adicional de cobertura, típicamente desde $1 millón.', 'The umbrella policy sits on top of the primary policies and comes into play when a liability claim exceeds those policies'' limits, providing an additional layer of coverage, typically starting at $1 million.', 'Florida Contractors Manual · Seguros (umbrella/excess)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (65, 1, 'Para sustituir la póliza de workers'' compensation', 'To replace the workers'' compensation policy', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (65, 2, 'Para aportar límites adicionales de responsabilidad por encima de las pólizas primarias (responsabilidad civil, auto) cuando un reclamo supera esos límites', 'To provide additional liability limits above the primary policies (general liability, auto) when a claim exceeds those limits', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (65, 3, 'Para cubrir los materiales almacenados en la obra', 'To cover materials stored at the project site', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (65, 4, 'Para garantizar el pago a los subcontratistas', 'To guarantee payment to subcontractors', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (66, 1, 66, 'La póliza de responsabilidad civil general (commercial general liability) del contratista cubre principalmente:', 'The contractor''s commercial general liability policy primarily covers:', 'La responsabilidad civil general protege frente a reclamos de terceros por lesiones corporales y daños a su propiedad; las lesiones de los empleados las cubre workers'' compensation y el daño a la propia obra en curso, el builder''s risk.', 'General liability protects against third-party claims for bodily injury and damage to their property; employee injuries are covered by workers'' compensation, and damage to the work itself under construction, by builder''s risk.', 'Florida Contractors Manual · Seguros (responsabilidad civil)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (66, 1, 'Las lesiones de los propios empleados en la obra', 'Injuries to the contractor''s own employees at the job site', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (66, 2, 'El daño a la estructura que el contratista está construyendo', 'Damage to the structure the contractor is building', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (66, 3, 'El incumplimiento del contrato por parte del contratista', 'The contractor''s breach of contract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (66, 4, 'Los reclamos de terceros por lesiones corporales y daños a la propiedad ajena derivados de las operaciones del contratista', 'Third-party claims for bodily injury and damage to others'' property arising from the contractor''s operations', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (67, 1, 67, '¿Qué garantiza una fianza de licitación (bid bond)?', 'What does a bid bond guarantee?', 'El bid bond asegura al dueño que el licitante ganador no retirará su oferta: celebrará el contrato y presentará las payment y performance bonds requeridas.', 'The bid bond assures the owner that the winning bidder will not withdraw its bid: it will execute the contract and furnish the required payment and performance bonds.', 'SBA · Surety Bonds (bid bond)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (67, 1, 'Que el licitante, si gana la adjudicación, firmará el contrato y entregará las fianzas de pago y de cumplimiento exigidas', 'That the bidder, if awarded the contract, will sign the contract and deliver the required payment and performance bonds', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (67, 2, 'Que los proveedores cobrarán por sus materiales', 'That suppliers will be paid for their materials', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (67, 3, 'Que la obra se terminará dentro del presupuesto', 'That the project will be completed within budget', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (67, 4, 'Que el dueño pagará puntualmente cada valuación', 'That the owner will pay each progress payment on time', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (68, 1, 68, 'Si el contratista abandona la obra a mitad de camino, ¿qué fianza protege al dueño para que el contrato se complete según sus términos?', 'If the contractor abandons the project midway, which bond protects the owner so the contract is completed according to its terms?', 'La performance bond garantiza la ejecución del contrato de acuerdo con sus términos y condiciones; ante el incumplimiento del contratista, la afianzadora responde completando la obra o cubriendo la pérdida del dueño hasta el monto de la fianza.', 'The performance bond guarantees performance of the contract in accordance with its terms and conditions; upon the contractor''s default, the surety answers by completing the work or covering the owner''s loss up to the bond amount.', 'SBA · Surety Bonds (performance bond)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (68, 1, 'La performance bond: garantiza que el contrato se ejecutará conforme a sus términos, y la afianzadora puede completar la obra o compensar al dueño', 'The performance bond: it guarantees the contract will be performed according to its terms, and the surety can complete the work or compensate the owner', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (68, 2, 'La bid bond', 'The bid bond', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (68, 3, 'La payment bond', 'The payment bond', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (68, 4, 'La fianza de licencia del condado', 'The county license bond', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (69, 1, 69, '¿A quiénes protege directamente una payment bond en un proyecto de construcción?', 'Whom does a payment bond directly protect on a construction project?', 'La payment bond garantiza que quienes suministran mano de obra y materiales al proyecto (subcontratistas, proveedores y laborers) reciban su pago, función clave donde no caben liens, como la obra pública.', 'The payment bond guarantees that those who furnish labor and materials to the project (subcontractors, suppliers, and laborers) receive their payment, a key function where liens are unavailable, such as on public works.', 'SBA · Surety Bonds (payment bond)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (69, 1, 'Al dueño, contra defectos de construcción', 'The owner, against construction defects', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (69, 2, 'A la afianzadora, contra demandas del contratista', 'The surety, against claims by the contractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (69, 3, 'A los subcontratistas, proveedores y obreros, garantizándoles el pago por el trabajo y los materiales aportados bajo el contrato', 'Subcontractors, suppliers, and laborers, guaranteeing them payment for the work and materials furnished under the contract', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (69, 4, 'Al banco que financia el proyecto', 'The bank financing the project', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (70, 1, 70, '¿Por qué un subcontratista impago en una obra pública de Florida no puede registrar un construction lien contra la propiedad?', 'Why can''t an unpaid subcontractor on a Florida public project record a construction lien against the property?', 'Contra bienes del Estado o de gobiernos locales no procede el construction lien del Capítulo 713; la Ley 255.05 (Little Miller Act de Florida) sustituye esa protección exigiendo una payment bond al contratista de la obra pública.', 'A Chapter 713 construction lien does not lie against property of the State or local governments; Law 255.05 (Florida''s Little Miller Act) substitutes that protection by requiring a payment bond from the public works contractor.', 'Estatutos de Florida, s. 255.05');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (70, 1, 'Porque los liens solo existen en proyectos residenciales', 'Because liens exist only on residential projects', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (70, 2, 'Porque la propiedad pública no está sujeta a liens; su remedio es reclamar contra la payment bond que exige la s. 255.05', 'Because public property is not subject to liens; his remedy is to claim against the payment bond required by s. 255.05', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (70, 3, 'Porque primero debe demandar al condado en corte federal', 'Because he must first sue the county in federal court', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (70, 4, 'Porque los subcontratistas nunca tienen derechos de cobro', 'Because subcontractors never have payment rights', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (71, 1, 71, 'En una obra pública regida por la s. 255.05, un proveedor sin contrato directo con el contratista principal quiere proteger su reclamo contra la payment bond. ¿Qué avisos debe dar y en qué plazos?', 'On a public project governed by s. 255.05, a supplier with no direct contract with the prime contractor wants to protect his claim against the payment bond. What notices must he give, and within what time frames?', 'El reclamante que no está en relación directa con el contratista debe avisarle por escrito dentro de 45 días de empezar a suministrar que mirará a la fianza, y entregar el aviso de no pago al contratista y a la afianzadora dentro de 90 días de su última aportación; la demanda debe presentarse dentro de 1 año de esa última aportación.', 'A claimant not in direct contractual relationship with the contractor must notify the contractor in writing within 45 days of beginning to furnish that he will look to the bond, and deliver the notice of nonpayment to the contractor and the surety within 90 days of his last furnishing; suit must be brought within 1 year of that last furnishing.', 'Estatutos de Florida, s. 255.05(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (71, 1, 'Solo una llamada al dueño antes del pago final', 'Just a phone call to the owner before final payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (71, 2, 'Aviso al secretario del condado dentro de 1 año', 'Notice to the county clerk within 1 year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (71, 3, 'Ninguno: el reclamo contra la fianza es automático', 'None: the claim against the bond is automatic', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (71, 4, 'Aviso al contratista dentro de 45 días de comenzar a suministrar, y aviso de no pago al contratista y a la afianzadora dentro de 90 días tras su última aportación', 'Notice to the contractor within 45 days of first furnishing, and notice of nonpayment to the contractor and the surety within 90 days after his last furnishing', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (72, 1, 72, 'Un claim of lien se registró hace 13 meses y el lienor nunca presentó demanda para ejecutarlo. ¿Cuál es la situación del lien?', 'A claim of lien was recorded 13 months ago and the lienor never filed suit to enforce it. What is the status of the lien?', 'Según la s. 713.22(1), el lien no continúa por más de 1 año después del registro del claim of lien (o de un claim enmendado con fecha posterior de última aportación), salvo que dentro de ese plazo se comience la acción judicial para ejecutarlo.', 'Under s. 713.22(1), the lien does not continue for more than 1 year after the recording of the claim of lien (or an amended claim with a later last-furnishing date), unless an action to enforce it is commenced within that period.', 'Estatutos de Florida, s. 713.22(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (72, 1, 'Sigue vigente indefinidamente hasta que se pague', 'It remains in effect indefinitely until paid', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (72, 2, 'Se convierte automáticamente en sentencia', 'It automatically becomes a judgment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (72, 3, 'Dura 5 años, como una sentencia ordinaria', 'It lasts 5 years, like an ordinary judgment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (72, 4, 'Se extinguió: el lien no dura más de 1 año desde el registro del claim of lien si dentro de ese año no se inicia la acción para ejecutarlo', 'It is extinguished: the lien lasts no more than 1 year after the recording of the claim of lien unless suit to enforce it is begun within that year', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (73, 1, 73, 'El dueño registra y notifica al lienor un Notice of Contest of Lien. ¿Qué efecto tiene sobre el plazo del lienor para demandar?', 'The owner records and serves a Notice of Contest of Lien on the lienor. What effect does it have on the lienor''s deadline to sue?', 'La s. 713.22(2) permite al dueño acortar el período de ejecución: servido el Notice of Contest, el lienor tiene solo 60 días para demandar y, si no lo hace, su lien se extingue automáticamente.', 'Section 713.22(2) allows the owner to shorten the enforcement period: once the Notice of Contest is served, the lienor has only 60 days to sue and, if he fails to do so, his lien is automatically extinguished.', 'Estatutos de Florida, s. 713.22(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (73, 1, 'Lo extiende a 2 años', 'It extends it to 2 years', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (73, 2, 'Lo reduce a 60 días desde la notificación; si no demanda en ese plazo, el lien se extingue automáticamente', 'It shortens it to 60 days from service; if he does not sue within that period, the lien is automatically extinguished', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (73, 3, 'No tiene ningún efecto', 'It has no effect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (73, 4, 'Obliga al dueño a pagar el monto reclamado', 'It obliges the owner to pay the amount claimed', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (74, 1, 74, 'El dueño quiere vender la propiedad pero tiene un lien registrado. Usando la transferencia del lien a una garantía (s. 713.24), ¿por qué monto debe constituirse la fianza o el depósito que sustituye a la propiedad?', 'The owner wants to sell the property but has a recorded lien. Using the transfer of the lien to a security (s. 713.24), in what amount must the bond or deposit that replaces the property be posted?', 'La s. 713.24 permite liberar el inmueble trasladando el lien a una fianza o depósito en efectivo; la garantía debe cubrir lo reclamado, tres años de interés a la tasa legal y una suma para honorarios y costos igual a la mayor entre $5,000 o el 25% del lien.', 'Section 713.24 permits the property to be released by transferring the lien to a bond or cash deposit; the security must cover the amount claimed, three years of interest at the legal rate, and a sum for fees and costs equal to the greater of $5,000 or 25% of the lien.', 'Estatutos de Florida, s. 713.24');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (74, 1, 'Por el mismo monto del lien, sin adicionales', 'For the same amount as the lien, with nothing additional', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (74, 2, 'Por el doble del monto reclamado', 'For twice the amount claimed', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (74, 3, 'Por el monto reclamado en el lien, más el interés de 3 años a la tasa legal, más lo mayor entre $5,000 o el 25% del monto del lien para honorarios y costos', 'For the amount claimed in the lien, plus 3 years of interest at the legal rate, plus the greater of $5,000 or 25% of the lien amount for fees and costs', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (74, 4, 'Por el 10% del valor de la propiedad', 'For 10% of the value of the property', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (75, 1, 75, 'Al firmar el contrato, el subcontratista acepta una cláusula que renuncia desde ya a todo derecho de lien por el trabajo que aún no ha ejecutado. Según la s. 713.20(2), esa renuncia es:', 'When signing the contract, the subcontractor accepts a clause waiving in advance all lien rights for work he has not yet performed. Under s. 713.20(2), that waiver is:', 'La s. 713.20(2) establece que el derecho a reclamar un lien no puede renunciarse por anticipado y que toda renuncia anticipada es inexigible; la renuncia solo alcanza el trabajo, los servicios o los materiales ya suministrados.', 'Section 713.20(2) provides that the right to claim a lien cannot be waived in advance and that any advance waiver is unenforceable; a waiver reaches only work, services, or materials already furnished.', 'Estatutos de Florida, s. 713.20(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (75, 1, 'Inexigible: el derecho a reclamar un lien no puede renunciarse por anticipado; solo puede renunciarse hasta donde ya se suministró trabajo o materiales', 'Unenforceable: the right to claim a lien cannot be waived in advance; it may be waived only to the extent work or materials have already been furnished', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (75, 2, 'Plenamente válida porque fue firmada libremente', 'Fully valid because it was freely signed', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (75, 3, 'Válida solo si se firmó ante notario', 'Valid only if signed before a notary', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (75, 4, 'Válida únicamente en proyectos comerciales', 'Valid only on commercial projects', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (76, 1, 76, 'Después de registrar el claim of lien, ¿en qué plazo debe el lienor entregar copia de ese claim al dueño de la propiedad?', 'After recording the claim of lien, within what time must the lienor serve a copy of that claim on the property owner?', 'La s. 713.08 exige que la copia del claim of lien se sirva al dueño antes de su registro o, a más tardar, dentro de los 15 días posteriores al registro, por los medios de servicio de la s. 713.18.', 'Section 713.08 requires that a copy of the claim of lien be served on the owner before its recording or, at the latest, within 15 days after recording, by the service methods of s. 713.18.', 'Estatutos de Florida, s. 713.08(4)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (76, 1, 'Dentro de los 45 días siguientes al registro', 'Within 45 days after recording', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (76, 2, 'Antes de registrarlo o dentro de los 15 días siguientes al registro', 'Before recording it or within 15 days after recording', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (76, 3, 'Dentro de los 90 días siguientes al registro', 'Within 90 days after recording', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (76, 4, 'No hay obligación de entregar copia si ya se registró', 'There is no duty to serve a copy once it has been recorded', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (77, 1, 77, 'Antes de demandar la ejecución de su lien, el contratista directo debe entregar al dueño su declaración jurada de pago final (Contractor''s Final Payment Affidavit). ¿Con cuánta anticipación mínima?', 'Before suing to enforce his lien, the direct contractor must deliver his Contractor''s Final Payment Affidavit to the owner. How far in advance, at minimum?', 'La s. 713.06(3)(d) obliga al contratista que va a demandar a entregar al dueño su affidavit final, donde declara los lienors impagos y los montos, no menos de 5 días antes de entablar la acción.', 'Section 713.06(3)(d) requires a contractor who is going to sue to deliver his final affidavit to the owner, declaring the unpaid lienors and amounts, not less than 5 days before bringing the action.', 'Estatutos de Florida, s. 713.06(3)(d)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (77, 1, 'Al menos 5 días antes de presentar la demanda', 'At least 5 days before filing suit', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (77, 2, 'El mismo día de la demanda', 'The same day as the suit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (77, 3, 'Al menos 30 días antes de presentar la demanda', 'At least 30 days before filing suit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (77, 4, 'Solo si el juez lo ordena', 'Only if the judge so orders', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (78, 1, 78, 'Si el Notice of Commencement no especifica una fecha de vencimiento distinta, ¿cuándo deja de ser efectivo?', 'If the Notice of Commencement does not specify a different expiration date, when does it cease to be effective?', 'El propio formulario de la s. 713.13 indica que la fecha de vencimiento del Notice of Commencement es 1 año desde su registro, salvo que se especifique una fecha diferente.', 'The form itself under s. 713.13 states that the expiration date of the Notice of Commencement is 1 year from its recording, unless a different date is specified.', 'Estatutos de Florida, s. 713.13');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (78, 1, 'A los 90 días de registrado', '90 days after it is recorded', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (78, 2, 'Cuando el dueño paga la primera valuación', 'When the owner pays the first progress payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (78, 3, 'Nunca: dura hasta que se cancele el permiso', 'Never: it lasts until the permit is canceled', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (78, 4, 'Al año de su registro', '1 year after its recording', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (79, 1, 79, 'Un contrato directo entre el dueño y el contratista supera los $2,500. Según la s. 713.015, ese contrato debe:', 'A direct contract between the owner and the contractor exceeds $2,500. Under s. 713.015, that contract must:', 'La s. 713.015 exige que todo contrato directo mayor de $2,500 contenga las provisiones obligatorias que informan al dueño de sus derechos y responsabilidades bajo la Construction Lien Law, incluida la advertencia de que podría pagar dos veces si no obtiene las liberaciones.', 'Section 713.015 requires every direct contract over $2,500 to contain the mandatory provisions informing the owner of his rights and responsibilities under the Construction Lien Law, including the warning that he could pay twice if he does not obtain releases.', 'Estatutos de Florida, s. 713.015');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (79, 1, 'Registrarse en la oficina del secretario del condado', 'Be recorded in the county clerk''s office', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (79, 2, 'Ser aprobado por el DBPR antes de firmarse', 'Be approved by the DBPR before it is signed', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (79, 3, 'Incluir las provisiones obligatorias con la información y advertencia de la ley de gravámenes para el dueño', 'Include the mandatory provisions with the lien law information and warning for the owner', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (79, 4, 'Firmarse ante dos testigos y un notario', 'Be signed before two witnesses and a notary', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (80, 1, 80, 'En un juicio para ejecutar un construction lien o un reclamo contra una fianza bajo el Capítulo 713, ¿quién recupera los honorarios de abogado según la s. 713.29?', 'In a suit to enforce a construction lien or a claim against a bond under Chapter 713, who recovers attorney''s fees under s. 713.29?', 'La s. 713.29 concede a la parte que prevalece en la acción de ejecución del lien o del reclamo contra la fianza el derecho a recuperar honorarios razonables de abogado por juicio y apelación, tasados como parte de las costas.', 'Section 713.29 grants the prevailing party in an action to enforce the lien or a claim against the bond the right to recover reasonable attorney''s fees for trial and appeal, taxed as part of the costs.', 'Estatutos de Florida, s. 713.29');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (80, 1, 'Siempre el dueño de la propiedad', 'Always the property owner', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (80, 2, 'Siempre el lienor', 'Always the lienor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (80, 3, 'La parte que prevalece (prevailing party), por un monto razonable fijado por el tribunal', 'The prevailing party, in a reasonable amount fixed by the court', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (80, 4, 'Nadie: cada parte paga siempre a su abogado', 'No one: each party always pays its own attorney', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (81, 1, 81, 'Un lienor registra un claim of lien por $80,000 sabiendo que solo se le deben $40,000, e incluye trabajo que nunca ejecutó. Bajo la s. 713.31, ese lien se considera:', 'A lienor records a claim of lien for $80,000 knowing that only $40,000 is owed to him, and includes work he never performed. Under s. 713.31, that lien is considered:', 'La s. 713.31 sanciona el fraude en la ley de gravámenes: exagerar deliberadamente el monto reclamado o incluir partidas no suministradas convierte el lien en fraudulento, lo hace inexigible y genera responsabilidad por daños y honorarios de la otra parte.', 'Section 713.31 punishes fraud under the lien law: willfully exaggerating the amount claimed or including items not furnished makes the lien fraudulent, renders it unenforceable, and creates liability for damages and the other party''s fees.', 'Estatutos de Florida, s. 713.31');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (81, 1, 'Válido por el monto completo, porque el juez lo ajustará', 'Valid for the full amount, because the judge will adjust it', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (81, 2, 'Una simple falta administrativa sin consecuencias', 'A simple administrative error without consequences', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (81, 3, 'Válido solo contra el contratista, no contra el dueño', 'Valid only against the contractor, not against the owner', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (81, 4, 'Fraudulento: un lien deliberadamente exagerado o con trabajo no realizado es inexigible y expone al lienor a daños y honorarios', 'Fraudulent: a lien that is willfully exaggerated or includes work not performed is unenforceable and exposes the lienor to damages and fees', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (82, 1, 82, '¿Cuál es la mecánica del impuesto federal de desempleo (FUTA) que paga un contratista empleador?', 'How does the federal unemployment tax (FUTA) paid by an employing contractor work?', 'El FUTA es un costo exclusivo del empleador: se aplica a los primeros $7,000 anuales por empleado a la tasa bruta de 6,0%, y el crédito por impuestos estatales de desempleo pagados a tiempo puede reducir la tasa efectiva a 0,6%.', 'FUTA is solely an employer cost: it applies to the first $7,000 per employee per year at the gross rate of 6.0%, and the credit for state unemployment taxes paid on time can reduce the effective rate to 0.6%.', 'IRS · Tópico 759 y Publicación 15 (FUTA)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (82, 1, 'Se descuenta del salario del empleado a razón del 6,0% sin límite', 'It is deducted from the employee''s wages at 6.0% with no limit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (82, 2, 'Lo paga solo el empleador: 6,0% sobre los primeros $7,000 pagados a cada empleado, con un crédito de hasta 5,4% por el impuesto estatal pagado, para una tasa efectiva típica de 0,6%', 'The employer alone pays it: 6.0% on the first $7,000 paid to each employee, with a credit of up to 5.4% for state unemployment tax paid, for a typical effective rate of 0.6%', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (82, 3, 'Lo pagan empleador y empleado por mitades sobre todo el salario', 'Employer and employee split it on the entire salary', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (82, 4, 'Es un impuesto estatal de Florida del 2,7%', 'It is a Florida state tax of 2.7%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (83, 1, 83, '¿En qué formulario y con qué frecuencia se declara el impuesto FUTA ante el IRS?', 'On what form, and how often, is the FUTA tax reported to the IRS?', 'El FUTA se reporta anualmente en el Formulario 940 (Employer''s Annual Federal Unemployment Tax Return), que vence el 31 de enero del año siguiente; los depósitos pueden exigirse trimestralmente si la deuda acumulada supera los $500.', 'FUTA is reported annually on Form 940 (Employer''s Annual Federal Unemployment Tax Return), due January 31 of the following year; deposits may be required quarterly if the accumulated liability exceeds $500.', 'IRS · Formulario 940 e instrucciones');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (83, 1, 'Formulario 940, una vez al año, con vencimiento el 31 de enero del año siguiente', 'Form 940, once a year, due January 31 of the following year', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (83, 2, 'Formulario 941, cada trimestre', 'Form 941, each quarter', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (83, 3, 'Formulario W-2, cada diciembre', 'Form W-2, each December', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (83, 4, 'Formulario RT-6, cada trimestre', 'Form RT-6, each quarter', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (84, 1, 84, 'El Formulario 941 del IRS se presenta trimestralmente y sirve para reportar:', 'IRS Form 941 is filed quarterly and is used to report:', 'Con el Formulario 941 el empleador reporta cada trimestre los salarios, las propinas y otras compensaciones, junto con la retención de income tax y las porciones de empleado y empleador de Seguro Social y Medicare; vence el último día del mes siguiente al trimestre.', 'With Form 941, the employer reports each quarter the wages, tips, and other compensation, together with income tax withholding and the employee and employer portions of Social Security and Medicare; it is due the last day of the month following the quarter.', 'IRS · Formulario 941 e instrucciones');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (84, 1, 'Los salarios pagados, el impuesto federal sobre la renta retenido y las contribuciones al Seguro Social y Medicare (FICA) del trimestre', 'Wages paid, federal income tax withheld, and Social Security and Medicare (FICA) contributions for the quarter', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (84, 2, 'Solo el impuesto FUTA del año', 'Only the FUTA tax for the year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (84, 3, 'Las ventas sujetas al impuesto estatal', 'Sales subject to state tax', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (84, 4, 'Los ingresos anuales de la corporación', 'The corporation''s annual income', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (85, 1, 85, '¿Cuál es la fecha límite para entregar el Formulario W-2 a cada empleado y presentar las copias ante la Administración del Seguro Social?', 'What is the deadline to give Form W-2 to each employee and file the copies with the Social Security Administration?', 'El empleador debe proporcionar el W-2 a cada empleado y transmitir las copias con el Formulario W-3 a la SSA a más tardar el 31 de enero del año siguiente al año salarial reportado.', 'The employer must furnish the W-2 to each employee and transmit the copies with Form W-3 to the SSA no later than January 31 of the year following the wage year reported.', 'IRS · Instrucciones generales de los Formularios W-2 y W-3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (85, 1, 'El 15 de abril del año siguiente', 'April 15 of the following year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (85, 2, 'El 31 de enero del año siguiente', 'January 31 of the following year', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (85, 3, 'El 28 de febrero del año siguiente', 'February 28 of the following year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (85, 4, 'El 31 de diciembre del mismo año', 'December 31 of the same year', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (86, 1, 86, 'Un contratista nuevo en Florida contrata a su primer empleado. ¿Cuál es su tasa inicial del impuesto de reempleo (reemployment tax, el desempleo estatal) y sobre qué base se calcula?', 'A new Florida contractor hires his first employee. What is his initial reemployment tax rate (the state unemployment tax), and on what base is it calculated?', 'Florida fija la tasa inicial de reemployment tax en 0,0270 (2,7%) sobre los primeros $7,000 de salarios por empleado y por año; se mantiene hasta que el empleador ha reportado 10 trimestres y luego pasa a una tasa por experiencia, declarándose con el RT-6.', 'Florida sets the initial reemployment tax rate at 0.0270 (2.7%) on the first $7,000 of wages per employee per year; it remains in effect until the employer has reported 10 quarters, after which an experience rate applies, and it is reported with the RT-6.', 'Departamento de Rentas de Florida · Reemployment Tax (Formulario RT-6)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (86, 1, '5,4% sobre todo el salario anual', '5.4% on the entire annual wage', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (86, 2, '0,6% sobre los primeros $7,000, con el Formulario 940', '0.6% on the first $7,000, with Form 940', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (86, 3, '2,7% sobre los primeros $7,000 pagados a cada empleado en el año, reportado trimestralmente con el Formulario RT-6 hasta completar 10 trimestres reportados', '2.7% on the first $7,000 paid to each employee in the year, reported quarterly with Form RT-6 until 10 quarters have been reported', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (86, 4, '1,0% sobre la nómina total, con el Formulario 941', '1.0% on the total payroll, with Form 941', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (87, 1, 87, '¿Por cuánto tiempo debe el empleador conservar los registros de impuestos sobre el empleo (employment tax records) según el IRS?', 'How long must an employer keep employment tax records under IRS rules?', 'El IRS exige conservar los registros de impuestos de empleo por lo menos 4 años después de la presentación de la declaración del cuarto trimestre del año en cuestión; esos registros sustentan los Formularios 941, 940 y W-2 ante una auditoría.', 'The IRS requires employment tax records to be kept for at least 4 years after the filing of the fourth-quarter return for the year in question; those records support Forms 941, 940, and W-2 in the event of an audit.', 'IRS · Publicación 15, conservación de registros de empleo');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (87, 1, '1 año', '1 year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (87, 2, '3 años desde la contratación', '3 years from hiring', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (87, 3, 'Solo hasta que el empleado deja la empresa', 'Only until the employee leaves the company', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (87, 4, 'Al menos 4 años después de presentada la declaración del cuarto trimestre del año correspondiente', 'At least 4 years after the return for the fourth quarter of the year in question has been filed', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (88, 1, 88, 'Un individuo realiza trabajos de contratación sin estar certificado ni registrado. Por la primera ofensa, la s. 489.127 lo expone a:', 'An individual performs contracting work without being certified or registered. For the first offense, s. 489.127 exposes him to:', 'La contratación sin licencia es delito en Florida: la primera ofensa es un misdemeanor de primer grado (hasta 1 año de cárcel del condado) y la ofensa subsiguiente es un felony de tercer grado.', 'Unlicensed contracting is a crime in Florida: the first offense is a first-degree misdemeanor (up to 1 year in county jail) and a subsequent offense is a third-degree felony.', 'Estatutos de Florida, s. 489.127(1)-(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (88, 1, 'Solo una carta de advertencia del DBPR', 'Only a warning letter from the DBPR', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (88, 2, 'Una multa civil de $25', 'A civil fine of $25', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (88, 3, 'Delito mayor de primer grado desde la primera vez', 'A first-degree felony from the first time', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (88, 4, 'Un delito menor de primer grado; una segunda ofensa se eleva a delito mayor de tercer grado', 'A first-degree misdemeanor; a second offense is elevated to a third-degree felony', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (89, 1, 89, 'Contratar sin licencia durante un estado de emergencia declarado por el Gobernador (por ejemplo, tras un huracán) cambia la clasificación penal así:', 'Contracting without a license during a state of emergency declared by the Governor (for example, after a hurricane) changes the criminal classification as follows:', 'La s. 489.127 eleva a felony de tercer grado la contratación sin licencia cometida durante un estado de emergencia declarado, aunque sea la primera ofensa del individuo.', 'Section 489.127 elevates unlicensed contracting committed during a declared state of emergency to a third-degree felony, even if it is the individual''s first offense.', 'Estatutos de Florida, s. 489.127(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (89, 1, 'No cambia nada', 'Nothing changes', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (89, 2, 'Se reduce a una infracción civil', 'It is reduced to a civil infraction', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (89, 3, 'Aun siendo la primera ofensa, constituye un delito mayor de tercer grado', 'Even if it is the first offense, it constitutes a third-degree felony', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (89, 4, 'Solo se sanciona si el daño supera los $100,000', 'It is punished only if the damage exceeds $100,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (90, 1, 90, 'Un contratista sin licencia termina una remodelación y el dueño se niega a pagarle. Según la s. 489.128, el contratista:', 'An unlicensed contractor finishes a remodel and the owner refuses to pay him. Under s. 489.128, the contractor:', 'Por política pública, la s. 489.128 declara inexigibles en derecho y en equidad, para el contratista que no obtuvo o no mantuvo su licencia, los contratos que ejecuta: no puede cobrarlos en corte ni gravar la propiedad por ellos.', 'As a matter of public policy, s. 489.128 declares unenforceable in law and in equity, for a contractor who did not obtain or maintain his license, the contracts he performs: he cannot collect on them in court or encumber the property under them.', 'Estatutos de Florida, s. 489.128');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (90, 1, 'No puede exigir judicialmente el contrato ni ejercer derechos de lien derivados de él: el contrato es inexigible para el contratista sin licencia', 'Cannot enforce the contract in court or exercise lien rights arising from it: the contract is unenforceable for the unlicensed contractor', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (90, 2, 'Puede demandar y registrar un lien como cualquier contratista', 'Can sue and record a lien like any contractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (90, 3, 'Puede cobrar si el trabajo quedó bien hecho', 'Can collect if the work was well done', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (90, 4, 'Solo pierde el derecho a la ganancia, no al costo', 'Loses only the right to profit, not to his costs', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (91, 1, 91, 'Frente a la actividad sin licencia, la s. 455.228 faculta al DBPR para:', 'With respect to unlicensed activity, s. 455.228 authorizes the DBPR to:', 'La s. 455.228 autoriza al Departamento a buscar el cese de la actividad no licenciada, imponer multas civiles entre $500 y $5,000 por ofensa y recuperar costos, incluso contra quien a sabiendas contrata o ayuda a una persona sin licencia.', 'Section 455.228 authorizes the Department to seek cessation of unlicensed activity, impose civil penalties between $500 and $5,000 per offense, and recover costs, including against one who knowingly contracts with or aids an unlicensed person.', 'Estatutos de Florida, s. 455.228');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (91, 1, 'Solo publicar el nombre del infractor', 'Only publish the offender''s name', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (91, 2, 'Emitir una orden de cese y desistimiento e imponer una multa civil de no menos de $500 ni más de $5,000 por cada ofensa', 'Issue a cease and desist order and impose a civil penalty of not less than $500 nor more than $5,000 per offense', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (91, 3, 'Confiscar las herramientas del infractor', 'Confiscate the offender''s tools', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (91, 4, 'Otorgarle una licencia provisional de 90 días', 'Grant him a provisional 90-day license', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (92, 1, 92, 'En un procedimiento disciplinario bajo la s. 489.129, la multa administrativa máxima que la Junta puede imponer a un licenciado es de:', 'In a disciplinary proceeding under s. 489.129, the maximum administrative fine the Board may impose on a licensee is:', 'La s. 489.129(1) permite a la CILB reprender, poner en probatoria, suspender o revocar, ordenar restitución al consumidor, exigir educación continua, imponer los costos del proceso y multar hasta $10,000 por cada violación.', 'Section 489.129(1) allows the CILB to reprimand, place on probation, suspend or revoke, order restitution to the consumer, require continuing education, impose the costs of the proceeding, and fine up to $10,000 per violation.', 'Estatutos de Florida, s. 489.129(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (92, 1, '$1,000 por violación', '$1,000 per violation', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (92, 2, '$10,000 por violación, además de sanciones como suspensión, revocación, restitución y costos de investigación', '$10,000 per violation, in addition to sanctions such as suspension, revocation, restitution, and investigative costs', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (92, 3, '$5,000 por violación', '$5,000 per violation', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (92, 4, '$500 en total, sin importar las violaciones', '$500 total, regardless of the violations', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (93, 1, 93, 'El único qualifying agent de una empresa contratista renuncia. ¿Qué prohíbe la s. 489.127(1)(g)?', 'The sole qualifying agent of a contracting company resigns. What does s. 489.127(1)(g) prohibit?', 'Ninguna organización puede ejercer la contratación sin estar calificada: operar más de 60 días tras la salida de su único qualifying agent sin designar otro primary qualifying agent es una conducta prohibida por la s. 489.127(1)(g).', 'No organization may engage in contracting without being qualified: operating more than 60 days after the departure of its sole qualifying agent without designating another primary qualifying agent is conduct prohibited by s. 489.127(1)(g).', 'Estatutos de Florida, s. 489.127(1)(g)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (93, 1, 'Que la empresa pague sus cuentas pendientes', 'The company from paying its outstanding bills', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (93, 2, 'Que el qualifying agent trabaje para otra empresa en el futuro', 'The qualifying agent from working for another company in the future', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (93, 3, 'Que la empresa contrate empleados nuevos durante un año', 'The company from hiring new employees for a year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (93, 4, 'Que la empresa siga operando en contratación pasados 60 días desde la terminación de su único qualifying agent sin designar a otro agente primario', 'The company from continuing to operate in contracting more than 60 days after the termination of its sole qualifying agent without designating another primary qualifying agent', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (94, 1, 94, 'La declaración jurada (affidavit) que el primary qualifying agent presenta con la solicitud para calificar a su empresa atestigua que él tiene:', 'The affidavit that the primary qualifying agent files with the application to qualify his business attests that he has:', 'La s. 489.119(2) exige el affidavit del qualifying agent afirmando su autoridad final de aprobación sobre la obra y sobre los negocios de la empresa (contratos, cheques, giros y pagos), excepto en lo financiero cuando la Junta aprueba un financially responsible officer.', 'Section 489.119(2) requires the qualifying agent''s affidavit affirming his final approval authority over the construction work and over the business affairs of the company (contracts, checks, drafts, and payments), except in financial matters when the Board approves a financially responsible officer.', 'Estatutos de Florida, s. 489.119(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (94, 1, 'Al menos el 51% de las acciones de la empresa', 'At least 51% of the company''s stock', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (94, 2, 'Un título universitario en ingeniería civil', 'A university degree in civil engineering', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (94, 3, 'Autoridad final de aprobación sobre todo el trabajo de construcción y sobre los asuntos del negocio, incluidos contratos, especificaciones, cheques y pagos, salvo donde exista un oficial de responsabilidad financiera aprobado', 'Final approval authority over all construction work and over the business affairs, including contracts, specifications, checks, and payments, except in financial matters where the Board has approved a financially responsible officer', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (94, 4, 'Diez años de experiencia como empleado de la empresa', 'Ten years of experience as an employee of the company', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (95, 1, 95, 'Cuando la empresa tiene un Financially Responsible Officer (FRO) aprobado, ¿cómo se reparte la responsabilidad ante la Junta?', 'When the business has an approved Financially Responsible Officer (FRO), how is responsibility divided before the Board?', 'Con un FRO certificado o registrado, éste asume la responsabilidad financiera total de la organización, y el primary qualifying agent queda responsable de todas las actividades de construcción de la empresa, tanto en general como en cada trabajo específico (ss. 489.119 y 489.1195).', 'With a certified or registered FRO, the FRO assumes total financial responsibility for the organization, and the primary qualifying agent remains responsible for all construction activities of the business, both generally and on each specific job (ss. 489.119 and 489.1195).', 'Estatutos de Florida, ss. 489.119 y 489.1195');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (95, 1, 'El FRO responde de todos los aspectos financieros y su aprobación se requiere para los pagos; el primary qualifying agent responde de todas las actividades de construcción, en general y en cada obra específica', 'The FRO is responsible for all financial aspects and his approval is required for payments; the primary qualifying agent is responsible for all construction activities, both generally and on each specific job', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (95, 2, 'El FRO responde de la obra y el qualifying agent de las finanzas', 'The FRO is responsible for the work and the qualifying agent for the finances', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (95, 3, 'Ambos responden de todo sin distinción', 'Both are responsible for everything without distinction', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (95, 4, 'Ninguno responde: responde solo la corporación', 'Neither is responsible: only the corporation is', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (96, 1, 96, 'Un solicitante tiene FICO de 720, pero su informe de crédito muestra una sentencia (judgment) insatisfecha en su contra. Según la Regla 61G4-15.006, ¿qué requisito NO cumple?', 'An applicant has a FICO score of 720, but his credit report shows an unsatisfied judgment against him. Under Rule 61G4-15.006, which requirement does he NOT meet?', 'La Regla 61G4-15.006 separa dos exigencias: la responsabilidad financiera se pierde si el informe de crédito revela judgments o liens insatisfechos (del solicitante o de la entidad que antes calificó), aunque el puntaje supere 660.', 'Rule 61G4-15.006 separates two requirements: financial responsibility is lost if the credit report reveals unsatisfied judgments or liens (of the applicant or of the entity he previously qualified), even if the score exceeds 660.', 'Regla 61G4-15.006, F.A.C.');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (96, 1, 'El de responsabilidad financiera: el informe no debe revelar sentencias ni gravámenes insatisfechos contra el solicitante', 'Financial responsibility: the report must not reveal unsatisfied judgments or liens against the applicant', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (96, 2, 'El de estabilidad financiera, por el puntaje', 'Financial stability, because of the score', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (96, 3, 'Ninguno: el puntaje alto lo cubre todo', 'None: the high score covers everything', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (96, 4, 'El de experiencia en construcción', 'Construction experience', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (97, 1, 97, '¿Qué requisito satisface el curso aprobado de responsabilidad financiera de 14 horas cuando el solicitante no alcanza el puntaje de crédito exigido?', 'Which requirement does the approved 14-hour financial responsibility course satisfy when the applicant does not reach the required credit score?', 'Según la Regla 61G4-15.006(2), la estabilidad financiera se acredita con FICO derivado de 660 o más, o, en su defecto, con la terminación del curso de responsabilidad financiera de 14 horas aprobado por la Junta; el curso no elimina sentencias o gravámenes insatisfechos del requisito de responsabilidad.', 'Under Rule 61G4-15.006(2), financial stability is shown by a FICO-derived score of 660 or higher or, failing that, by completion of the Board-approved 14-hour financial responsibility course; the course does not eliminate unsatisfied judgments or liens from the responsibility requirement.', 'Regla 61G4-15.006(2), F.A.C.');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (97, 1, 'El requisito de experiencia de 4 años', 'The 4-year experience requirement', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (97, 2, 'El examen de Business & Finance completo', 'The entire Business & Finance examination', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (97, 3, 'El de estabilidad financiera: quien no provee un FICO de 660 o más cumple esa exigencia completando el curso de 14 horas aprobado por la Junta', 'Financial stability: an applicant who does not provide a FICO score of 660 or higher satisfies that requirement by completing the Board-approved 14-hour course', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (97, 4, 'El requisito de seguro de responsabilidad civil', 'The general liability insurance requirement', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (98, 1, 98, '¿Cuándo vencen las renovaciones de licencia de los contratistas de construcción de Florida?', 'When do Florida construction contractor license renewals fall due?', 'El ciclo es bienal y escalonado: los certified contractors renuevan el 31 de agosto de los años pares y los registered contractors el 31 de agosto de los años impares, según el DBPR.', 'The cycle is biennial and staggered: certified contractors renew on August 31 of even-numbered years and registered contractors on August 31 of odd-numbered years, according to the DBPR.', 'DBPR · Construction Industry Licensing Board, renovación de licencias');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (98, 1, 'Todos, el 31 de diciembre de cada año', 'All of them, on December 31 of each year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (98, 2, 'Los certificados, el 31 de agosto de los años impares', 'Certified contractors, on August 31 of odd-numbered years', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (98, 3, 'En la fecha de aniversario de cada licencia, cada año', 'On each license''s anniversary date, every year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (98, 4, 'Los certificados, el 31 de agosto de los años pares; los registrados, el 31 de agosto de los años impares', 'Certified contractors, on August 31 of even-numbered years; registered contractors, on August 31 of odd-numbered years', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (99, 1, 99, '¿Cómo se componen las 14 horas de educación continua exigidas en cada ciclo de renovación?', 'How are the 14 hours of continuing education required in each renewal cycle composed?', 'El DBPR exige dentro de las 14 horas al menos una hora en cada una de esas cinco áreas, y los contratistas generales, de edificios y residenciales (entre otros) deben completar además una hora de Wind Mitigation Methodology como parte del total.', 'The DBPR requires, within the 14 hours, at least one hour in each of those five areas, and general, building, and residential contractors (among others) must additionally complete one hour of Wind Mitigation Methodology as part of the total.', 'DBPR · Construction Industry FAQs, educación continua');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (99, 1, '14 horas libres en cualquier tema de construcción', '14 free hours in any construction topic', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (99, 2, 'Al menos 1 hora en cada área: seguridad en el trabajo, compensación de trabajadores, prácticas de negocio, módulo avanzado del Building Code y leyes y reglas; el general contractor suma además 1 hora de metodología de mitigación de viento dentro de las 14', 'At least 1 hour in each area: workplace safety, workers'' compensation, business practices, an advanced Building Code module, and laws and rules; the general contractor must also complete 1 hour of Wind Mitigation Methodology within the 14', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (99, 3, '7 horas de seguridad y 7 de contabilidad', '7 hours of safety and 7 of accounting', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (99, 4, 'Solo horas del Florida Building Code', 'Only Florida Building Code hours', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (100, 1, 100, 'Un licenciado deja pasar dos ciclos consecutivos sin renovar su licencia. ¿Qué ocurre con ella?', 'A licensee lets two consecutive cycles pass without renewing his license. What happens to it?', 'Si la licencia no se renueva durante dos ciclos de licenciamiento consecutivos, queda null and void conforme a la s. 455.271 y la política del DBPR; su titular debe volver a solicitar como un solicitante nuevo, salvo que demuestre que la falta de renovación se debió a enfermedad o dificultad económica.', 'If the license is not renewed during two consecutive licensing cycles, it becomes null and void under s. 455.271 and DBPR policy; its holder must apply again as a new applicant, unless he demonstrates that the failure to renew was due to illness or economic hardship.', 'Estatutos de Florida, s. 455.271 · DBPR, definición de licencia null and void');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (100, 1, 'Queda inactiva pero siempre recuperable pagando los atrasos', 'It becomes inactive but always recoverable by paying the back fees', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (100, 2, 'Se renueva automáticamente con un recargo', 'It renews automatically with a late fee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (100, 3, 'Pasa a nombre de su qualifying agent', 'It passes into the name of his qualifying agent', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (100, 4, 'Se convierte en nula y sin valor (null and void): no se restablece salvo enfermedad o adversidad económica demostrada, y en general debe solicitarse como si nunca se hubiera tenido', 'It becomes null and void: it is not reinstated except upon a showing of illness or economic hardship, and generally it must be applied for as if it had never been held', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (101, 1, 101, 'El Notice of Commencement de un proyecto se registró el 3 de marzo. El 20 de marzo un banco registró una hipoteca sobre el terreno. Meses después, un subcontratista que cumplió todos los avisos registra su claim of lien. En la disputa de prioridad entre el lien del subcontratista y la hipoteca del banco, ¿qué decide la ley?', 'The Notice of Commencement for a project was recorded on March 3. On March 20, a bank recorded a mortgage on the land. Months later, a subcontractor who complied with all of the notices records its claim of lien. In the priority dispute between the subcontractor''s lien and the bank''s mortgage, what does the law decide?', 'Según la s. 713.07(2), los liens de quienes no tienen contrato directo con el dueño se adhieren y toman prioridad desde el registro del Notice of Commencement. Por la s. 713.07(3), esos liens tienen prioridad sobre cualquier gravamen no registrado antes de ese momento; una hipoteca registrada antes del Notice of Commencement sí conservaría su prioridad.', 'Under s. 713.07(2), the liens of those who have no direct contract with the owner attach and take priority from the recording of the Notice of Commencement. Under s. 713.07(3), those liens have priority over any encumbrance not recorded before that time; a mortgage recorded before the Notice of Commencement would indeed keep its priority.', 'Estatutos de Florida · s. 713.07(2) y (3) Prioridad de los liens');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (101, 1, 'La hipoteca tiene prioridad porque se registró antes que el claim of lien', 'The mortgage has priority because it was recorded before the claim of lien', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (101, 2, 'El lien tiene prioridad, porque los liens de subcontratistas y proveedores nacen y toman prioridad desde la fecha de registro del Notice of Commencement, que es anterior a la hipoteca', 'The lien has priority, because the liens of subcontractors and suppliers arise and take priority from the recording date of the Notice of Commencement, which is earlier than the mortgage', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (101, 3, 'Ambos créditos se prorratean al 50%', 'Both claims are prorated 50/50', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (101, 4, 'El lien solo tiene prioridad si el subcontratista notificó también al banco', 'The lien only has priority if the subcontractor also notified the bank', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (102, 1, 102, 'Una empresa suministra áridos a otra empresa de materiales, que los revende y los entrega en una obra privada. La empresa de materiales no paga y la suministradora quiere registrar un construction lien contra la propiedad mejorada. ¿Cuál es su situación bajo el Capítulo 713?', 'A company supplies aggregates to another materials company, which resells them and delivers them to a private project. The materials company does not pay, and the supplier wants to record a construction lien against the improved property. What is its situation under Chapter 713?', 'La definición de materialman de la s. 713.01 cubre a quien suministra materiales al dueño, al contratista, a un subcontratista o a un sub-subcontratista para la mejora. Quien vende a otro materialman queda fuera de la cadena protegida por la s. 713.02 y no adquiere derechos de lien, aunque conserva su acción contractual contra su comprador.', 'The definition of materialman in s. 713.01 covers one who furnishes materials to the owner, to the contractor, to a subcontractor, or to a sub-subcontractor for the improvement. One who sells to another materialman falls outside the chain protected by s. 713.02 and acquires no lien rights, although it retains its contractual action against its buyer.', 'Estatutos de Florida · s. 713.01 Definición de materialman y s. 713.02(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (102, 1, 'Tiene derecho de lien porque sus materiales terminaron incorporados en la obra', 'It has lien rights because its materials ended up incorporated into the work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (102, 2, 'Tiene derecho de lien solo si envió un Notice to Owner dentro de 45 días', 'It has lien rights only if it sent a Notice to Owner within 45 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (102, 3, 'No tiene derecho de lien: quien suministra materiales a otro proveedor de materiales (materialman) no es un lienor bajo la ley', 'It has no lien rights: one who supplies materials to another materials supplier (materialman) is not a lienor under the law', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (102, 4, 'Tiene derecho de lien únicamente por el 50% del valor de los materiales', 'It has lien rights only for 50% of the value of the materials', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (103, 1, 103, 'El contrato de arrendamiento de un local obliga al arrendatario a construir las mejoras de su restaurante. El contratista del arrendatario termina la obra y no recibe el pago final. ¿Contra qué interés puede hacerse efectivo su lien?', 'The lease of a commercial space requires the tenant to build the improvements for its restaurant. The tenant''s contractor finishes the work and does not receive the final payment. Against what interest may its lien be enforced?', 'La s. 713.10 dispone que el lien se extiende al interés del arrendador cuando la mejora la realiza el arrendatario de acuerdo con el contrato entre arrendatario y arrendador. Por eso los arrendadores se protegen registrando oportunamente el arrendamiento, o su forma corta, con el lenguaje expreso que prohíbe esa responsabilidad, antes de que se registre el Notice of Commencement.', 'Section 713.10 provides that the lien extends to the interest of the landlord when the improvement is made by the tenant in accordance with the contract between the tenant and the landlord. That is why landlords protect themselves by timely recording the lease, or its short form, with the express language prohibiting such liability, before the Notice of Commencement is recorded.', 'Estatutos de Florida · s. 713.10 Gravámenes sobre intereses sujetos a arrendamiento');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (103, 1, 'Contra el interés del arrendador también, porque la mejora se hizo de acuerdo con el contrato celebrado entre el arrendatario y el arrendador', 'Against the landlord''s interest as well, because the improvement was made in accordance with the contract entered into between the tenant and the landlord', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (103, 2, 'Solo contra el interés del arrendatario (leasehold); el interés del arrendador jamás se afecta', 'Only against the tenant''s interest (leasehold); the landlord''s interest is never affected', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (103, 3, 'Contra el interés del arrendador solo si este firmó también el contrato de construcción', 'Against the landlord''s interest only if the landlord also signed the construction contract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (103, 4, 'Contra ninguno: las mejoras hechas por arrendatarios no generan liens', 'Against neither: improvements made by tenants do not give rise to liens', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (104, 1, 104, 'Al terminar una obra privada, el dueño paga al contratista el 100% del saldo final sin exigirle la declaración jurada de pago final (contractor''s affidavit), a pesar de haber recibido Notices to Owner de dos subcontratistas que resultan impagos. ¿Cuál es la consecuencia legal de ese pago?', 'At the completion of a private project, the owner pays the contractor 100% of the final balance without requiring the contractor''s final payment affidavit (contractor''s affidavit), even though the owner had received Notices to Owner from two subcontractors who turn out to be unpaid. What is the legal consequence of that payment?', 'La s. 713.06(3)(d)5. obliga al dueño a retener el pago final hasta que el contratista le entregue su affidavit. Si el dueño no retiene como se exige, la s. 713.06(3)(d)6. sujeta la propiedad al monto íntegro de los liens válidos de los que el dueño tenía aviso: es el riesgo de pagar dos veces que advierte la tarjeta del permiso de construcción.', 'Section 713.06(3)(d)5. requires the owner to retain the final payment until the contractor delivers its affidavit to the owner. If the owner fails to retain as required, s. 713.06(3)(d)6. subjects the property to the full amount of the valid liens of which the owner had notice: this is the risk of paying twice that the building permit card warns about.', 'Estatutos de Florida · s. 713.06(3)(d)5. y 6. Pagos propios y affidavit del contratista');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (104, 1, 'Ninguna: al pagar el precio completo del contrato, el dueño queda liberado frente a todos', 'None: by paying the full contract price, the owner is released as to everyone', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (104, 2, 'La propiedad queda sujeta al monto total de todos los liens válidos de los que el dueño tenía aviso cuando el contratista entrega su affidavit, por lo que el dueño puede terminar pagando dos veces', 'The property remains subject to the full amount of all valid liens of which the owner had notice when the contractor delivers its affidavit, so the owner may end up paying twice', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (104, 3, 'El dueño solo arriesga hasta el 10% del precio del contrato', 'The owner only risks up to 10% of the contract price', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (104, 4, 'Los subcontratistas pierden su lien porque el dueño actuó de buena fe', 'The subcontractors lose their lien because the owner acted in good faith', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (105, 1, 105, 'En una escuela pública de $2.300.000 afianzada bajo la s. 255.05, un subcontratista eléctrico contratado directamente por el contratista principal (en privity con él) no recibe su pago final. Para reclamar contra la payment bond, ¿qué avisos preliminares le exige la ley?', 'On a $2,300,000 public school bonded under s. 255.05, an electrical subcontractor hired directly by the prime contractor (in privity with the contractor) does not receive its final payment. To claim against the payment bond, what preliminary notices does the law require of it?', 'La s. 255.05(2) impone el aviso de intención dentro de 45 días y el aviso jurado de no pago (entre 45 y 90 días) únicamente al reclamante que no tiene privity con el contratista, salvo el laborer. Quien contrató directamente con el principal reclama contra la fianza sin esos avisos, pero su demanda vence al año de la última labor o entrega; contra la propiedad pública no cabe lien, el remedio es la fianza.', 'Section 255.05(2) imposes the notice of intent within 45 days and the sworn notice of nonpayment (between 45 and 90 days) only on a claimant who is not in privity with the contractor, except for a laborer. One who contracted directly with the principal claims against the bond without those notices, but its action expires one year after the last labor or delivery; no lien lies against public property — the remedy is the bond.', 'Estatutos de Florida · s. 255.05(2) Reclamos contra la fianza en obra pública');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (105, 1, 'El aviso escrito de 45 días y el aviso jurado de no pago dentro de 90 días, igual que a todo reclamante', 'The written 45-day notice and the sworn notice of nonpayment within 90 days, the same as for every claimant', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (105, 2, 'Solo el aviso jurado de no pago dentro de 90 días', 'Only the sworn notice of nonpayment within 90 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (105, 3, 'Ninguno de esos dos avisos: ambos se exigen solo a los reclamantes que no están en privity con el contratista (con excepción del laborer); él sí debe presentar su demanda dentro del año de su última aportación', 'Neither of those two notices: both are required only of claimants who are not in privity with the contractor (with the exception of the laborer); it must bring its action within one year of its last furnishing', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (105, 4, 'Debe primero registrar un claim of lien contra la escuela', 'It must first record a claim of lien against the school', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (106, 1, 106, 'Un condado adjudica a un contratista la construcción de una biblioteca por $850.000. Bajo la s. 255.05, ¿por qué monto deben emitirse la performance bond y la payment bond exigidas?', 'A county awards a contractor the construction of a library for $850,000. Under s. 255.05, in what amount must the required performance bond and payment bond be issued?', 'La s. 255.05 exige fianzas en los contratos públicos que exceden $100.000 y fija su monto en el precio total del contrato, salvo reducción autorizada por escrito. Como el contrato de $850.000 supera el umbral, la performance bond y la payment bond deben emitirse por $850.000 cada una.', 'Section 255.05 requires bonds on public contracts exceeding $100,000 and sets their amount at the total contract price, unless a reduction is authorized in writing. Because the $850,000 contract exceeds the threshold, the performance bond and the payment bond must each be issued for $850,000.', 'Estatutos de Florida · s. 255.05(1) Fianzas en contratos públicos');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (106, 1, '$85.000 (el 10% del precio del contrato)', '$85,000 (10% of the contract price)', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (106, 2, '$100.000 (el mínimo legal)', '$100,000 (the statutory minimum)', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (106, 3, '$425.000 (el 50% del precio del contrato)', '$425,000 (50% of the contract price)', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (106, 4, '$850.000 (el 100% del precio del contrato)', '$850,000 (100% of the contract price)', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (107, 1, 107, 'Un contratista general subcontrata la estructura a una empresa que, sin que él lo verifique, no tiene seguro de compensación de trabajadores. Un empleado del subcontratista se lesiona en la obra. ¿Quién responde por asegurar y pagar su compensación?', 'A general contractor subcontracts the structure to a company that, without the contractor verifying it, carries no workers'' compensation insurance. An employee of the subcontractor is injured on the job. Who is responsible for securing and paying his compensation?', 'Bajo la s. 440.10(1)(b), el contratista que subcontrata parte de su trabajo actúa como empleador estatutario y responde por la compensación de todos los empleados de la obra, excepto los de un subcontratista que sí aseguró su pago. Por eso la s. 440.10(1)(c) le ordena exigir al sub evidencia de su seguro de compensación o de su certificado de exención, y la (1)(d) le permite recuperar del sub lo que pague.', 'Under s. 440.10(1)(b), a contractor that subcontracts part of its work acts as a statutory employer and is liable for the compensation of all employees on the job, except those of a subcontractor that has secured payment of its own. That is why s. 440.10(1)(c) directs it to require the subcontractor to furnish evidence of its compensation insurance or its certificate of exemption, and s. 440.10(1)(d) allows it to recover from the subcontractor whatever it pays.', 'Estatutos de Florida · s. 440.10(1)(b), (c) y (d) Responsabilidad del contratista');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (107, 1, 'El contratista general: al subcontratar parte de su trabajo debe asegurar el pago de la compensación de todos los empleados dedicados a ese trabajo, salvo los de un subcontratista que sí haya asegurado su pago', 'The general contractor: when it subcontracts part of its work, it must secure the payment of compensation for all employees engaged in that work, except those of a subcontractor that has itself secured payment', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (107, 2, 'Solo el subcontratista: el contratista general nunca responde por empleados ajenos', 'Only the subcontractor: the general contractor never answers for another party''s employees', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (107, 3, 'El fondo estatal de Florida, porque el subcontratista estaba sin seguro', 'The Florida state fund, because the subcontractor was uninsured', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (107, 4, 'El dueño de la obra, por ser el beneficiario final del trabajo', 'The project owner, as the ultimate beneficiary of the work', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (108, 1, 108, 'La nómina anual de campo de una constructora es $250.000, la tarifa de su clase de riesgo es $8,50 por cada $100 de nómina y su modificador de experiencia (EMR) es 1,00. ¿Cuál es su prima anual de workers'' compensation?', 'A construction company''s annual field payroll is $250,000, its risk class rate is $8.50 per $100 of payroll, and its experience modification rate (EMR) is 1.00. What is its annual workers'' compensation premium?', 'La prima se calcula (nómina ÷ 100) × tarifa de clase × EMR: (250.000 ÷ 100) × 8,50 × 1,00 = 2.500 × 8,50 = $21.250. Un EMR menor que 1,00 reduciría la prima y uno mayor la aumentaría, porque refleja el historial de reclamos de la empresa.', 'The premium is computed as (payroll ÷ 100) × class rate × EMR: (250,000 ÷ 100) × 8.50 × 1.00 = 2,500 × 8.50 = $21,250. An EMR below 1.00 would reduce the premium and one above 1.00 would increase it, because it reflects the company''s claims history.', 'FFVA Mutual · Fórmula de la prima de compensación de trabajadores: (nómina ÷ $100) × tarifa de clase × EMR');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (108, 1, '$2.125', '$2,125', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (108, 2, '$21.250', '$21,250', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (108, 3, '$25.000', '$25,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (108, 4, '$212.500', '$212,500', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (109, 1, 109, 'Una afianzadora revisa los estados financieros de un contratista que pide ampliar su programa: su backlog afianzado total sería $1.500.000 y su capital de trabajo ajustado es $75.000, es decir el 5% del backlog (una razón de 20 a 1). ¿Qué conclusión es la más probable del suscriptor?', 'A surety reviews the financial statements of a contractor seeking to expand its program: its total bonded backlog would be $1,500,000 and its adjusted working capital is $75,000, that is, 5% of the backlog (a 20-to-1 ratio). What is the underwriter''s most likely conclusion?', 'El capital de trabajo (activos corrientes menos pasivos corrientes) es la medida central del suscriptor, y la afianzadora lo ajusta descontando cuentas por cobrar viejas y préstamos a partes relacionadas. El consenso del sector (CFMA y NASBP) espera un capital de trabajo de cerca del 10% del backlog afianzado; con solo 5% (20 a 1), el contratista está sobrextendido para ese volumen de trabajo.', 'Working capital (current assets minus current liabilities) is the underwriter''s central measure, and the surety adjusts it by discounting stale receivables and related-party loans. The industry consensus (CFMA and NASBP) expects working capital of roughly 10% of the bonded backlog; at only 5% (20 to 1), the contractor is overextended for that volume of work.', 'Guías del sector de fianzas (CFMA/NASBP) · Capacidad de afianzamiento aproximada de 10 a 20 veces el capital de trabajo ajustado');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (109, 1, 'La posición es sólida: mientras el patrimonio sea positivo, el tamaño del backlog no importa', 'The position is solid: as long as equity is positive, the size of the backlog does not matter', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (109, 2, 'El capital de trabajo es insuficiente para ese backlog: la guía habitual del sector pide que equivalga aproximadamente al 10% o más del backlog (una razón no mayor de unas 10 a 1), así que probablemente limite o niegue la ampliación', 'Working capital is insufficient for that backlog: the industry''s usual guideline calls for it to equal roughly 10% or more of the backlog (a ratio of no more than about 10 to 1), so the surety will likely limit or deny the increase', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (109, 3, 'La afianzadora solo evalúa el puntaje de crédito personal del dueño', 'The surety evaluates only the owner''s personal credit score', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (109, 4, 'El contratista debería reducir su capital de trabajo para mejorar la razón', 'The contractor should reduce its working capital to improve the ratio', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (110, 1, 110, 'Una constructora tiene gastos fijos anuales (overhead) de $300.000 y trabaja con un margen bruto promedio del 25% sobre sus ingresos. ¿Qué volumen anual de ingresos necesita para alcanzar su punto de equilibrio?', 'A construction company has annual fixed expenses (overhead) of $300,000 and works with an average gross margin of 25% on its revenue. What annual revenue volume does it need to reach its break-even point?', 'El punto de equilibrio en ingresos es costos fijos ÷ razón de margen de contribución: $300.000 ÷ 0,25 = $1.200.000. Por debajo de ese volumen, el margen bruto generado por las obras no alcanza a cubrir el overhead y la empresa opera con pérdida.', 'Break-even revenue equals fixed costs ÷ contribution margin ratio: $300,000 ÷ 0.25 = $1,200,000. Below that volume, the gross margin generated by the jobs does not cover the overhead and the company operates at a loss.', 'Análisis del punto de equilibrio · Ingresos de equilibrio = costos fijos ÷ margen de contribución (fuente educativa abierta)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (110, 1, '$75.000', '$75,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (110, 2, '$375.000', '$375,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (110, 3, '$1.200.000', '$1,200,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (110, 4, '$3.000.000', '$3,000,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (111, 1, 111, 'Una constructora evalúa un cargador para un horizonte de 4 años. Comprarlo cuesta $60.000, con mantenimiento de $3.000 al año y valor de reventa de $15.000 al final del año 4. Arrendarlo cuesta $1.400 mensuales durante 48 meses. Comparando el costo total neto de cada opción, ¿cuál conviene y por cuánto?', 'A construction company is evaluating a loader over a 4-year horizon. Buying it costs $60,000, with maintenance of $3,000 per year and a resale value of $15,000 at the end of year 4. Leasing it costs $1,400 per month for 48 months. Comparing the total net cost of each option, which is the better choice and by how much?', 'Comprar: $60.000 + (4 × $3.000 de mantenimiento) − $15.000 de reventa = $57.000. Arrendar: $1.400 × 48 meses = $67.200. La diferencia es $67.200 − $57.000 = $10.200 a favor de la compra, sin considerar el valor del dinero en el tiempo ni el efecto de impuestos.', 'Buying: $60,000 + (4 × $3,000 of maintenance) − $15,000 resale = $57,000. Leasing: $1,400 × 48 months = $67,200. The difference is $67,200 − $57,000 = $10,200 in favor of buying, without considering the time value of money or tax effects.', 'Análisis comprar vs. arrendar · Comparación del costo total de propiedad del equipo (fuente educativa abierta)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (111, 1, 'Arrendar: cuesta $67.200 contra $72.000 de la compra, y ahorra $4.800', 'Leasing: it costs $67,200 versus $72,000 for buying, and saves $4,800', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (111, 2, 'Comprar: su costo neto es $45.000 contra $67.200 del arriendo, y ahorra $22.200', 'Buying: its net cost is $45,000 versus $67,200 for leasing, and saves $22,200', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (111, 3, 'Ambas opciones cuestan exactamente lo mismo al final de los 4 años', 'Both options cost exactly the same at the end of the 4 years', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (111, 4, 'Comprar: su costo neto es $57.000 contra $67.200 del arriendo, y ahorra $10.200', 'Buying: its net cost is $57,000 versus $67,200 for leasing, and saves $10,200', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (112, 1, 112, 'En una licitación regida por AIA A701, un contratista presenta una oferta base de $480.000, el Alternate Aditivo N.º 1 por $25.000 y el Alternate Deductivo N.º 2 por $12.000. El dueño acepta la oferta base y AMBOS alternates. ¿Cuál es el monto inicial del contrato?', 'In a bid governed by AIA A701, a contractor submits a base bid of $480,000, Additive Alternate No. 1 for $25,000, and Deductive Alternate No. 2 for $12,000. The owner accepts the base bid and BOTH alternates. What is the initial contract amount?', '$480.000 + $25.000 (alternate aditivo) − $12.000 (alternate deductivo) = $493.000. El alternate aditivo suma el precio de un trabajo adicional definido en los documentos de licitación y el deductivo resta el de un trabajo que se elimina, y solo los alternates que el dueño acepta forman el monto inicial del contrato.', '$480,000 + $25,000 (additive alternate) − $12,000 (deductive alternate) = $493,000. The additive alternate adds the price of additional work defined in the bidding documents, and the deductive alternate subtracts the price of work that is removed; only the alternates the owner accepts form part of the initial contract amount.', 'AIA A701 · Instrucciones a los licitantes: oferta base y alternates aceptados');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (112, 1, '$443.000', '$443,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (112, 2, '$468.000', '$468,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (112, 3, '$493.000', '$493,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (112, 4, '$505.000', '$505,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (113, 1, 113, 'El contrato incluye una cláusula de escalación para el paquete de acero, valorado en $150.000 al momento de firmar. El índice publicado aplicable sube 12% antes de efectuarse la compra. ¿Cuál es el ajuste por escalación que corresponde aplicar?', 'The contract includes an escalation clause for the steel package, valued at $150,000 at the time of signing. The applicable published index rises 12% before the purchase is made. What escalation adjustment applies?', 'Ajuste = monto sujeto a escalación × variación del índice: $150.000 × 12% = $18.000, y el paquete ajustado pasa a costar $168.000. La cláusula traslada el riesgo de precio según el índice pactado en el contrato, no según la factura final del proveedor.', 'Adjustment = amount subject to escalation × index change: $150,000 × 12% = $18,000, and the adjusted package then costs $168,000. The clause shifts the price risk according to the index agreed upon in the contract, not according to the supplier''s final invoice.', 'Administración del contrato · Cláusula de ajuste por escalación de precios según índice publicado');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (113, 1, '$1.800', '$1,800', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (113, 2, '$12.000', '$12,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (113, 3, '$15.000', '$15,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (113, 4, '$18.000', '$18,000', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (114, 1, 114, 'Al día siguiente de la apertura de ofertas, el licitante más bajo descubre que, al transponer una cifra de su hoja de cálculo, omitió $60.000 de su oferta, y avisa de inmediato aportando la evidencia del error. Según el esquema de AIA A701-2018, ¿cómo se trata esta situación?', 'The day after the bid opening, the low bidder discovers that, in transposing a figure from its spreadsheet, it omitted $60,000 from its bid, and it gives notice immediately, furnishing evidence of the error. Under the AIA A701-2018 framework, how is this situation handled?', 'A701-2018 regula en su §4.4.3 el retiro de la oferta cuando el arquitecto queda razonablemente satisfecho de que hubo un error clerical, y dispone el tratamiento de la garantía de licitación en ese caso. Un error de juicio al estimar no recibe el mismo trato que un error clerical demostrable y notificado con prontitud.', 'A701-2018 addresses in its §4.4.3 the withdrawal of a bid when the architect is reasonably satisfied that a clerical error was made, and provides for the treatment of the bid security in that case. An error in judgment in estimating does not receive the same treatment as a demonstrable clerical error reported promptly.', 'AIA A701-2018 · §4.4.3 Retiro de la oferta por error clerical (guía oficial de AIA)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (114, 1, 'Si el arquitecto queda razonablemente satisfecho de que el licitante cometió un error clerical, el licitante puede retirar su oferta, y los documentos de licitación establecen qué ocurre con su garantía de licitación (bid security) en ese retiro', 'If the architect is reasonably satisfied that the bidder made a clerical error, the bidder may withdraw its bid, and the bidding documents establish what happens to its bid guarantee (bid security) upon that withdrawal', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (114, 2, 'La oferta no puede tocarse: el licitante debe firmar por el precio errado o perder automáticamente su garantía en todos los casos', 'The bid cannot be touched: the bidder must sign at the erroneous price or automatically lose its guarantee in every case', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (114, 3, 'El dueño está obligado a aceptar la oferta corregida con los $60.000 adicionales', 'The owner is required to accept the corrected bid with the additional $60,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (114, 4, 'El error se reparte: el dueño absorbe la mitad y el licitante la otra mitad', 'The error is shared: the owner absorbs one half and the bidder the other half', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (115, 1, 115, 'Una empresa pequeña busca el respaldo del programa Surety Bond Guarantee de la SBA para afianzar un contrato privado (no federal) de $7.200.000. ¿Es elegible por el monto del contrato?', 'A small firm seeks the backing of the SBA''s Surety Bond Guarantee Program to bond a private (non-federal) contract for $7,200,000. Is it eligible based on the contract amount?', 'El programa de garantía de fianzas de la SBA respalda contratos de hasta $6.500.000 cuando no son federales y hasta $10.000.000 cuando son federales. Un contrato privado de $7.200.000 supera el tope aplicable y la empresa debe buscar la fianza en el mercado estándar de afianzadoras.', 'The SBA''s Surety Bond Guarantee Program guarantees contracts of up to $6,500,000 when they are non-federal and up to $10,000,000 when they are federal. A private contract of $7,200,000 exceeds the applicable cap, and the firm must obtain the bond in the standard surety market.', 'SBA · Surety Bond Guarantee Program: límites de $6,5 millones (contratos no federales) y $10 millones (federales)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (115, 1, 'Sí: el programa cubre contratos de hasta $10.000.000 en todos los casos', 'Yes: the program covers contracts of up to $10,000,000 in every case', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (115, 2, 'Sí: para empresas de dueños desfavorecidos el tope sube a $7.500.000', 'Yes: for firms owned by socially and economically disadvantaged individuals, the cap rises to $7,500,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (115, 3, 'No: el tope del programa para contratos no federales es $6.500.000; el límite de $10.000.000 aplica a los contratos federales', 'No: the program''s cap for non-federal contracts is $6,500,000; the $10,000,000 limit applies to federal contracts', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (115, 4, 'No: el programa solo afianza contratos menores de $1.000.000', 'No: the program bonds only contracts under $1,000,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (116, 1, 116, 'Un contratista certificado publica un anuncio en una revista local y entrega propuestas a clientes, pero en ninguno de los dos aparece su número de certificado. El camión de la empresa también lleva el nombre comercial sin ese número. ¿Qué establece la ley?', 'A certified contractor publishes an advertisement in a local magazine and delivers proposals to clients, but his certificate number appears in neither. The company''s truck also bears the trade name without that number. What does the law provide?', 'La s. 489.119 exige que el número de registro o certificación aparezca en toda oferta de servicios, propuesta, licitación, contrato o anuncio, sin importar el medio, y que el vehículo que exhibe el nombre del contratista lo muestre de forma visible y legible. La propia definición legal de anuncio excluye la papelería y los artículos promocionales (novelties).', 'Section 489.119 requires the registration or certification number to appear in every offer of services, proposal, bid, contract, or advertisement, regardless of the medium, and requires the vehicle displaying the contractor''s name to show it visibly and legibly. The statutory definition of advertising itself excludes stationery and promotional items (novelties).', 'Estatutos de Florida · s. 489.119 Publicidad y exhibición del número de licencia');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (116, 1, 'El número solo es obligatorio en el contrato firmado, no en publicidad ni en propuestas', 'The number is mandatory only in the signed contract, not in advertisements or proposals', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (116, 2, 'Basta con mostrar el número cuando el cliente lo solicite', 'It is enough to show the number when the client asks for it', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (116, 3, 'La regla aplica únicamente a la papelería oficial de la empresa', 'The rule applies only to the company''s official stationery', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (116, 4, 'El número de certificación o registro debe aparecer en cada oferta de servicios, propuesta, licitación, contrato y anuncio, cualquiera sea el medio, y exhibirse de forma visible y legible en los vehículos identificados con el contratista', 'The certification or registration number must appear in every offer of services, proposal, bid, contract, and advertisement, whatever the medium, and must be displayed visibly and legibly on vehicles identified with the contractor', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (117, 1, 117, 'Un contratista certificado permite que un amigo sin licencia use su número de certificado para obtener permisos y ejecutar obras que el amigo consigue, negocia y controla por su cuenta, sin participación alguna del titular en ese negocio. ¿Cómo califica la ley esa conducta?', 'A certified contractor allows an unlicensed friend to use his certificate number to pull permits and perform work that the friend obtains, negotiates, and controls on his own, with no participation whatsoever by the certificate holder in that business. How does the law characterize that conduct?', 'La s. 489.129(1)(e) sanciona permitir que una persona no certificada use el certificado ajeno con intención de evadir el Capítulo 489, y presume esa intención cuando el titular no participa activamente en la operación del negocio. Es la conducta conocida como prestar la licencia, y expone al titular a disciplina aunque las obras queden bien hechas.', 'Section 489.129(1)(e) penalizes allowing one''s certificate to be used by an uncertified person with the intent to evade Chapter 489, and presumes that intent when the holder does not actively participate in the operation of the business. It is the conduct known as lending one''s license, and it exposes the holder to discipline even if the work is well performed.', 'Estatutos de Florida · s. 489.129(1)(e) Causales de disciplina');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (117, 1, 'Es legal si el amigo tiene experiencia y las obras pasan las inspecciones', 'It is legal if the friend is experienced and the jobs pass inspections', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (117, 2, 'Es legal mientras el titular revise los planos antes de cada permiso', 'It is legal as long as the holder reviews the plans before each permit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (117, 3, 'Es una causal de disciplina: combinarse o conspirar con una persona no certificada permitiéndole usar su certificado con intención de evadir la ley, y la falta de participación activa del titular en la operación, dirección o control es evidencia prima facie de esa intención', 'It is a ground for discipline: combining or conspiring with an uncertified person by allowing that person to use his certificate with the intent to evade Chapter 489, and the holder''s lack of active participation in the operation of the business is prima facie evidence of that intent', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (117, 4, 'Solo es infracción si algún cliente presenta una queja formal', 'It is an offense only if some client files a formal complaint', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (118, 1, 118, 'Un contratista puso su licencia en estado inactivo en la renovación. Meses después firma un contrato de remodelación y ejecuta la obra manteniendo la licencia inactiva. ¿Cuál es su situación legal?', 'A contractor placed his license in inactive status at renewal. Months later, he signs a remodeling contract and performs the work while keeping the license inactive. What is his legal situation?', 'La s. 455.271(1) establece que el licenciado puede ejercer su profesión únicamente si tiene una licencia en estado activo; practicar sin estado activo viola esa sección y la s. 455.227 y faculta a la Junta a imponer disciplina. Para volver a contratar debe reactivarla cumpliendo los cargos y la educación continua correspondientes.', 'Under s. 455.271(1), a licensee may engage in his profession only if he holds a license in active status; practicing without active status violates that section and s. 455.227 and empowers the Board to impose discipline. To resume contracting, he must reactivate it by paying the applicable fees and completing the corresponding continuing education.', 'Estatutos de Florida · s. 455.271(1) Estado inactivo y delincuente');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (118, 1, 'Viola la ley: un licenciado solo puede ejercer su profesión si tiene una licencia en estado activo, y ejercer sin ella lo expone a disciplina de la Junta', 'He is violating the law: a licensee may practice his profession only if he holds a license in active status, and practicing without one exposes him to discipline by the Board', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (118, 2, 'Es válido: la licencia inactiva solo suspende el requisito de educación continua', 'It is valid: the inactive status only suspends the continuing education requirement', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (118, 3, 'Es válido si completa la reactivación antes de terminar la obra', 'It is valid if he completes the reactivation before finishing the work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (118, 4, 'El contrato es válido, pero no podrá cobrar el pago final', 'The contract is valid, but he will not be able to collect the final payment', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (119, 1, 119, 'Una corporación contratista se disuelve y su dueño le pide al IRS que cancele el EIN de la empresa para que el número quede liberado. ¿Cuál es la respuesta correcta según el IRS?', 'A contracting corporation dissolves, and its owner asks the IRS to cancel the company''s EIN so that the number is freed up. What is the correct answer according to the IRS?', 'Según la guía del IRS sobre cancelación de un EIN y cierre de la cuenta, el IRS no puede cancelar un EIN: una vez asignado es el número federal permanente de la entidad y jamás se reutiliza ni se reasigna a otra. El cierre correcto consiste en presentar las declaraciones finales y enviar al IRS la carta de cierre con el nombre legal, el EIN, la dirección y el motivo.', 'According to the IRS guidance on canceling an EIN and closing your account, the IRS cannot cancel an EIN: once assigned, it is the entity''s permanent federal number and is never reused or reassigned to another entity. Proper closure consists of filing the final returns and sending the IRS a closure letter with the legal name, the EIN, the address, and the reason.', 'IRS · Canceling an EIN — Closing Your Account (cierre de la cuenta de negocio)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (119, 1, 'El EIN se cancela y puede reasignarse a otra empresa después de 3 años', 'The EIN is canceled and may be reassigned to another company after 3 years', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (119, 2, 'El EIN nunca se cancela ni se reutiliza: es el número federal permanente de la entidad; lo que se cierra es la cuenta de negocio ante el IRS, por carta y tras presentar las declaraciones finales', 'The EIN is never canceled or reused: it is the entity''s permanent federal number; what is closed is the business account with the IRS, by letter and after filing the final returns', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (119, 3, 'El EIN pasa automáticamente al dueño como persona natural', 'The EIN passes automatically to the owner as an individual', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (119, 4, 'El EIN lo cancela el estado de Florida al disolver la corporación', 'The EIN is canceled by the State of Florida when the corporation is dissolved', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (120, 1, 120, 'En una obra privada con contrato directo de $24.500 llega el día de la primera inspección, pero nadie presentó copia del Notice of Commencement registrado ante la autoridad que emitió el permiso ni lo exhibió en la obra. ¿Qué dispone la ley?', 'On a private project with a direct contract of $24,500, the day of the first inspection arrives, but no one filed a copy of the recorded Notice of Commencement with the authority that issued the permit, nor was it posted at the job site. What does the law provide?', 'El texto que la s. 713.135(1)(a) manda imprimir en la tarjeta del permiso lo advierte: el Notice of Commencement debe registrarse y exhibirse en el sitio antes de la primera inspección. La s. 713.135(1)(e) añade que, si el contrato directo supera $5.000, el solicitante debe presentar la copia ante la autoridad emisora antes de esa primera inspección.', 'The text that s. 713.135(1)(a) requires to be printed on the permit card warns of exactly this: the Notice of Commencement must be recorded and posted at the site before the first inspection. Section 713.135(1)(e) adds that, if the direct contract exceeds $5,000, the applicant must file the copy with the issuing authority before that first inspection.', 'Estatutos de Florida · s. 713.135(1)(a) y (e) Notice of Commencement y permisos de construcción');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (120, 1, 'El Notice of Commencement debe estar registrado y exhibido en el sitio antes de la primera inspección, y en contratos directos mayores de $5.000 el solicitante del permiso debe presentar su copia ante la autoridad emisora antes de esa inspección, por lo que la inspección no puede realizarse y el trabajo se frena', 'The Notice of Commencement must be recorded and posted at the site before the first inspection, and on direct contracts over $5,000 the permit applicant must file its copy with the issuing authority before that inspection, so the inspection cannot be held and the work is halted', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (120, 2, 'La inspección procede igual; el Notice of Commencement solo se exige en la inspección final', 'The inspection proceeds anyway; the Notice of Commencement is required only at the final inspection', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (120, 3, 'El Notice of Commencement solo se exige en contratos mayores de $100.000', 'The Notice of Commencement is required only on contracts over $100,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (120, 4, 'El contratista puede registrar el Notice of Commencement dentro de los 45 días siguientes a la inspección', 'The contractor may record the Notice of Commencement within the 45 days following the inspection', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (121, 1, 121, 'Según la Regla 61G4-15.003 del Código Administrativo de Florida, ¿cuáles son los montos mínimos de seguro que debe mantener un certified general contractor?', 'Under Rule 61G4-15.003 of the Florida Administrative Code, what are the minimum insurance amounts that a certified general contractor must maintain?', 'La Regla 61G4-15.003 fija para los contratistas de la División I (generales, de edificios y residenciales) un mínimo de $300.000 en public liability y $50.000 en property damage; los oficios de la División II tienen mínimos menores, de $100.000 y $25.000.', 'Rule 61G4-15.003 sets, for Division I contractors (general, building, and residential), a minimum of $300,000 in public liability and $50,000 in property damage; Division II trades have lower minimums, of $100,000 and $25,000.', 'Regla 61G4-15.003, F.A.C. · Public Liability Insurance');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (121, 1, '$100.000 de responsabilidad pública y $25.000 de daños a la propiedad', '$100,000 in public liability and $25,000 in property damage', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (121, 2, '$300.000 de responsabilidad pública (lesiones corporales) y $50.000 de daños a la propiedad', '$300,000 in public liability (bodily injury) and $50,000 in property damage', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (121, 3, '$500.000 de responsabilidad pública y $100.000 de daños a la propiedad', '$500,000 in public liability and $100,000 in property damage', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (121, 4, '$1.000.000 de responsabilidad pública y $500.000 de daños a la propiedad', '$1,000,000 in public liability and $500,000 in property damage', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (122, 1, 122, 'Un contratista está registrado (registered) en Florida con base en su tarjeta de competencia de Miami-Dade. Le ofrecen un trabajo en Orlando y quiere ejecutarlo con esa misma credencial. ¿Puede hacerlo?', 'A contractor is registered in Florida based on his Miami-Dade certificate of competency. He is offered a job in Orlando and wants to perform it with that same credential. Can he do so?', 'Bajo la s. 489.105, el certified contractor puede contratar en cualquier jurisdicción del estado, mientras que el registered contractor se registra con base en una competencia local y solo puede contratar en esa jurisdicción.', 'Under s. 489.105, a certified contractor may contract in any jurisdiction in the state, while a registered contractor registers based on a local competency and may only contract in that jurisdiction.', 'Estatutos de Florida, s. 489.105 · DBPR, contratistas certificados y registrados');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (122, 1, 'Sí, porque la credencial registrada la emite el estado', 'Yes, because the registered credential is issued by the state', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (122, 2, 'Sí, si notifica al condado de Orange con 30 días de anticipación', 'Yes, if he notifies Orange County 30 days in advance', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (122, 3, 'No: el contratista registrado solo puede contratar en las jurisdicciones cubiertas por su registro local; el certificado estatal (certified) es el que permite contratar en todo Florida', 'No: a registered contractor may only contract in the jurisdictions covered by his local registration; the state certified credential is what allows contracting throughout Florida', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (122, 4, 'Sí, siempre que el contrato sea menor de $75.000', 'Yes, as long as the contract is under $75,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (123, 1, 123, 'En una empresa con un acuerdo conjunto (joint agreement) aprobado por la Junta, ¿cuál es el alcance de la responsabilidad de un secondary qualifying agent según la s. 489.1195?', 'In a business organization with a joint agreement approved by the Board, what is the scope of a secondary qualifying agent''s responsibility under s. 489.1195?', 'La s. 489.1195(1)(e) limita al secondary qualifying agent a la supervisión del trabajo de campo en los sitios donde su licencia obtuvo el permiso y a lo que voluntariamente acepte, y declara expresamente que no es responsable de la supervisión de los asuntos financieros.', 'Section 489.1195(1)(e) limits the secondary qualifying agent to supervision of the field work at the sites where his license was used to obtain the permit and to what he voluntarily accepts, and expressly states that he is not responsible for supervision of financial matters.', 'Estatutos de Florida, s. 489.1195(1)(e)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (123, 1, 'Responde por todas las operaciones y finanzas de la empresa, igual que el agente primario', 'He is responsible for all operations and finances of the business, the same as the primary agent', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (123, 2, 'Responde solo por la supervisión del trabajo de campo en las obras donde su licencia se usó para obtener el permiso, y por el trabajo adicional que acepte; no responde por los asuntos financieros', 'He is responsible only for supervising field work at the job sites where his license was used to obtain the permit, and for any additional work he accepts; he is not responsible for financial matters', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (123, 3, 'No tiene responsabilidad alguna mientras exista un agente primario', 'He has no responsibility at all as long as a primary agent exists', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (123, 4, 'Responde únicamente por las finanzas de las obras que supervisa', 'He is responsible only for the finances of the jobs he supervises', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (124, 1, 124, 'Un contratista registró su nombre ficticio (fictitious name) ante la División de Corporaciones en 2026. Según la Ley de Nombres Ficticios (s. 865.09), ¿cuándo vence ese registro si no lo renueva?', 'A contractor registered his fictitious name with the Division of Corporations in 2026. Under the Fictitious Name Act (s. 865.09), when does that registration expire if he does not renew it?', 'La s. 865.09 establece que el registro del nombre ficticio vence el 31 de diciembre del quinto año calendario siguiente a su presentación (el año del registro cuenta como el primero) y debe renovarse durante ese año de vencimiento.', 'Section 865.09 provides that fictitious name registration expires on December 31 of the fifth calendar year following its filing (the year of registration counts as the first) and must be renewed during that expiration year.', 'Estatutos de Florida, s. 865.09 · Fictitious Name Act');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (124, 1, 'El 31 de diciembre de 2026', 'December 31, 2026', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (124, 2, 'El 1 de mayo de 2031', 'May 1, 2031', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (124, 3, 'El 31 de diciembre de 2030, es decir, al cierre del quinto año calendario del registro', 'December 31, 2030, that is, at the close of the fifth calendar year of the registration', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (124, 4, 'Nunca vence: el registro es permanente', 'It never expires: the registration is permanent', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (125, 1, 125, '¿Qué conjunto de características define a una corporación tipo S (S corporation)?', 'What set of characteristics defines an S corporation?', 'La S corporation elige el tratamiento del Subcapítulo S con el Formulario 2553: sus ganancias y pérdidas pasan a las declaraciones de los accionistas (sin doble tributación), pero está limitada a 100 accionistas, todos personas elegibles, y a una sola clase de acciones.', 'An S corporation elects Subchapter S treatment with Form 2553: its income and losses pass through to the shareholders'' returns (no double taxation), but it is limited to 100 shareholders, all eligible persons, and a single class of stock.', 'SBA · Choose a business structure (S corporation) · IRS, Formulario 2553');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (125, 1, 'Tributación de paso a los accionistas, máximo 100 accionistas, una sola clase de acciones y elección mediante el Formulario 2553 del IRS', 'Pass-through taxation to the shareholders, a maximum of 100 shareholders, a single class of stock, and election by IRS Form 2553', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (125, 2, 'Doble tributación, accionistas ilimitados y varias clases de acciones', 'Double taxation, unlimited shareholders, and several classes of stock', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (125, 3, 'Exención total de impuestos y propiedad abierta a corporaciones extranjeras', 'Complete tax exemption and ownership open to foreign corporations', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (125, 4, 'Tributación a nivel de la entidad y máximo 10 accionistas', 'Entity-level taxation and a maximum of 10 shareholders', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (126, 1, 126, 'Un contratista ejecuta una mejora de propiedad real con un contrato a suma alzada (lump sum). Bajo la Regla 12A-1.051 del Departamento de Rentas de Florida, ¿cómo se trata el impuesto sobre las ventas de los materiales de esa obra?', 'A contractor performs a real property improvement under a lump sum contract. Under Rule 12A-1.051 of the Florida Department of Revenue, how is the sales tax on the materials for that job treated?', 'La Regla 12A-1.051 trata al contratista de mejoras de propiedad real en contratos lump sum, cost plus o de precio garantizado como el consumidor final de los materiales y suministros: paga el sales tax en la compra y no traslada un impuesto separado al dueño.', 'Rule 12A-1.051 treats a real property improvement contractor under lump sum, cost plus, or guaranteed price contracts as the ultimate consumer of the materials and supplies: he pays the sales tax at purchase and does not pass a separate tax on to the owner.', 'Departamento de Rentas de Florida · Regla 12A-1.051, F.A.C.');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (126, 1, 'El contratista cobra el impuesto al dueño como una línea separada de la factura final', 'The contractor charges the tax to the owner as a separate line on the final invoice', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (126, 2, 'Los materiales están exentos porque se incorporan a un bien raíz', 'The materials are exempt because they are incorporated into real property', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (126, 3, 'El contratista debe registrarse y remitir el impuesto sobre el precio total del contrato', 'The contractor must register and remit tax on the total contract price', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (126, 4, 'El contratista es el consumidor final (ultimate consumer) de los materiales: paga el impuesto al comprarlos a su proveedor y no lo cobra al dueño sobre el contrato', 'The contractor is the ultimate consumer of the materials: he pays the tax when buying them from his supplier and does not charge it to the owner on the contract', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (127, 1, 127, 'El dueño de la obra sirve a un proveedor que le envió un Notice to Owner una solicitud formal de estado de cuenta jurado (Request for Sworn Statement of Account) bajo la s. 713.16. El proveedor la ignora por completo. ¿Qué consecuencia enfrenta?', 'The owner of a project serves on a supplier who sent him a Notice to Owner a formal Request for Sworn Statement of Account under s. 713.16. The supplier ignores it completely. What consequence does he face?', 'La s. 713.16(2) permite al dueño exigir por escrito un estado de cuenta bajo juramento, y dispone que la falta de entrega dentro de los 30 días, o la entrega de un estado falso o fraudulento, priva a esa persona de su lien.', 'Section 713.16(2) allows the owner to demand in writing a sworn statement of account, and provides that failure to deliver it within 30 days, or delivering a false or fraudulent statement, deprives that person of his lien.', 'Estatutos de Florida, s. 713.16(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (127, 1, 'Una multa administrativa de $500', 'An administrative fine of $500', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (127, 2, 'Pierde su derecho de lien: no entregar el estado de cuenta jurado dentro de los 30 días de la demanda, o entregar uno falso, priva al lienor de su lien', 'He loses his lien right: failing to deliver the sworn statement of account within 30 days of the demand, or delivering a false one, deprives the lienor of his lien', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (127, 3, 'Ninguna: responder es voluntario', 'None: responding is voluntary', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (127, 4, 'Su plazo para registrar el claim of lien se extiende 30 días', 'His deadline to record the claim of lien is extended by 30 days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (128, 1, 128, 'El dueño quiere obligar al lienor a ejecutar su lien o perderlo, y presenta la demanda del procedimiento sumario de la s. 713.21(4). ¿Qué debe hacer el lienor y en qué plazo?', 'The owner wants to force the lienor to enforce his lien or lose it, and files the complaint under the summary procedure of s. 713.21(4). What must the lienor do, and by when?', 'Según la s. 713.21(4), presentada la demanda, el secretario emite una citación para que el lienor muestre causa dentro de 20 días de por qué su lien no debe ser ejecutado por acción o cancelado del registro; si no muestra causa ni inicia la acción, el tribunal ordena la cancelación.', 'Under s. 713.21(4), once the complaint is filed, the clerk issues a summons for the lienor to show cause within 20 days why his lien should not be enforced by action or discharged from the record; if he neither shows cause nor begins the action, the court orders the cancellation of the lien.', 'Estatutos de Florida, s. 713.21(4)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (128, 1, 'Mostrar causa dentro de 20 días de la citación (summons) de por qué su lien no debe cancelarse, o comenzar la acción de ejecución antes de esa fecha; si no lo hace, el tribunal ordena la cancelación del lien', 'Show cause within 20 days of the summons why his lien should not be enforced by action or discharged from the record; if he does not show cause or begin the action, the court orders the lien discharged', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (128, 2, 'Presentar su demanda dentro de 1 año, como en el procedimiento ordinario', 'File his lawsuit within 1 year, as in the ordinary procedure', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (128, 3, 'Depositar una fianza por el doble del monto del lien dentro de 45 días', 'Post a bond for double the amount of the lien within 45 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (128, 4, 'Responder solo si el juez fija una audiencia dentro de 90 días', 'Respond only if the judge sets a hearing within 90 days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (129, 1, 129, 'La obra terminó, todos los lienors cobraron por completo y el dueño quiere cerrar el período de vigencia del Notice of Commencement registrando un Notice of Termination bajo la s. 713.132. ¿Cuál afirmación es correcta?', 'The work is finished, all lienors have been paid in full, and the owner wants to close out the effective period of the Notice of Commencement by recording a Notice of Termination under s. 713.132. Which statement is correct?', 'La s. 713.132 exige que el Notice of Termination sea jurado y registrado por el dueño, que la terminación no sea efectiva antes de 30 días tras su registro, que solo procede tras la terminación de la obra o su cese con todos los lienors pagados, y que lo acompañe el contractor''s affidavit.', 'Section 713.132 requires that the Notice of Termination be sworn and recorded by the owner, that the termination not be effective until 30 days after its recording, that it proceed only after termination of the work or its cessation with all lienors paid, and that it be accompanied by the contractor''s affidavit.', 'Estatutos de Florida, s. 713.132');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (129, 1, 'El aviso de terminación es efectivo el mismo día en que se registra', 'The notice of termination is effective the same day it is recorded', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (129, 2, 'Puede registrarse en cualquier momento, aunque queden lienors sin pagar', 'It may be recorded at any time, even if lienors remain unpaid', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (129, 3, 'La fecha de terminación no puede ser anterior a 30 días después del registro del aviso de terminación, y el aviso debe ir acompañado del affidavit del contratista', 'The termination date cannot be earlier than 30 days after the notice of termination is recorded, and the notice must be accompanied by the contractor''s affidavit', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (129, 4, 'Solo el contratista puede registrar el aviso de terminación', 'Only the contractor may record the notice of termination', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (130, 1, 130, 'En un proyecto privado, el contratista otorga una payment bond bajo la s. 713.23, por un monto al menos igual al precio del contrato, y la copia de la fianza se adjunta al Notice of Commencement registrado. ¿Cuál es el efecto principal para la propiedad y para los subcontratistas?', 'On a private project, the contractor furnishes a payment bond under s. 713.23, in an amount at least equal to the contract price, and a copy of the bond is attached to the recorded Notice of Commencement. What is the main effect for the property and for the subcontractors?', 'La s. 713.23 permite eximir la propiedad del dueño de los liens cuando el contratista aporta una payment bond suficiente (al menos el precio del contrato) registrada con el Notice of Commencement; los lienors conservan su protección reclamando contra esa fianza.', 'Section 713.23 allows the owner''s property to be exempted from liens when the contractor furnishes a sufficient payment bond (at least the contract price) recorded with the Notice of Commencement; lienors retain their protection by claiming against that bond.', 'Estatutos de Florida, s. 713.23');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (130, 1, 'La propiedad queda exenta de los construction liens y el remedio de los lienors se traslada a reclamar contra la fianza', 'The property is exempt from construction liens and the lienors'' remedy shifts to claiming against the bond', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (130, 2, 'Los subcontratistas pierden todo derecho de cobro', 'Subcontractors lose all right to collect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (130, 3, 'La propiedad sigue sujeta a liens, pero el dueño gana un año adicional de plazo', 'The property remains subject to liens, but the owner gains an additional year of time', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (130, 4, 'La fianza sustituye al seguro de responsabilidad civil del contratista', 'The bond replaces the contractor''s liability insurance', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (131, 1, 131, 'En ese mismo proyecto privado afianzado bajo la s. 713.23, un subcontratista que SÍ tiene contrato directo con el contratista principal (está en privity) termina su trabajo y no le pagan. Como condición para cobrar contra la fianza, ¿qué aviso debe servir y cuándo?', 'On that same private project bonded under s. 713.23, a subcontractor who DOES have a direct contract with the prime contractor (is in privity) finishes his work and is not paid. As a condition to collecting against the bond, what notice must he serve, and when?', 'Bajo la s. 713.23(1)(d), todo lienor, incluido el que está en privity con el contratista, debe servir el aviso de no pago al contratista y a la afianzadora dentro de los 90 días de su última aportación como condición previa para recuperar contra la fianza, y demandar dentro del año.', 'Under s. 713.23(1)(d), every lienor, including one in privity with the contractor, must serve the notice of nonpayment on the contractor and the surety within 90 days of his last furnishing as a condition precedent to recovering against the bond, and sue within the year.', 'Estatutos de Florida, s. 713.23(1)(d) y (e)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (131, 1, 'Ninguno: quien está en privity cobra de la fianza automáticamente', 'None: anyone in privity collects from the bond automatically', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (131, 2, 'Un Notice to Owner al dueño dentro de 45 días', 'A Notice to Owner to the owner within 45 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (131, 3, 'El aviso de no pago (Notice of Nonpayment) al contratista y a la afianzadora, a más tardar 90 días después de su última aportación de trabajo o materiales', 'The Notice of Nonpayment to the contractor and the surety, no later than 90 days after his last furnishing of labor or materials', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (131, 4, 'Un claim of lien contra la propiedad dentro de 90 días', 'A claim of lien against the property within 90 days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (132, 1, 132, 'Un contratista recibe un pago por avance del dueño y, en vez de pagar lo que ya debe a los subcontratistas y proveedores de esa obra, usa el dinero para cubrir la nómina de otro proyecto y gastos personales, sabiendo que deja sin pagar lo adeudado por la primera obra. ¿Cómo trata la s. 713.345 esa conducta?', 'A contractor receives a progress payment from the owner and, instead of paying what he already owes the subcontractors and suppliers on that job, uses the money to cover payroll on another project and personal expenses, knowing he is leaving unpaid what is owed on the first job. How does s. 713.345 treat that conduct?', 'La s. 713.345(1) obliga a aplicar cada pago recibido por una mejora de propiedad real a los montos vencidos por el trabajo y los materiales de esa misma mejora, y castiga el incumplimiento consciente e intencional como delito grave, con la gravedad escalada según el monto total aplicado indebidamente.', 'Section 713.345(1) requires each payment received for a real property improvement to be applied to the amounts due for the labor and materials of that same improvement, and punishes knowing and intentional noncompliance as a felony, with the severity graded according to the total amount improperly applied.', 'Estatutos de Florida, s. 713.345(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (132, 1, 'Es solo un incumplimiento de contrato sin consecuencia penal', 'It is merely a breach of contract with no criminal consequence', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (132, 2, 'Es una infracción administrativa que resuelve el DBPR con una amonestación', 'It is an administrative violation that DBPR resolves with a reprimand', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (132, 3, 'Es lícita mientras el contratista eventualmente pague', 'It is lawful as long as the contractor eventually pays', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (132, 4, 'Es aplicación indebida de fondos de construcción (misapplication of construction funds): quien recibe un pago por una mejora debe aplicarlo primero a lo adeudado por los servicios, el trabajo y los materiales de esa mejora, y no hacerlo a sabiendas es un delito grave (felony) graduado por el monto', 'It is misapplication of construction funds: anyone who receives a payment for an improvement must apply it first to what is owed for the services, labor, and materials of that improvement, and knowingly failing to do so is a felony graded by the amount', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (133, 1, 133, 'Una constructora de Florida contrata a un carpintero que empieza a trabajar hoy. ¿Dentro de qué plazo debe reportarlo al Directorio Estatal de Nuevos Empleados (State Directory of New Hires) según la s. 409.2576?', 'A Florida construction company hires a carpenter who starts work today. Within what period must it report him to the State Directory of New Hires under s. 409.2576?', 'La s. 409.2576 obliga a todo empleador de Florida a reportar a cada empleado nuevo o recontratado al State Directory of New Hires, administrado por el Departamento de Rentas, dentro de los 20 días de la fecha de contratación.', 'Section 409.2576 requires every Florida employer to report each newly hired or rehired employee to the State Directory of New Hires, administered by the Department of Revenue, within 20 days of the date of hire.', 'Estatutos de Florida, s. 409.2576 · Florida New Hire Reporting Center');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (133, 1, 'Dentro de 20 días de la fecha de contratación', 'Within 20 days of the date of hire', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (133, 2, 'Dentro de 45 días de la fecha de contratación', 'Within 45 days of the date of hire', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (133, 3, 'Al presentar la declaración trimestral RT-6 siguiente', 'When filing the next quarterly RT-6 return', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (133, 4, 'Solo si el empleado tiene una orden de manutención de menores', 'Only if the employee has a child support order', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (134, 1, 134, 'Una constructora privada de Florida tiene 32 empleados y contrata a un operador nuevo. Según la s. 448.095, ¿qué debe hacer respecto a la elegibilidad de empleo del nuevo trabajador?', 'A private Florida construction company has 32 employees and hires a new operator. Under s. 448.095, what must it do regarding the new worker''s employment eligibility?', 'La s. 448.095 exige a los empleadores privados con 25 o más empleados usar E-Verify para confirmar la elegibilidad de cada nuevo empleado dentro de los 3 días laborables posteriores a su primer día de trabajo por paga; los empleadores públicos y sus contratistas deben usarlo sin importar su tamaño.', 'Section 448.095 requires private employers with 25 or more employees to use E-Verify to confirm the eligibility of each new employee within 3 business days after his first day of work for pay; public employers and their contractors must use it regardless of size.', 'Estatutos de Florida, s. 448.095');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (134, 1, 'Nada adicional: el Formulario I-9 basta para todo empleador privado', 'Nothing additional: Form I-9 is enough for every private employer', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (134, 2, 'Debe verificar su elegibilidad usando el sistema federal E-Verify dentro de los 3 días laborables siguientes a su primer día de trabajo remunerado, porque el mandato alcanza a los empleadores privados con 25 o más empleados', 'It must verify his eligibility using the federal E-Verify system within 3 business days after his first day of work for pay, because the mandate reaches private employers with 25 or more employees', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (134, 3, 'Debe reportarlo al DBPR dentro de 30 días', 'It must report him to DBPR within 30 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (134, 4, 'Debe verificarlo con E-Verify solo si trabajará en obra pública', 'It must verify him with E-Verify only if he will work on public projects', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (135, 1, 135, 'El presidente de una corporación de construcción quiere excluirse de la cobertura de workers'' compensation con un certificado de exención. ¿Qué requisitos especiales impone la industria de la construcción bajo el Capítulo 440?', 'The president of a construction corporation wants to exclude himself from workers'' compensation coverage with a certificate of exemption. What special requirements does the construction industry impose under Chapter 440?', 'En la construcción, la exención de la s. 440.05 solo está disponible para oficiales corporativos (o miembros de LLC) que figuren ante la División de Corporaciones y posean al menos el 10% de la empresa, con un máximo de tres exentos por corporación, un costo de $50 y una vigencia de 2 años.', 'In construction, the exemption under s. 440.05 is available only to corporate officers (or LLC members) who are on file with the Division of Corporations and own at least 10% of the business, with a maximum of three exempt per corporation, a cost of $50, and a duration of 2 years.', 'Estatutos de Florida, s. 440.05 · División de Workers'' Compensation de Florida');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (135, 1, 'Ninguno: cualquier empleado puede eximirse firmando una renuncia', 'None: any employee can exempt himself by signing a waiver', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (135, 2, 'Debe renunciar a la empresa y trabajar como contratista independiente', 'He must resign from the company and work as an independent contractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (135, 3, 'Debe ser oficial registrado ante la División de Corporaciones y poseer al menos el 10% de las acciones, no puede haber más de tres oficiales exentos por corporación, el certificado cuesta $50 y dura 2 años', 'He must be an officer registered with the Division of Corporations and own at least 10% of the stock, there may be no more than three exempt officers per corporation, the certificate costs $50 and lasts 2 years', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (135, 4, 'Debe tener al menos 10 años de experiencia en la construcción', 'He must have at least 10 years of experience in construction', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (136, 1, 136, 'Un subcontratista se niega a entregar su Formulario W-9 y nunca proporciona su número de identificación tributaria (TIN) al contratista que le paga. ¿Qué debe hacer el pagador según las reglas del IRS?', 'A subcontractor refuses to provide his Form W-9 and never furnishes his taxpayer identification number (TIN) to the contractor who pays him. What must the payer do under IRS rules?', 'Bajo la s. 3406 del Código de Rentas Internas, si el beneficiario no suministra su TIN correcto, el pagador debe practicar backup withholding del 24% sobre los pagos reportables y remitirlo al IRS (se declara en el Formulario 945); el pagador que no retiene responde personalmente por ese impuesto.', 'Under s. 3406 of the Internal Revenue Code, if the payee does not furnish his correct TIN, the payer must apply backup withholding of 24% on reportable payments and remit it to the IRS (reported on Form 945); the payer who fails to withhold is personally liable for that tax.', 'IRS · Publicación 15 y s. 3406 del IRC (backup withholding)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (136, 1, 'Pagarle el 100% y reportar el problema al final del año', 'Pay him 100% and report the problem at the end of the year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (136, 2, 'Retener el pago completo hasta que entregue el W-9', 'Withhold the entire payment until he delivers the W-9', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (136, 3, 'Pagarle en efectivo para evitar el reporte', 'Pay him in cash to avoid the reporting', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (136, 4, 'Aplicar la retención de respaldo (backup withholding) del 24% sobre cada pago y remitirla al IRS', 'Apply backup withholding of 24% on each payment and remit it to the IRS', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (137, 1, 137, 'Una ciudad de Florida recibe una solicitud de pago apropiada por servicios de construcción ya aprobada. Bajo la Ley de Pago Puntual de los Gobiernos Locales (s. 218.735), ¿cuándo vence el pago?', 'A Florida city receives a proper payment request for construction services that has already been approved. Under the Local Government Prompt Payment Act (s. 218.735), when is payment due?', 'La s. 218.735 fija el vencimiento del pago por servicios de construcción de una entidad gubernamental local en 20 días laborables contados desde que la solicitud de pago apropiada se recibe sellada (y, cuando aplica, desde su aprobación por el arquitecto o ingeniero del proyecto).', 'Section 218.735 sets the due date for payment for construction services to a local governmental entity at 20 business days counted from when the proper payment request is received date-stamped (and, where applicable, from its approval by the project''s architect or engineer).', 'Estatutos de Florida, s. 218.735 · Local Government Prompt Payment Act');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (137, 1, 'A los 20 días laborables de recibida y aprobada la solicitud de pago', '20 business days after the payment request is received and approved', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (137, 2, 'A los 90 días calendario de recibida la factura', '90 calendar days after receiving the invoice', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (137, 3, 'Al cierre del año fiscal de la ciudad', 'At the close of the city''s fiscal year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (137, 4, 'Solo cuando el contratista presenta la liberación final de liens', 'Only when the contractor files the final release of liens', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (138, 1, 138, 'La nómina anual sujeta a FICA de una constructora es $60.000 y todos los empleados están por debajo del tope salarial del Seguro Social. ¿Cuánto paga el empleador por su propia porción de FICA (Seguro Social 6,2% y Medicare 1,45%)?', 'A construction company''s annual payroll subject to FICA is $60,000 and all employees are below the Social Security wage base. How much does the employer pay for its own share of FICA (Social Security 6.2% and Medicare 1.45%)?', 'La porción del empleador es 6,2% + 1,45% = 7,65%. Sobre $60.000 de salarios: 60.000 × 0,0765 = $4.590. Es un costo del empleador adicional al salario, separado de la porción igual que retiene al empleado.', 'The employer''s share is 6.2% + 1.45% = 7.65%. On $60,000 in wages: 60,000 × 0.0765 = $4,590. It is a cost of the employer in addition to the salary, separate from the equal share withheld from the employee.', 'IRS · Publicación 15 (Circular E), tasas FICA del empleador');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (138, 1, '$3.720', '$3,720', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (138, 2, '$4.590', '$4,590', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (138, 3, '$7.650', '$7,650', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (138, 4, '$9.180', '$9,180', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (139, 1, 139, 'A un subcontratista que no ha suministrado su TIN se le debe un pago de $10.000 por trabajo terminado. ¿Cuánto debe retener el contratista por backup withholding y cuánto paga neto al subcontratista?', 'A subcontractor who has not furnished his TIN is owed a payment of $10,000 for completed work. How much must the contractor withhold for backup withholding and how much does he pay the subcontractor net?', 'Backup withholding = 24% × 10.000 = $2.400, que se remite al IRS. El subcontratista recibe neto 10.000 − 2.400 = $7.600 y reclama lo retenido como crédito al presentar su declaración.', 'Backup withholding = 24% × 10,000 = $2,400, which is remitted to the IRS. The subcontractor receives net 10,000 − 2,400 = $7,600 and claims the withheld amount as a credit when filing his return.', 'IRS · Backup withholding, tasa del 24% (s. 3406 del IRC)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (139, 1, 'Retiene $600 y paga $9.400', 'He withholds $600 and pays $9,400', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (139, 2, 'Retiene $1.000 y paga $9.000', 'He withholds $1,000 and pays $9,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (139, 3, 'Retiene $2.400 y paga $7.600', 'He withholds $2,400 and pays $7,600', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (139, 4, 'Retiene $3.000 y paga $7.000', 'He withholds $3,000 and pays $7,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (140, 1, 140, 'Una constructora operó todo el año sin el seguro de workers'' compensation exigido. La prima que habría pagado por ese período de 12 meses era $18.500. ¿Cuál es la penalidad que impone la s. 440.107, además de la orden de paralización (stop-work order)?', 'A construction company operated all year without the required workers'' compensation insurance. The premium it would have paid for that 12-month period was $18,500. What penalty does s. 440.107 impose, in addition to the stop-work order?', 'La s. 440.107(7) ordena una penalidad igual a 2 veces la prima que el empleador habría pagado durante el período sin cobertura dentro de los 12 meses anteriores, o $1.000, lo que sea mayor: 2 × 18.500 = $37.000, además de la stop-work order inmediata.', 'Section 440.107(7) orders a penalty equal to 2 times the premium the employer would have paid during the period without coverage within the preceding 12 months, or $1,000, whichever is greater: 2 × 18,500 = $37,000, in addition to the immediate stop-work order.', 'Estatutos de Florida, s. 440.107(7)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (140, 1, '$1.000 fijos', 'A flat $1,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (140, 2, '$18.500, el equivalente a la prima omitida', '$18,500, the equivalent of the omitted premium', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (140, 3, '$9.250, la mitad de la prima omitida', '$9,250, half of the omitted premium', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (140, 4, '$37.000: el doble de la prima que habría pagado en los 12 meses anteriores (o $1.000, lo que sea mayor)', '$37,000: double the premium it would have paid in the preceding 12 months (or $1,000, whichever is greater)', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (141, 1, 141, 'Para una obra a suma alzada, el contratista compra materiales por $60.000 a su proveedor. Siendo el consumidor final de esos materiales y aplicando la tasa estatal de impuesto sobre las ventas del 6%, ¿cuánto impuesto paga el contratista en la compra?', 'For a lump sum job, the contractor buys materials for $60,000 from his supplier. As the ultimate consumer of those materials and applying the state sales tax rate of 6%, how much tax does the contractor pay on the purchase?', 'Como ultimate consumer bajo la Regla 12A-1.051, el contratista paga el sales tax al comprar los materiales: 60.000 × 6% = $3.600. Ese impuesto es un costo suyo que incorpora a su precio, no un cargo separado al dueño.', 'As ultimate consumer under Rule 12A-1.051, the contractor pays the sales tax when purchasing the materials: 60,000 × 6% = $3,600. That tax is a cost of his that he builds into his price, not a separate charge to the owner.', 'Departamento de Rentas de Florida · Regla 12A-1.051 e impuesto estatal del 6% (Cap. 212)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (141, 1, '$3.600, que paga a su proveedor como parte del costo de los materiales', '$3,600, which he pays to his supplier as part of the cost of the materials', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (141, 2, '$0: los materiales para construcción están exentos', '$0: materials for construction are exempt', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (141, 3, '$3.600, que cobra después al dueño en la factura final', '$3,600, which he later charges to the owner in the final invoice', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (141, 4, '$6.000, a la tasa del 10% para construcción', '$6,000, at the 10% rate for construction', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (142, 1, 142, 'Un equipo costó $80.000, tiene vida útil de 5 años y la empresa usa el método de doble saldo decreciente (double-declining balance). ¿Cuál es la depreciación del primer año?', 'A piece of equipment cost $80,000, has a useful life of 5 years, and the company uses the double-declining balance method. What is the depreciation for the first year?', 'La tasa de línea recta es 1 ÷ 5 = 20%; el doble es 40%. El método se aplica sobre el valor en libros y no resta el valor residual al inicio: 80.000 × 40% = $32.000 el primer año.', 'The straight-line rate is 1 ÷ 5 = 20%; double is 40%. The method is applied on the book value and does not subtract the salvage value at the start: 80,000 × 40% = $32,000 in the first year.', 'OpenStax · Principles of Accounting 11.3 (métodos de depreciación)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (142, 1, '$16.000', '$16,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (142, 2, '$32.000', '$32,000', 1);
