INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (143, 1, 143, 'Una planta de asfalto costó $110.000, su valor residual es $10.000 y se espera que produzca 200.000 toneladas en su vida útil. Este año produjo 30.000 toneladas. Por el método de unidades de producción, la depreciación del año es:', 'An asphalt plant cost $110,000, its salvage value is $10,000, and it is expected to produce 200,000 tons over its useful life. This year it produced 30,000 tons. Under the units-of-production method, the depreciation for the year is:', 'Costo depreciable = 110.000 − 10.000 = $100.000. Tarifa por tonelada = 100.000 ÷ 200.000 = $0,50. Depreciación del año = 30.000 × 0,50 = $15.000.', 'Depreciable cost = 110,000 − 10,000 = $100,000. Rate per ton = 100,000 ÷ 200,000 = $0.50. Depreciation for the year = 30,000 × 0.50 = $15,000.', 'OpenStax · Principles of Accounting 11.3 (unidades de producción)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (143, 1, '$10.000', '$10,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (143, 2, '$16.500', '$16,500', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (143, 3, '$15.000', '$15,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (143, 4, '$13.750', '$13,750', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (144, 1, 144, 'Una constructora inicia el año con utilidades retenidas de $185.000, obtiene una utilidad neta de $96.000 y distribuye $40.000 a sus dueños. ¿Cuál es el saldo final de utilidades retenidas?', 'A construction company begins the year with retained earnings of $185,000, earns net income of $96,000, and distributes $40,000 to its owners. What is the ending retained earnings balance?', 'Utilidades retenidas finales = saldo inicial + utilidad neta − distribuciones = 185.000 + 96.000 − 40.000 = $241.000. Las distribuciones a los dueños reducen el patrimonio acumulado, no son un gasto del período.', 'Ending retained earnings = beginning balance + net income − distributions = 185,000 + 96,000 − 40,000 = $241,000. Distributions to owners reduce accumulated equity; they are not an expense of the period.', 'Builder''s Guide to Accounting · Estado de cambios en el patrimonio');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (144, 1, '$129.000', '$129,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (144, 2, '$281.000', '$281,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (144, 3, '$321.000', '$321,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (144, 4, '$241.000', '$241,000', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (145, 1, 145, 'Una constructora mantiene un préstamo de construcción de $500.000 a una tasa de interés simple anual del 9%. ¿Cuánto interés se acumula en 4 meses?', 'A construction company carries a construction loan of $500,000 at a simple annual interest rate of 9%. How much interest accrues in 4 months?', 'Interés simple = capital × tasa × tiempo = 500.000 × 9% × (4 ÷ 12) = 500.000 × 0,09 × 0,3333 = $15.000. Los $45.000 serían el interés de un año completo.', 'Simple interest = principal × rate × time = 500,000 × 9% × (4 ÷ 12) = 500,000 × 0.09 × 0.3333 = $15,000. The $45,000 would be the interest for a full year.', 'Builder''s Guide to Accounting · Interés simple sobre préstamos de construcción');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (145, 1, '$15.000', '$15,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (145, 2, '$45.000', '$45,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (145, 3, '$11.250', '$11,250', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (145, 4, '$3.750', '$3,750', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (146, 1, 146, 'En una semana, la nómina bruta de campo de una obra es $1.000. El empleador paga además FICA de 7,65% sobre esos salarios y workers'' compensation a una tarifa de $6,00 por cada $100 de nómina. ¿Cuál es el costo total de mano de obra de esa semana para el empleador?', 'In one week, the gross field payroll for a job is $1,000. The employer also pays FICA of 7.65% on those wages and workers'' compensation at a rate of $6.00 per $100 of payroll. What is the total labor cost for that week for the employer?', 'Cargas del empleador: FICA 7,65% × 1.000 = $76,50 y workers'' comp (1.000 ÷ 100) × 6,00 = $60,00. Costo total = 1.000 + 76,50 + 60,00 = $1.136,50. Esa diferencia entre el salario y el costo real es la carga laboral (labor burden).', 'Employer burdens: FICA 7.65% × 1,000 = $76.50 and workers'' comp (1,000 ÷ 100) × 6.00 = $60.00. Total cost = 1,000 + 76.50 + 60.00 = $1,136.50. That difference between the wage and the real cost is the labor burden.', 'Builder''s Guide to Accounting · Carga laboral (labor burden)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (146, 1, '$1.076,50', '$1,076.50', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (146, 2, '$1.136,50', '$1,136.50', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (146, 3, '$1.060,00', '$1,060.00', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (146, 4, '$1.765,00', '$1,765.00', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (147, 1, 147, 'Al cierre del año, el overhead real de la empresa fue $120.000, pero el overhead aplicado a las obras con la tasa predeterminada sumó solo $108.000. ¿Qué significa la diferencia y cómo se trata?', 'At year-end, the company''s actual overhead was $120,000, but the overhead applied to the jobs with the predetermined rate totaled only $108,000. What does the difference mean and how is it treated?', 'Aplicado (108.000) menor que real (120.000) significa overhead subaplicado de $12.000: las obras absorbieron menos indirectos de los que realmente costaron, así que la diferencia se ajusta contra el costo de construcción del período.', 'Applied (108,000) less than actual (120,000) means underapplied overhead of $12,000: the jobs absorbed less indirect cost than was actually incurred, so the difference is adjusted against the cost of construction for the period.', 'Builder''s Guide to Accounting · Job costing, overhead subaplicado y sobreaplicado');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (147, 1, 'Hay overhead sobreaplicado de $12.000 que se suma a la utilidad', 'There is overapplied overhead of $12,000 that is added to income', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (147, 2, 'Hay un error de nómina de $12.000 que se investiga el año siguiente', 'There is a payroll error of $12,000 that is investigated the following year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (147, 3, 'Hay overhead subaplicado de $12.000 que se carga al costo de construcción, reduciendo la utilidad bruta del período', 'There is underapplied overhead of $12,000 that is charged to the cost of construction, reducing the gross profit for the period', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (147, 4, 'La diferencia se ignora porque la tasa era predeterminada', 'The difference is ignored because the rate was predetermined', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (148, 1, 148, 'En una obra, el valor ganado (earned value) es $240.000 pero el costo real incurrido es $300.000. Su índice de desempeño de costo (CPI = EV ÷ AC) es:', 'On a job, the earned value is $240,000 but the actual cost incurred is $300,000. Its cost performance index (CPI = EV ÷ AC) is:', 'CPI = 240.000 ÷ 300.000 = 0,80. Un CPI menor de 1 indica sobrecosto: el trabajo realmente avanzado vale menos que lo que costó producirlo.', 'CPI = 240,000 ÷ 300,000 = 0.80. A CPI below 1 indicates cost overrun: the work actually accomplished is worth less than what it cost to produce it.', 'Administración de proyectos · Análisis del valor ganado (fuente educativa abierta)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (148, 1, '1,25, y la obra va por debajo del presupuesto', '1.25, and the job is under budget', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (148, 2, '1,00, y la obra va exactamente en presupuesto', '1.00, and the job is exactly on budget', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (148, 3, '0,60, y la obra va muy por encima del presupuesto', '0.60, and the job is well over budget', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (148, 4, '0,80, y la obra va por encima del presupuesto: por cada dólar gastado solo se ganan $0,80 de valor', '0.80, and the job is over budget: for every dollar spent, only $0.80 of value is earned', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (149, 1, 149, 'El backlog de contratos firmados por ejecutar de una constructora suma $1.800.000 y la empresa espera en ellos su margen bruto histórico del 15%. ¿Cuánta utilidad bruta espera generar ese backlog?', 'A construction company''s backlog of signed contracts to be performed totals $1,800,000 and the company expects on them its historical gross margin of 15%. How much gross profit does that backlog expect to generate?', 'Utilidad bruta esperada del backlog = 1.800.000 × 15% = $270.000. Proyectar la ganancia contenida en el trabajo contratado es una medida básica de la salud financiera y de la capacidad que evalúan bancos y afianzadoras.', 'Expected gross profit from the backlog = 1,800,000 × 15% = $270,000. Projecting the profit contained in contracted work is a basic measure of financial health and of the capacity that banks and sureties evaluate.', 'Builder''s Guide to Accounting · Análisis de backlog y proyecciones');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (149, 1, '$270.000', '$270,000', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (149, 2, '$180.000', '$180,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (149, 3, '$120.000', '$120,000', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (149, 4, '$300.000', '$300,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (150, 1, 150, 'Un proveedor ofrece términos 2/10, neto 30 sobre una factura de materiales de $25.000. Si el contratista paga el día 10, ¿cuánto paga?', 'A supplier offers terms of 2/10, net 30 on a materials invoice of $25,000. If the contractor pays on day 10, how much does he pay?', '2/10, neto 30 significa 2% de descuento si se paga en 10 días y el total vence a los 30. Descuento = 25.000 × 2% = $500; pago neto = 25.000 − 500 = $24.500.', '2/10, net 30 means a 2% discount if paid in 10 days and the full amount due in 30. Discount = 25,000 × 2% = $500; net payment = 25,000 − 500 = $24,500.', 'Práctica comercial estándar · Términos de descuento por pronto pago (fuente educativa abierta de contabilidad)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (150, 1, '$25.000, porque el descuento aplica solo a compras en efectivo', '$25,000, because the discount applies only to cash purchases', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (150, 2, '$24.500: aprovecha el descuento del 2% ($500) por pagar dentro de los 10 días', '$24,500: he takes advantage of the 2% discount ($500) for paying within 10 days', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (150, 3, '$22.500: el descuento es del 10%', '$22,500: the discount is 10%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (150, 4, '$24.000: el descuento es de $1.000', '$24,000: the discount is $1,000', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (151, 2, 151, '¿Qué contiene el documento AIA A201?', 'What does the AIA A201 document contain?', 'El A201-2017 son las General Conditions of the Contract for Construction: define roles, pagos, cambios, reclamos y terminación entre dueño, arquitecto y contratista.', 'The A201-2017 is the General Conditions of the Contract for Construction: it defines roles, payments, changes, claims and termination among the owner, architect and contractor.', 'AIA A201-2017');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (151, 1, 'El acuerdo entre contratista y subcontratista', 'The agreement between contractor and subcontractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (151, 2, 'Las instrucciones a los licitantes', 'The instructions to bidders', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (151, 3, 'Las Condiciones Generales del Contrato para la Construcción', 'The General Conditions of the Contract for Construction', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (151, 4, 'El formulario de solicitud de pago', 'The payment application form', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (152, 2, 152, 'El documento AIA A401 se utiliza para formalizar:', 'The AIA A401 document is used to formalize:', 'El A401-2017 es el Standard Form of Agreement Between Contractor and Subcontractor. No confundirlo con el A201 (condiciones generales) ni con el A701 (instrucciones a licitantes).', 'The A401-2017 is the Standard Form of Agreement Between Contractor and Subcontractor. Do not confuse it with the A201 (general conditions) or the A701 (instructions to bidders).', 'AIA A401-2017');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (152, 1, 'La relación entre el dueño y el arquitecto', 'The relationship between the owner and the architect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (152, 2, 'El acuerdo entre el contratista y el subcontratista', 'The agreement between the contractor and the subcontractor', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (152, 3, 'Las instrucciones a los licitantes', 'The instructions to bidders', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (152, 4, 'El aviso de inicio de obra', 'The notice of commencement of the work', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (153, 2, 153, '¿A qué documento AIA corresponde el A701-2018?', 'To what AIA document does the A701-2018 correspond?', 'El A701-2018 son las Instructions to Bidders: reglas del proceso de licitación, formularios de propuesta y requisitos para los oferentes.', 'The A701-2018 is the Instructions to Bidders: rules of the bidding process, proposal forms and requirements for bidders.', 'AIA A701-2018');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (153, 1, 'Instructions to Bidders (instrucciones a los licitantes)', 'Instructions to Bidders', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (153, 2, 'General Conditions of the Contract', 'General Conditions of the Contract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (153, 3, 'Agreement Between Owner and Contractor', 'Agreement Between Owner and Contractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (153, 4, 'Standard Form of Agreement Between Contractor and Subcontractor', 'Standard Form of Agreement Between Contractor and Subcontractor', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (154, 2, 154, 'Para que una Change Order sea válida según el A201, debe estar firmada por:', 'For a Change Order to be valid under the A201, it must be signed by:', 'Una Change Order es un acuerdo escrito de cambio de alcance, precio o tiempo firmado por dueño, arquitecto y contratista. Si falta el acuerdo en precio o tiempo, el instrumento correcto es la Construction Change Directive.', 'A Change Order is a written agreement changing the scope, price or time, signed by the owner, architect and contractor. If agreement on price or time is missing, the correct instrument is the Construction Change Directive.', 'AIA A201-2017, Artículo 7');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (154, 1, 'Solo el contratista', 'The contractor only', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (154, 2, 'El dueño y el contratista únicamente', 'The owner and the contractor only', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (154, 3, 'El dueño, el arquitecto y el contratista', 'The owner, the architect and the contractor', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (154, 4, 'El subcontratista afectado y el contratista', 'The affected subcontractor and the contractor', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (155, 2, 155, '¿Qué es una Construction Change Directive?', 'What is a Construction Change Directive?', 'La Change Directive permite ordenar el cambio y seguir la obra cuando dueño y contratista aún no acuerdan el ajuste de precio o de plazo; el ajuste se resuelve después por los métodos del A201.', 'The Change Directive makes it possible to order the change and continue the work when the owner and contractor have not yet agreed on the price or time adjustment; the adjustment is resolved later by the methods of the A201.', 'AIA A201-2017, Artículo 7');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (155, 1, 'Una orden del dueño y el arquitecto de ejecutar un cambio aunque aún no haya acuerdo sobre precio o tiempo', 'An order from the owner and the architect to perform a change even though there is not yet agreement on price or time', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (155, 2, 'El documento de cierre del contrato', 'The contract closeout document', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (155, 3, 'La lista de partidas pendientes al final de la obra', 'The list of pending items at the end of the work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (155, 4, 'Una solicitud de información sobre los planos', 'A request for information about the drawings', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (156, 2, 156, 'Se alcanza el Substantial Completion cuando:', 'Substantial Completion is reached when:', 'Substantial completion es la etapa en que la obra (o una parte designada) está suficientemente completa para que el dueño la ocupe o la use según su propósito. Desde esa fecha corren garantías y se emite el certificado correspondiente.', 'Substantial completion is the stage at which the work (or a designated portion) is sufficiently complete for the owner to occupy it or use it for its intended purpose. Warranties run from that date and the corresponding certificate is issued.', 'AIA A201-2017, Artículo 9');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (156, 1, 'Se firma el contrato de construcción', 'The construction contract is signed', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (156, 2, 'La obra puede ocuparse o usarse para el propósito para el que fue construida', 'The work can be occupied or used for the purpose for which it was built', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (156, 3, 'Se paga la última factura de materiales', 'The last materials invoice is paid', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (156, 4, 'Se completa el 50% del contrato', '50% of the contract is completed', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (157, 2, 157, '¿Quién emite el Certificate of Occupancy de un edificio nuevo?', 'Who issues the Certificate of Occupancy of a new building?', 'El Certificate of Occupancy lo emite la autoridad local con jurisdicción (building department / building official) cuando la obra aprueba las inspecciones finales y cumple el código.', 'The Certificate of Occupancy is issued by the local authority with jurisdiction (building department / building official) when the work passes the final inspections and complies with the code.', 'Florida Building Code — Building');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (157, 1, 'El arquitecto del proyecto', 'The project architect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (157, 2, 'El contratista general', 'The general contractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (157, 3, 'La autoridad local de construcción (building official), tras las inspecciones finales', 'The local construction authority (building official), after the final inspections', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (157, 4, 'El DBPR del estado', 'The state DBPR', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (158, 2, 158, 'Según las condiciones generales estándar, la gestión y obtención del permiso de construcción (building permit) recae típicamente en:', 'Under the standard general conditions, obtaining and processing the building permit typically falls on:', 'En el esquema AIA, el contratista asegura y paga el building permit y demás permisos de construcción (distinto de los cargos del dueño, como el registro del Notice of Commencement).', 'Under the AIA scheme, the contractor secures and pays for the building permit and the other construction permits (unlike the owner''s charges, such as recording the Notice of Commencement).', 'AIA A201-2017');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (158, 1, 'El dueño, siempre y sin excepción', 'The owner, always and without exception', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (158, 2, 'El contratista, que lo tramita y paga como parte de su administración del contrato', 'The contractor, who processes and pays for it as part of the contractor''s administration of the contract', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (158, 3, 'El subcontratista principal', 'The main subcontractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (158, 4, 'La afianzadora del proyecto', 'The project''s surety', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (159, 2, 159, '¿Qué es el punch list?', 'What is the punch list?', 'El punch list se genera en la inspección de substantial completion: enumera lo incompleto o defectuoso que el contratista debe corregir para cerrar el contrato y liberar el pago final y la retención.', 'The punch list is generated at the substantial completion inspection: it lists what is incomplete or defective that the contractor must correct to close the contract and release final payment and retainage.', 'AIA A201-2017 · Administración de contratos');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (159, 1, 'La lista de licitantes que presentaron oferta', 'The list of bidders who submitted a bid', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (159, 2, 'La lista de partidas incompletas o defectuosas que deben corregirse antes del pago final y la aceptación', 'The list of incomplete or defective items that must be corrected before final payment and acceptance', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (159, 3, 'El registro de accidentes de la obra', 'The job accident log', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (159, 4, 'El cronograma de inspecciones del condado', 'The county inspection schedule', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (160, 2, 160, 'Los liquidated damages en un contrato de construcción son:', 'Liquidated damages in a construction contract are:', 'Los liquidated damages son la cantidad por día de atraso que las partes acuerdan por adelantado en el contrato como estimación razonable del daño del dueño por la entrega tardía.', 'Liquidated damages are the amount per day of delay that the parties agree in advance in the contract as a reasonable estimate of the owner''s damage from late delivery.', 'AIA A201-2017 · Florida Contractors Manual');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (160, 1, 'Una multa que impone el condado por violaciones de código', 'A fine imposed by the county for code violations', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (160, 2, 'Una suma diaria pactada en el contrato como compensación por el atraso en entregar la obra', 'A daily sum agreed in the contract as compensation for the delay in delivering the work', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (160, 3, 'El costo de reparar daños a propiedades vecinas', 'The cost of repairing damage to neighboring properties', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (160, 4, 'La retención del 10% sobre cada pago', 'The retainage of 10% on each payment', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (161, 2, 161, 'En un contrato a suma estipulada (stipulated sum), ¿qué debe entregar el Contratista al Arquitecto antes de presentar su primera Solicitud de Pago?', 'Under a stipulated sum contract, what must the Contractor submit to the Architect before submitting its first Application for Payment?', 'El schedule of values reparte la totalidad de la Contract Sum entre las porciones de la Obra y, salvo objeción del Arquitecto, sirve de base para revisar las solicitudes de pago del Contratista.', 'The schedule of values allocates the entire Contract Sum among the portions of the Work and, unless the Architect objects, serves as the basis for reviewing the Contractor''s Applications for Payment.', 'AIA A201-2017, § 9.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (161, 1, 'La lista preliminar de partidas pendientes de corregir en la obra', 'The preliminary punch list of items remaining to be corrected on the Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (161, 2, 'El certificado de ocupación temporal del edificio', 'The temporary certificate of occupancy for the building', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (161, 3, 'El cronograma de valores (schedule of values) que distribuye la totalidad de la Suma del Contrato entre las distintas porciones de la Obra', 'The schedule of values allocating the entire Contract Sum among the various portions of the Work', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (161, 4, 'El plan de mantenimiento preventivo del primer año del edificio', 'The preventive maintenance plan for the building''s first year', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (162, 2, 162, '¿Con cuánta anticipación debe el Contratista presentar su Solicitud de Pago (Application for Payment) desglosada, respecto de la fecha establecida para cada pago de avance?', 'How far in advance of the date established for each progress payment must the Contractor submit its itemized Application for Payment?', 'La solicitud se prepara conforme al schedule of values, refleja la retención aplicable y se acompaña de los datos que sustenten el derecho al pago, como las liberaciones de gravamen de subcontratistas y proveedores.', 'The Application is prepared in accordance with the schedule of values, reflects the applicable retainage, and is accompanied by the data substantiating the right to payment, such as lien releases from subcontractors and suppliers.', 'AIA A201-2017, § 9.3.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (162, 1, 'Al menos 10 días antes de la fecha establecida para cada pago de avance', 'At least 10 days before the date established for each progress payment', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (162, 2, 'El mismo día fijado para el pago', 'On the very day established for payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (162, 3, 'Dentro de los 7 días siguientes al cierre del mes', 'Within 7 days after the end of the month', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (162, 4, 'Al menos 30 días antes de cada pago de avance', 'At least 30 days before each progress payment', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (163, 2, 163, 'Dentro de los siete días siguientes a recibir la Solicitud de Pago del Contratista, ¿qué puede hacer el Arquitecto?', 'Within seven days after receiving the Contractor''s Application for Payment, what may the Architect do?', 'Esas tres son las únicas actuaciones previstas: certificar el total, certificar una cantidad menor explicando por qué se retiene parte, o retener la certificación entera explicando la causa conforme al § 9.5.1.', 'Those three are the only actions provided for: certify the full amount, certify a lesser amount while explaining why part is being withheld, or withhold the entire certification while explaining the cause in accordance with § 9.5.1.', 'AIA A201-2017, § 9.4.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (163, 1, 'Ordenar la suspensión de la Obra hasta completar su próxima visita programada', 'Order the Work suspended until the Architect completes the next scheduled site visit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (163, 2, 'Pagar directamente al Contratista con fondos del Dueño', 'Pay the Contractor directly from the Owner''s funds', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (163, 3, 'Transferir la revisión de la solicitud a la afianzadora del proyecto', 'Transfer review of the Application to the project''s surety', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (163, 4, 'Emitir el certificado por el monto total, emitirlo por un monto menor notificando las razones de la retención parcial, o retener la certificación completa notificando la razón', 'Issue the certificate for the full amount, issue it for a lesser amount while notifying the reasons for the partial withholding, or withhold the entire certification while notifying the reason', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (164, 2, 164, 'La emisión de un Certificate for Payment es una representación del Arquitecto ante el Dueño, pero NO representa que el Arquitecto:', 'The issuance of a Certificate for Payment is a representation by the Architect to the Owner, but it does NOT represent that the Architect:', 'El certificado se basa en la evaluación del Arquitecto y en los datos de la solicitud; tampoco implica que haya revisado los medios y métodos de construcción ni cómo el Contratista usó los pagos anteriores.', 'The certificate is based on the Architect''s evaluation and on the data in the Application; nor does it imply that the Architect has reviewed the construction means and methods or how the Contractor used prior payments.', 'AIA A201-2017, § 9.4.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (164, 1, 'Considere que la Obra avanzó hasta el punto indicado en la solicitud', 'Considers that the Work has progressed to the point indicated in the Application', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (164, 2, 'Haya hecho inspecciones exhaustivas o continuas en el sitio para verificar la calidad y la cantidad de la Obra', 'Has made exhaustive or continuous on-site inspections to verify the quality and quantity of the Work', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (164, 3, 'Considere que la calidad de la Obra se ajusta a los Documentos del Contrato', 'Considers that the quality of the Work conforms to the Contract Documents', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (164, 4, 'Considere que el Contratista tiene derecho al pago del monto certificado', 'Considers that the Contractor is entitled to payment of the amount certified', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (165, 2, 165, '¿Cuál de las siguientes es una causal válida para que el Arquitecto retenga, total o parcialmente, un Certificate for Payment?', 'Which of the following is a valid ground for the Architect to withhold a Certificate for Payment, in whole or in part?', 'Entre las causales enumeradas están también la obra defectuosa no remediada, los reclamos de terceros probables, la falta de pago del Contratista a subcontratistas o proveedores y los daños al Dueño o a un contratista separado.', 'The enumerated grounds also include defective Work that has not been remedied, probable third-party claims, the Contractor''s failure to pay subcontractors or suppliers, and damage to the Owner or to a separate contractor.', 'AIA A201-2017, § 9.5.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (165, 1, 'Que el Contratista haya presentado un reclamo de extensión de plazo', 'That the Contractor has filed a claim for an extension of time', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (165, 2, 'Que el Dueño quiera renegociar el diseño de una fachada', 'That the Owner wants to renegotiate the design of a façade', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (165, 3, 'Que exista evidencia razonable de que la Obra no podrá completarse con el saldo no pagado de la Suma del Contrato', 'That there is reasonable evidence that the Work cannot be completed for the unpaid balance of the Contract Sum', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (165, 4, 'Que el Arquitecto no haya podido visitar la obra durante esa semana', 'That the Architect was unable to visit the site that week', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (166, 2, 166, 'Una vez que el Contratista recibe el pago del Dueño, ¿en qué plazo debe pagar a cada Subcontratista el monto que le corresponde por su porción de la Obra?', 'Once the Contractor receives payment from the Owner, within what period must it pay each Subcontractor the amount due for its portion of the Work?', 'El pago al subcontratista refleja la retención aplicada a los pagos del Contratista por esa porción, y el Contratista debe exigir por contrato que cada subcontratista pague de la misma manera a sus sub-subcontratistas.', 'Payment to the Subcontractor reflects the retainage applied to payments to the Contractor for that portion, and the Contractor must contractually require each Subcontractor to pay its sub-subcontractors in the same manner.', 'AIA A201-2017, § 9.6.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (166, 1, 'A más tardar 7 días después de recibir el pago del Dueño, reflejando los porcentajes de retención efectivamente aplicados', 'No later than 7 days after receiving payment from the Owner, reflecting the retainage percentages actually applied', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (166, 2, 'El mismo día en que el Arquitecto emite el certificado de pago', 'On the same day the Architect issues the Certificate for Payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (166, 3, 'A los 30 días de emitido el certificado de pago', '30 days after the Certificate for Payment is issued', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (166, 4, 'Al cierre del proyecto, junto con el pago final', 'At project closeout, together with final payment', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (167, 2, 167, 'Si el Arquitecto no emite el certificado de pago dentro de los siete días sin culpa del Contratista, o el Dueño no paga dentro de los siete días siguientes a la fecha establecida en los Documentos del Contrato, el Contratista puede detener la Obra siempre que:', 'If the Architect does not issue the Certificate for Payment within seven days through no fault of the Contractor, or the Owner does not pay within seven days after the date established in the Contract Documents, the Contractor may stop the Work provided that it:', 'Cumplido ese procedimiento, el Plazo del Contrato se extiende de forma apropiada y la Suma aumenta con los costos razonables de parada, demora y rearranque, más los intereses correspondientes.', 'Once that procedure is followed, the Contract Time is extended appropriately and the Contract Sum is increased by the reasonable costs of shutdown, delay, and start-up, plus applicable interest.', 'AIA A201-2017, § 9.7');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (167, 1, 'Abandone el sitio de inmediato y retire todo su equipo', 'Abandons the site immediately and removes all of its equipment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (167, 2, 'Presente primero una demanda ante la corte del condado', 'First files a lawsuit in the county court', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (167, 3, 'Obtenga la autorización escrita de su afianzadora', 'Obtains written authorization from its surety', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (167, 4, 'Dé un aviso adicional de siete días al Dueño y al Arquitecto, y mantenga la detención hasta recibir el pago debido', 'Gives an additional seven days'' notice to the Owner and the Architect, and keeps the Work stopped until the payment due is received', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (168, 2, 168, '¿Cuál de estos documentos debe entregar el Contratista como condición previa para que venza el pago final y se le deba la retención restante?', 'Which of these documents must the Contractor submit as a condition precedent to final payment becoming due and to being owed the remaining retainage?', 'También debe entregar el certificado de vigencia de los seguros que deben continuar después del pago final, la declaración de que no conoce razón para que no se renueven, el consentimiento de la afianzadora si la hay y la documentación de las garantías especiales.', 'It must also submit the certificate showing that the insurance required to remain in force after final payment is in effect, a statement that it knows of no reason why it would not be renewed, the surety''s consent if there is a surety, and the documentation for special warranties.', 'AIA A201-2017, § 9.10.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (168, 1, 'Una carta de recomendación del Arquitecto sobre su desempeño', 'A letter of recommendation from the Architect regarding its performance', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (168, 2, 'Una declaración jurada (affidavit) de que las nóminas, las facturas de materiales y equipos y demás deudas vinculadas a la Obra han sido pagadas o satisfechas', 'An affidavit that payrolls, bills for materials and equipment, and other indebtedness connected with the Work have been paid or otherwise satisfied', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (168, 3, 'Un nuevo juego de planos récord aprobado por el condado', 'A new set of record drawings approved by the county', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (168, 4, 'La constancia de renovación de su licencia estatal de contratista', 'Proof of renewal of its state contractor''s license', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (169, 2, 169, 'Al hacer el pago final, el Dueño renuncia a sus reclamos (Claims) contra el Contratista, EXCEPTO los que surjan de:', 'In making final payment, the Owner waives its Claims against the Contractor, EXCEPT those arising from:', 'También sobreviven al pago final los gravámenes y reclamos no resueltos, los términos de las garantías especiales exigidas y las auditorías del Dueño permitidas por los Documentos del Contrato después del pago final.', 'Unresolved liens and Claims, the terms of special warranties required, and the Owner''s audits permitted by the Contract Documents after final payment also survive final payment.', 'AIA A201-2017, § 9.10.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (169, 1, 'Los cambios menores ordenados por escrito por el Arquitecto', 'Minor changes ordered in writing by the Architect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (169, 2, 'Los retrasos causados por clima adverso documentado', 'Delays caused by documented adverse weather', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (169, 3, 'La falta de conformidad de la Obra con los requisitos de los Documentos del Contrato', 'Nonconformity of the Work with the requirements of the Contract Documents', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (169, 4, 'Las solicitudes de información (RFI) respondidas con atraso', 'Requests for Information (RFIs) answered late', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (170, 2, 170, 'Para quien acepta el pago final (el Contratista, un Subcontratista o un proveedor), la aceptación constituye renuncia a sus reclamos, salvo:', 'For whoever accepts final payment (the Contractor, a Subcontractor, or a supplier), acceptance constitutes a waiver of its Claims, except for:', 'Solo sobreviven los reclamos que ya constaban por escrito y que el beneficiario identificó expresamente como pendientes cuando presentó la solicitud final de pago.', 'Only Claims that were already in writing and that the payee expressly identified as pending when it submitted the Final Application for Payment survive.', 'AIA A201-2017, § 9.10.5');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (170, 1, 'Los reclamos hechos previamente por escrito e identificados por ese beneficiario como no resueltos al momento de la Solicitud Final de Pago', 'Claims previously made in writing and identified by that payee as unsettled at the time of the Final Application for Payment', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (170, 2, 'Cualquier reclamo que presente verbalmente al Arquitecto durante el cierre de la obra', 'Any claim presented verbally to the Architect during project closeout', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (170, 3, 'Los reclamos por trabajos extra ejecutados sin autorización escrita', 'Claims for extra work performed without written authorization', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (170, 4, 'Los reclamos de terceros que ya fueron pagados en su totalidad', 'Third-party claims that have already been paid in full', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (171, 2, 171, 'Salvo que el Certificate of Substantial Completion disponga otra cosa, ¿cuándo comienzan a correr las garantías exigidas por los Documentos del Contrato?', 'Unless the Certificate of Substantial Completion provides otherwise, when do the warranties required by the Contract Documents begin to run?', 'El certificado establece además la fecha de terminación sustancial, las responsabilidades del Dueño y del Contratista en seguridad, mantenimiento, servicios, daños y seguros, y el plazo para terminar las partidas de la lista.', 'The certificate also establishes the date of Substantial Completion, the responsibilities of the Owner and the Contractor for security, maintenance, utilities, damage, and insurance, and the period for completing the items on the list.', 'AIA A201-2017, § 9.8.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (171, 1, 'En la fecha en que se hace el pago final', 'On the date final payment is made', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (171, 2, 'Un año después de la fecha de terminación sustancial', 'One year after the date of Substantial Completion', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (171, 3, 'Cuando la autoridad local emite el Certificate of Occupancy', 'When the local authority issues the Certificate of Occupancy', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (171, 4, 'En la fecha de Substantial Completion de la Obra o de la porción designada', 'On the date of Substantial Completion of the Work or of the designated portion', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (172, 2, 172, 'Cuando el Contratista firma una Construction Change Directive, esa firma significa que:', 'When the Contractor signs a Construction Change Directive, that signature means that it:', 'Por eso el Contratista debe revisar el método de ajuste antes de firmar: una vez firmada la directiva, el acuerdo sobre el ajuste o sobre su método es efectivo de inmediato.', 'That is why the Contractor must review the method of adjustment before signing: once the directive is signed, the agreement on the adjustment or on its method is effective immediately.', 'AIA A201-2017, § 7.3.7');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (172, 1, 'Solo acusa recibo de la directiva, sin acordar ajuste alguno', 'Merely acknowledges receipt of the directive, without agreeing to any adjustment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (172, 2, 'Renuncia a cualquier reclamo relacionado con el cambio', 'Waives any claim related to the change', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (172, 3, 'Acuerda su contenido, incluido el ajuste de la Suma y el Plazo o el método para determinarlos, con efecto inmediato, y el acuerdo se registra como una Change Order', 'Agrees to its contents, including the adjustment to the Contract Sum and the Contract Time or the method for determining them, effective immediately, and the agreement is recorded as a Change Order', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (172, 4, 'Obliga al Dueño a pagar el costo estimado del cambio más un 25%', 'Obligates the Owner to pay the estimated cost of the change plus 25%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (173, 2, 173, 'Mientras se determina el costo final de una Construction Change Directive, ¿cómo puede cobrar el Contratista el trabajo ya ejecutado bajo esa directiva?', 'While the final cost of a Construction Change Directive is being determined, how may the Contractor be paid for work already performed under that directive?', 'La determinación provisional del Arquitecto ajusta la Suma del Contrato con la misma base de una Change Order, sin perjuicio del derecho de cualquiera de las partes a discrepar y presentar un Claim.', 'The Architect''s interim determination adjusts the Contract Sum on the same basis as a Change Order, without prejudice to the right of either party to disagree and make a Claim.', 'AIA A201-2017, § 7.3.9');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (173, 1, 'Puede incluirlo en sus Solicitudes de Pago y el Arquitecto hará una determinación provisional, certificando el monto que en su juicio profesional sea razonablemente justificado', 'It may include it in its Applications for Payment, and the Architect will make an interim determination, certifying the amount that in the Architect''s professional judgment is reasonably justified', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (173, 2, 'No puede cobrar nada hasta que exista una Change Order firmada por las tres partes', 'It cannot be paid anything until there is a Change Order signed by all three parties', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (173, 3, 'Debe facturar ese trabajo directamente a los subcontratistas', 'It must invoice that work directly to the subcontractors', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (173, 4, 'Solo puede cobrarlo si el Dueño emite cheques conjuntos', 'It may only be paid if the Owner issues joint checks', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (174, 2, 174, 'El Arquitecto ordena por escrito un cambio menor en la Obra y el Contratista cree que ese cambio afectará la Suma o el Plazo del Contrato. ¿Qué debe hacer para no perder el ajuste?', 'The Architect orders a minor change in the Work in writing, and the Contractor believes that the change will affect the Contract Sum or the Contract Time. What must it do to avoid losing the adjustment?', 'La orden de cambio menor, por definición, no conlleva ajuste de suma ni de plazo; la única protección del Contratista es avisar al Arquitecto antes de ejecutarla.', 'A minor change order, by definition, carries no adjustment to the Contract Sum or the Contract Time; the Contractor''s only protection is to notify the Architect before performing it.', 'AIA A201-2017, § 7.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (174, 1, 'Ejecutarlo de inmediato y reclamar el ajuste en el pago final', 'Perform it immediately and claim the adjustment in the final payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (174, 2, 'Detener toda la Obra hasta que el Dueño firme una Change Order', 'Stop all of the Work until the Owner signs a Change Order', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (174, 3, 'Trasladar el costo al subcontratista que ejecute esa porción', 'Shift the cost to the subcontractor performing that portion', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (174, 4, 'Notificar al Arquitecto que el cambio afectará la Suma o el Plazo y no proceder con él; si lo ejecuta sin esa notificación previa, renuncia al ajuste', 'Notify the Architect that the change will affect the Contract Sum or the Contract Time and not proceed with it; if it performs it without that prior notice, it waives the adjustment', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (175, 2, 175, '¿Cuál de estas causas, si demora el inicio o el avance de la Obra, da derecho al Contratista a una extensión del Plazo del Contrato por el tiempo razonable que determine el Arquitecto?', 'Which of these causes, if it delays the commencement or progress of the Work, entitles the Contractor to an extension of the Contract Time for such reasonable time as the Architect determines?', 'También califican los actos u omisiones del Dueño o del Arquitecto, los cambios ordenados en la Obra, el clima adverso documentado según el § 15.1.6.2 y las demoras autorizadas en espera de mediación o resolución vinculante.', 'Acts or omissions of the Owner or the Architect, ordered changes in the Work, documented adverse weather under § 15.1.6.2, and authorized delays pending mediation or binding dispute resolution also qualify.', 'AIA A201-2017, § 8.3.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (175, 1, 'La avería del equipo de izaje propiedad del Contratista', 'Breakdown of the Contractor''s own hoisting equipment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (175, 2, 'Disputas laborales, incendio, demoras inusuales en las entregas o siniestros inevitables', 'Labor disputes, fire, unusual delivery delays, or unavoidable casualties', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (175, 3, 'La insolvencia de uno de sus subcontratistas', 'The insolvency of one of its subcontractors', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (175, 4, 'Los errores de estimación cometidos en su propia oferta', 'Estimating errors made in its own bid', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (176, 2, 176, 'Cuando la condición que da origen al reclamo se descubre antes de que expire el período de corrección de la Obra, ¿en qué plazo debe iniciarse un Claim, con aviso a la otra parte y al Initial Decision Maker?', 'When the condition giving rise to the claim is discovered before the period for correction of the Work expires, within what period must a Claim be commenced, with notice to the other party and to the Initial Decision Maker?', 'El aviso se dirige a la otra parte y al Initial Decision Maker, con copia al Arquitecto cuando este no ejerce esa función.', 'Notice is given to the other party and to the Initial Decision Maker, with a copy to the Architect when the Architect is not serving in that role.', 'AIA A201-2017, § 15.1.3.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (176, 1, 'Dentro de los 7 días siguientes al evento', 'Within 7 days after the event', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (176, 2, 'Dentro de los 90 días siguientes al pago final', 'Within 90 days after final payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (176, 3, 'Dentro de los 21 días del evento o de los 21 días desde que el reclamante reconoció por primera vez la condición, lo que ocurra después', 'Within 21 days of the event or within 21 days after the claimant first recognized the condition, whichever is later', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (176, 4, 'En cualquier momento dentro de los 10 años posteriores a la terminación sustancial', 'At any time within 10 years after Substantial Completion', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (177, 2, 177, 'Para reclamar un aumento de la Suma del Contrato, el Contratista debe dar el aviso del Claim:', 'To claim an increase in the Contract Sum, the Contractor must give notice of the Claim:', 'El aviso previo permite a las partes evaluar el cambio antes de incurrir en el costo; la única excepción es la emergencia prevista en el § 10.4.', 'Prior notice allows the parties to evaluate the change before incurring the cost; the only exception is the emergency provided for in § 10.4.', 'AIA A201-2017, § 15.1.5');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (177, 1, 'Antes de ejecutar la porción de la Obra objeto del reclamo, salvo que se trate de una emergencia que ponga en peligro la vida o la propiedad', 'Before performing the portion of the Work that is the subject of the claim, unless it is an emergency endangering life or property', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (177, 2, 'Dentro del mes siguiente a ejecutar el trabajo reclamado', 'Within the month after performing the claimed work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (177, 3, 'Únicamente después de recibido el pago final', 'Only after final payment has been received', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (177, 4, 'No se requiere aviso alguno cuando el monto reclamado es menor', 'No notice is required when the amount claimed is small', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (178, 2, 178, '¿Quién actúa como Initial Decision Maker de los Claims y qué efecto tiene su decisión inicial?', 'Who serves as the Initial Decision Maker for Claims, and what effect does its initial decision have?', 'Si el Initial Decision Maker no rinde su decisión dentro de los 30 días de referido el Claim, la parte reclamante puede exigir mediación y resolución vinculante aunque no exista decisión previa.', 'If the Initial Decision Maker does not render its decision within 30 days after the Claim is referred, the claiming party may demand mediation and binding dispute resolution even though there is no prior decision.', 'AIA A201-2017, § 15.2.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (178, 1, 'El Dueño, y su decisión es final e inapelable', 'The Owner, and its decision is final and unappealable', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (178, 2, 'La afianzadora del Contratista, cuando el reclamo supera el monto de la retención', 'The Contractor''s surety, when the claim exceeds the amount of the retainage', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (178, 3, 'El building official del condado, solo en asuntos de código', 'The county building official, only in code matters', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (178, 4, 'El Arquitecto, salvo que el Acuerdo designe a otra persona; su decisión inicial es condición precedente para pasar a la mediación', 'The Architect, unless the Agreement designates another person; its initial decision is a condition precedent to mediation', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (179, 2, 179, 'En el esquema del A201, antes de pasar a la resolución vinculante de disputas (arbitraje o litigio, según lo elegido en el Acuerdo), los Claims deben someterse a:', 'Under the A201 scheme, before proceeding to binding dispute resolution (arbitration or litigation, as selected in the Agreement), Claims must be submitted to:', 'Salvo acuerdo distinto, la mediación la administra la American Arbitration Association conforme a sus Construction Industry Mediation Procedures vigentes a la fecha del Acuerdo.', 'Unless otherwise agreed, mediation is administered by the American Arbitration Association in accordance with its Construction Industry Mediation Procedures in effect on the date of the Agreement.', 'AIA A201-2017, § 15.3.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (179, 1, 'Una audiencia administrativa ante el CILB', 'An administrative hearing before the CILB', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (179, 2, 'La votación de los subcontratistas principales del proyecto', 'A vote of the project''s principal subcontractors', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (179, 3, 'La mediación, como condición precedente a la resolución vinculante', 'Mediation, as a condition precedent to binding dispute resolution', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (179, 4, 'La revisión del prestamista que financia la construcción', 'Review by the lender financing the construction', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (180, 2, 180, 'Si en el Acuerdo se eligió el arbitraje como método de resolución vinculante, ¿cómo se administra y dónde se realiza por defecto?', 'If arbitration was selected in the Agreement as the binding dispute resolution method, how is it administered and where is it held by default?', 'El laudo del árbitro es final y sobre él puede dictarse sentencia en cualquier corte con jurisdicción, conforme a la ley aplicable.', 'The arbitrator''s award is final, and judgment may be entered on it in any court having jurisdiction, in accordance with applicable law.', 'AIA A201-2017, §§ 15.4.1 y 15.4.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (180, 1, 'Lo administra la American Arbitration Association bajo sus Construction Industry Arbitration Rules y se realiza en el lugar donde se encuentra el Proyecto', 'It is administered by the American Arbitration Association under its Construction Industry Arbitration Rules and is held in the place where the Project is located', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (180, 2, 'Lo administra el Arquitecto y se realiza en su oficina', 'It is administered by the Architect and held in the Architect''s office', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (180, 3, 'Lo administra el DBPR y se realiza en Tallahassee', 'It is administered by the DBPR and held in Tallahassee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (180, 4, 'Lo administra la corte del condado como arbitraje judicial obligatorio', 'It is administered by the county court as mandatory court-ordered arbitration', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (181, 2, 181, 'El Arquitecto pide destapar una porción de la Obra que fue cubierta sin que él hubiera solicitado examinarla antes de cubrirla. Al destaparla, la Obra resulta conforme a los Documentos del Contrato. ¿Qué corresponde?', 'The Architect asks to uncover a portion of the Work that was covered without the Architect having requested to examine it before it was covered. When uncovered, the Work conforms to the Contract Documents. What is the result?', 'La regla es simétrica: si la obra destapada no estuviera conforme, los costos del destape y de la corrección correrían por cuenta del Contratista.', 'The rule is symmetrical: if the uncovered Work did not conform, the costs of uncovering and correction would be borne by the Contractor.', 'AIA A201-2017, § 12.1.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (181, 1, 'El Contratista asume todos los costos del destape y la reposición, sin ajuste alguno', 'The Contractor bears all costs of uncovering and replacement, with no adjustment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (181, 2, 'El Contratista tiene derecho a un ajuste equitativo de la Suma y del Plazo del Contrato', 'The Contractor is entitled to an equitable adjustment to the Contract Sum and the Contract Time', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (181, 3, 'El Dueño debe pagar el doble del costo del destape como sanción', 'The Owner must pay double the cost of uncovering as a penalty', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (181, 4, 'Se anula retroactivamente el último Certificate for Payment', 'The most recent Certificate for Payment is retroactively nullified', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (182, 2, 182, 'Dentro del año de corrección posterior a la Substantial Completion, el Dueño descubre una no conformidad pero NO avisa al Contratista ni le da la oportunidad de corregirla. En consecuencia, el Dueño:', 'Within the one-year correction period after Substantial Completion, the Owner discovers a nonconformity but does NOT notify the Contractor or give it an opportunity to correct it. As a consequence, the Owner:', 'Si, en cambio, el Dueño avisa oportunamente y el Contratista no corrige dentro de un tiempo razonable, el Dueño puede corregir la obra por su cuenta conforme al § 2.5.', 'If, instead, the Owner gives timely notice and the Contractor does not correct it within a reasonable time, the Owner may correct the Work at its own hand in accordance with § 2.5.', 'AIA A201-2017, § 12.2.2.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (182, 1, 'Conserva intacto el derecho de exigir al Contratista la corrección', 'Retains intact the right to require the Contractor to correct it', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (182, 2, 'Puede retener de nuevo el doble del valor de la partida defectuosa', 'May withhold twice the value of the defective item again', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (182, 3, 'Transfiere automáticamente la obligación de corregir al Arquitecto', 'Automatically transfers the obligation to correct it to the Architect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (182, 4, 'Renuncia al derecho de exigir la corrección por el Contratista y a reclamar por incumplimiento de garantía bajo esa sección', 'Waives the right to require correction by the Contractor and to claim for breach of warranty under that section', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (183, 2, 183, 'El Arquitecto aprueba un shop drawing que contiene una desviación respecto de los Documentos del Contrato que el Contratista no le señaló al presentarlo. ¿Quién responde por esa desviación?', 'The Architect approves a shop drawing that contains a deviation from the Contract Documents that the Contractor did not point out when submitting it. Who is responsible for that deviation?', 'Solo hay liberación si el Contratista notificó la desviación al presentar el submittal y el Arquitecto la aprobó por escrito como cambio menor, o si se emitió una Change Order o una Construction Change Directive que la autorizara; tampoco hay liberación por errores u omisiones del propio submittal.', 'There is relief only if the Contractor notified the deviation when it submitted the submittal and the Architect approved it in writing as a minor change, or if a Change Order or a Construction Change Directive authorizing it was issued; nor is there relief for errors or omissions in the submittal itself.', 'AIA A201-2017, § 3.12.8');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (183, 1, 'El Arquitecto, porque su aprobación transfiere la responsabilidad', 'The Architect, because its approval transfers responsibility', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (183, 2, 'El Dueño, por ser quien se beneficia de la obra construida', 'The Owner, because it is the party that benefits from the constructed Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (183, 3, 'El Contratista, porque la aprobación no lo libera de las desviaciones que no notificó expresamente al momento de presentar el submittal', 'The Contractor, because approval does not relieve it of deviations it did not expressly notify at the time it submitted the submittal', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (183, 4, 'Se reparte en partes iguales entre el Arquitecto y el Dueño', 'It is shared in equal parts between the Architect and the Owner', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (184, 2, 184, '¿Cuál es el alcance de la revisión que hace el Arquitecto de los submittals del Contratista (shop drawings, datos de producto y muestras)?', 'What is the scope of the Architect''s review of the Contractor''s submittals (shop drawings, product data, and samples)?', 'La revisión es limitada a ese propósito: no releva al Contratista de sus obligaciones y la aprobación de un artículo específico no significa la aprobación del conjunto del cual forma parte.', 'Review is limited to that purpose: it does not relieve the Contractor of its obligations, and approval of a specific item does not mean approval of the assembly of which it is a part.', 'AIA A201-2017, § 4.2.7');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (184, 1, 'Comprobar la conformidad del submittal con la información dada y con el concepto de diseño expresado en los Documentos del Contrato', 'To check the submittal''s conformance with the information given and the design concept expressed in the Contract Documents', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (184, 2, 'Verificar la exactitud y completitud de todas las dimensiones y cantidades', 'To verify the accuracy and completeness of all dimensions and quantities', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (184, 3, 'Aprobar los medios, métodos, técnicas y secuencias de construcción', 'To approve the construction means, methods, techniques, and sequences', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (184, 4, 'Certificar las precauciones de seguridad del sitio de la obra', 'To certify the site''s safety precautions', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (185, 2, 185, 'El Contratista notifica al Dueño y al Arquitecto las personas o entidades propuestas para las porciones principales de la Obra. Si el Arquitecto no notifica ninguna objeción dentro de los 14 días de recibida esa información:', 'The Contractor notifies the Owner and the Architect of the persons or entities proposed for the principal portions of the Work. If the Architect does not notify any objection within 14 days after receiving that information:', 'El Contratista no puede contratar con una persona o entidad contra la cual el Dueño o el Arquitecto hayan hecho una objeción razonable y oportuna.', 'The Contractor may not contract with a person or entity against which the Owner or the Architect has made a reasonable and timely objection.', 'AIA A201-2017, § 5.2.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (185, 1, 'Se entiende que el Dueño rechaza a todos los propuestos', 'It is understood that the Owner rejects all of the proposed parties', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (185, 2, 'El Contratista debe presentar la lista de nuevo con otros nombres', 'The Contractor must submit the list again with other names', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (185, 3, 'Los propuestos quedan vetados hasta que responda la afianzadora', 'The proposed parties remain barred until the surety responds', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (185, 4, 'Se entiende que no existe objeción razonable contra las personas o entidades propuestas', 'It is understood that there is no reasonable objection to the proposed persons or entities', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (186, 2, 186, 'Si la Obra se detiene 30 días consecutivos sin culpa del Contratista por una causal del § 14.1.1 (por ejemplo, que el Arquitecto no certifique el pago o el Dueño no pague), el Contratista puede terminar el Contrato con aviso de siete días y recuperar del Dueño:', 'If the Work is stopped for 30 consecutive days through no fault of the Contractor for a cause under § 14.1.1 (for example, the Architect fails to certify payment or the Owner fails to pay), the Contractor may terminate the Contract on seven days'' notice and recover from the Owner:', 'El mismo remedio aplica si el Dueño incumple repetidamente obligaciones importantes para el avance y la detención llega a 60 días consecutivos, con siete días adicionales de aviso.', 'The same remedy applies if the Owner repeatedly fails to perform obligations material to progress and the stoppage reaches 60 consecutive days, with an additional seven days'' notice.', 'AIA A201-2017, §§ 14.1.1 a 14.1.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (186, 1, 'Solo el pago de la Obra ejecutada, sin ningún concepto adicional', 'Only payment for the Work performed, with no additional amount', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (186, 2, 'El pago de la Obra ejecutada, más gastos generales y ganancia razonables sobre la Obra no ejecutada, y los costos incurridos por razón de la terminación', 'Payment for the Work performed, plus reasonable overhead and profit on the Work not performed, and the costs incurred by reason of the termination', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (186, 3, 'La totalidad de la Suma del Contrato a título de penalidad', 'The entire Contract Sum as a penalty', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (186, 4, 'Únicamente la liberación de la retención acumulada', 'Only the release of the accumulated retainage', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (187, 2, 187, 'Para que el Dueño termine el Contrato por causa (termination for cause), además de que exista una causal del § 14.2.1 se requiere:', 'For the Owner to terminate the Contract for cause, in addition to a ground under § 14.2.1 existing, what is required?', 'Efectuada la terminación por causa, el Dueño puede excluir al Contratista del sitio, tomar posesión de sus materiales y equipos, aceptar la cesión de los subcontratos y terminar la Obra por el método razonable que estime conveniente.', 'Once termination for cause has been effected, the Owner may exclude the Contractor from the site, take possession of its materials and equipment, accept assignment of the subcontracts, and complete the Work by whatever reasonable method it deems expedient.', 'AIA A201-2017, § 14.2.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (187, 1, 'La aprobación previa de la afianzadora y del prestamista de la construcción', 'Prior approval from the surety and the construction lender', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (187, 2, 'Una orden judicial que autorice la terminación', 'A court order authorizing the termination', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (187, 3, 'La certificación del Arquitecto de que existe causa suficiente y el aviso escrito de siete días al Contratista y a su afianzadora, si la hay', 'Certification by the Architect that sufficient cause exists, and seven days'' written notice to the Contractor and its surety, if any', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (187, 4, 'El voto favorable de los subcontratistas de las porciones principales', 'A favorable vote by the subcontractors for the principal portions', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (188, 2, 188, 'Si el Dueño ordena por escrito suspender la Obra por conveniencia, el ajuste de la Suma del Contrato a favor del Contratista:', 'If the Owner orders the Work suspended in writing for the Owner''s convenience, the adjustment to the Contract Sum in the Contractor''s favor:', 'La suspensión por conveniencia no requiere causa y también da lugar al ajuste del Plazo del Contrato por el tiempo afectado.', 'A suspension for convenience requires no cause and also gives rise to an adjustment to the Contract Time for the time affected.', 'AIA A201-2017, § 14.3.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (188, 1, 'Incluye ganancia (profit), excepto en la medida en que la suspensión se deba a una causa imputable al Contratista o el ajuste ya esté cubierto por otra disposición del Contrato', 'Includes profit, except to the extent the suspension is due to a cause attributable to the Contractor or the adjustment is already covered by another provision of the Contract', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (188, 2, 'Nunca puede incluir ganancia, solo costos directos comprobados', 'Can never include profit, only proven direct costs', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (188, 3, 'Se limita al 50% del costo adicional demostrado', 'Is limited to 50% of the additional cost demonstrated', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (188, 4, 'Lo fija el Arquitecto de manera unilateral e irrecurrible', 'Is set by the Architect unilaterally and without recourse', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (189, 2, 189, 'En una terminación del Contrato por conveniencia del Dueño, este debe pagar al Contratista:', 'In a termination of the Contract for the Owner''s convenience, the Owner must pay the Contractor:', 'A diferencia de la terminación ejercida por el Contratista bajo el § 14.1, aquí no se paga ganancia sobre la obra no ejecutada; solo la tarifa de terminación si el Acuerdo la establece.', 'Unlike a termination exercised by the Contractor under § 14.1, profit on the Work not performed is not paid here; only the termination fee if the Agreement establishes one.', 'AIA A201-2017, § 14.4.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (189, 1, 'La Obra ejecutada más la ganancia sobre toda la Obra no ejecutada', 'The Work performed plus profit on all of the Work not performed', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (189, 2, 'Solo los materiales y equipos almacenados en el sitio', 'Only the materials and equipment stored on the site', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (189, 3, 'La Suma total del Contrato menos una penalidad del 10%', 'The total Contract Sum minus a 10% penalty', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (189, 4, 'La Obra correctamente ejecutada, los costos incurridos por razón de la terminación, incluidos los costos de terminación de subcontratos, y la tarifa de terminación fijada en el Acuerdo, si la hay', 'The Work properly performed, the costs incurred by reason of the termination, including the costs of terminating subcontracts, and the termination fee stipulated in the Agreement, if any', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (190, 2, 190, 'Según el A401, los Documentos del Subcontrato no deben interpretarse como creadores de una relación contractual entre:', 'According to the A401, the Subcontract Documents are not intended to be construed as creating a contractual relationship between:', 'La cadena contractual es Dueño–Contratista y Contratista–Subcontratista; el subcontratista no tiene contrato directo con el Dueño, aunque el A201 se adopte por referencia como condiciones generales del subcontrato.', 'The contractual chain is Owner–Contractor and Contractor–Subcontractor; the Subcontractor has no direct contract with the Owner, even though the A201 is adopted by reference as the general conditions of the subcontract.', 'AIA A401-2017, § 1.5');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (190, 1, 'El Contratista y el Subcontratista', 'The Contractor and the Subcontractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (190, 2, 'El Subcontratista y sus propios proveedores', 'The Subcontractor and its own suppliers', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (190, 3, 'El Dueño y el Subcontratista, ni tampoco entre el Arquitecto y el Subcontratista', 'The Owner and the Subcontractor, or between the Architect and the Subcontractor', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (190, 4, 'El Contratista y el Arquitecto del proyecto', 'The Contractor and the project Architect', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (191, 2, 191, 'Un Subcontratista incumple y, tras recibir el aviso del Contratista, no comienza ni continúa la corrección del incumplimiento con diligencia dentro de los cinco días laborables. El Contratista puede:', 'A Subcontractor defaults and, after receiving the Contractor''s notice, does not begin or continue correction of the default diligently within five business days. The Contractor may:', 'Si los pagos debidos al Subcontratista no alcanzan a cubrir el costo de la corrección, el Subcontratista debe pagar la diferencia al Contratista.', 'If the payments owed to the Subcontractor are not enough to cover the cost of the correction, the Subcontractor must pay the difference to the Contractor.', 'AIA A401-2017, § 3.5');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (191, 1, 'Detener los pagos de todos los demás subcontratistas del proyecto', 'Stop payments to all of the project''s other subcontractors', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (191, 2, 'Corregir el incumplimiento por su cuenta y retener su costo razonable de los pagos actuales o futuros debidos al Subcontratista', 'Correct the default on its own account and deduct its reasonable cost from present or future payments owed to the Subcontractor', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (191, 3, 'Exigir al Dueño que pague directamente la corrección', 'Require the Owner to pay for the correction directly', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (191, 4, 'Declarar rescindidos todos los subcontratos del proyecto', 'Declare all of the project''s subcontracts terminated', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (192, 2, 192, 'Para terminar el Subcontrato por causa, el A401 exige que el Subcontratista, tras recibir el aviso del Contratista, no comience ni continúe la corrección de su incumplimiento dentro de un período de:', 'To terminate the Subcontract for cause, the A401 requires that the Subcontractor, after receiving the Contractor''s notice, not begin or continue correction of its default within a period of:', 'Vencido ese período sin corrección diligente, el Contratista puede terminar el Subcontrato y finalizar esa porción de la Obra por el método que estime conveniente.', 'Once that period expires without diligent correction, the Contractor may terminate the Subcontract and complete that portion of the Work by whatever method it deems expedient.', 'AIA A401-2017, § 7.2.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (192, 1, 'Cinco días laborables', 'Five business days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (192, 2, 'Cuarenta y ocho horas', 'Forty-eight hours', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (192, 3, 'Treinta días calendario', 'Thirty calendar days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (192, 4, 'Diez días', 'Ten days', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (193, 2, 193, 'Según el A401, el Contratista debe pagar cada pago de avance al Subcontratista:', 'According to the A401, the Contractor must pay each progress payment to the Subcontractor:', 'Y si el certificado no se emite o el Contratista no recibe el pago por una causa ajena al Subcontratista, este puede exigir el pago de avance a demanda (on demand).', 'And if the certificate is not issued or the Contractor does not receive payment for a cause not attributable to the Subcontractor, the Subcontractor may demand the progress payment on demand.', 'AIA A401-2017, § 11.1.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (193, 1, 'Al cierre del mes siguiente a aquel en que recibió el pago del Dueño', 'At the close of the month following the month in which it received payment from the Owner', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (193, 2, 'A más tardar siete días laborables después de que el Contratista reciba el pago del Dueño', 'No later than seven business days after the Contractor receives payment from the Owner', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (193, 3, 'Cuando el Arquitecto emita el siguiente certificado de pago', 'When the Architect issues the next Certificate for Payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (193, 4, 'Solo contra entrega de una nueva fianza de pago del Subcontratista', 'Only upon delivery of a new payment bond from the Subcontractor', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (194, 2, 194, 'La porción de un Subcontratista alcanzó su terminación sustancial, pero el Contrato Principal no permite liberar totalmente la retención antes de que termine todo el Proyecto. Dentro de los 30 días siguientes al certificado del Arquitecto que cubre esa porción, el Contratista debe pagarle una suma que:', 'A Subcontractor''s portion has reached Substantial Completion, but the Prime Contract does not allow the retainage to be fully released before the entire Project is completed. Within 30 days after the Architect''s certificate covering that portion, the Contractor must pay the Subcontractor an amount that:', 'Si el Contrato Principal sí permitiera la liberación total de la retención, el pago sería el saldo completo no pagado de la suma del subcontrato por esa porción, descontando lo retenido para partidas por completar o corregir.', 'If the Prime Contract did allow full release of the retainage, the payment would be the full unpaid balance of the subcontract sum for that portion, less amounts retained for items to be completed or corrected.', 'AIA A401-2017, § 11.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (194, 1, 'Reduzca la retención de esa porción hasta dejarla en el mismo porcentaje de retención aplicado a la Obra del Contratista en ese certificado', 'Reduces the retainage on that portion so as to leave it at the same retainage percentage applied to the Contractor''s Work in that certificate', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (194, 2, 'Libere la totalidad de la retención de esa porción en todos los casos', 'Releases the entire retainage on that portion in all cases', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (194, 3, 'Aumente la retención al doble hasta el pago final del proyecto', 'Increases the retainage to double until final payment for the project', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (194, 4, 'Se limite al valor de los materiales almacenados de esa porción', 'Is limited to the value of the stored materials for that portion', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (195, 2, 195, 'Están cumplidas las demás condiciones del pago final del subcontrato, pero por una causa ajena al Subcontratista el Arquitecto no emite el certificado, el Contratista no recibe el pago del Dueño o no le paga dentro de los siete días de haberlo recibido. En ese caso, el pago final al Subcontratista:', 'The other conditions for final payment under the subcontract have been met, but, through no fault of the Subcontractor, the Architect does not issue the certificate, the Contractor does not receive payment from the Owner, or it does not pay within seven days after receiving it. In that case, final payment to the Subcontractor:', 'Antes del pago final, el Subcontratista puede tener que evidenciar que pagó las nóminas, los materiales y todas las deudas conocidas vinculadas a su porción de la Obra.', 'Before final payment, the Subcontractor may be required to evidence that it has paid payrolls, materials, and all known indebtedness connected with its portion of the Work.', 'AIA A401-2017, § 11.3.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (195, 1, 'Queda suspendido indefinidamente hasta que termine todo el Proyecto', 'Is suspended indefinitely until the entire Project ends', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (195, 2, 'Lo paga directamente el Dueño al Subcontratista', 'Is paid directly by the Owner to the Subcontractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (195, 3, 'Se convierte en un préstamo del Contratista al Subcontratista', 'Becomes a loan from the Contractor to the Subcontractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (195, 4, 'Debe hacerse a demanda (upon demand) del Subcontratista', 'Must be made upon the Subcontractor''s demand', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (196, 2, 196, 'En el A401, si el Contratista y el Subcontratista no marcan ninguna casilla con el método vinculante de resolución de disputas ni lo acuerdan después por escrito, los Claims se resolverán mediante:', 'Under the A401, if the Contractor and the Subcontractor check no box for the binding dispute resolution method and do not later agree on one in writing, Claims will be resolved by:', 'La mediación sigue siendo condición precedente a la resolución vinculante, pero el método por defecto, cuando no se selecciona otro, es el litigio.', 'Mediation remains a condition precedent to binding dispute resolution, but the default method, when no other is selected, is litigation.', 'AIA A401-2017, § 6.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (196, 1, 'Arbitraje administrado por la American Arbitration Association', 'Arbitration administered by the American Arbitration Association', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (196, 2, 'Litigio en una corte de jurisdicción competente', 'Litigation in a court of competent jurisdiction', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (196, 3, 'Decisión final e inapelable del Arquitecto', 'A final and unappealable decision by the Architect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (196, 4, 'Mediación repetida hasta que una de las partes ceda', 'Repeated mediation until one of the parties yields', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (197, 2, 197, 'Durante la licitación, la aprobación de una sustitución de material o equipo propuesta por un licitante antes de la recepción de ofertas solo es vinculante si:', 'During bidding, approval of a substitution of material or equipment proposed by a bidder before receipt of bids is binding only if:', 'Las solicitudes de sustitución deben recibirse por escrito al menos diez días antes de la fecha de recepción de ofertas, y la carga de probar el mérito de la sustitución recae en quien la propone.', 'Requests for substitution must be received in writing at least ten days before the date for receipt of bids, and the burden of proving the merit of the substitution rests on the party proposing it.', 'AIA A701-2018, §§ 3.3.2 y 3.3.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (197, 1, 'El Arquitecto la aprueba verbalmente en la reunión previa a la oferta', 'The Architect approves it verbally at the pre-bid meeting', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (197, 2, 'El licitante la anota directamente en su formulario de oferta', 'The bidder notes it directly on its bid form', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (197, 3, 'La aprobación se establece en una Adenda (Addendum); las aprobaciones hechas de cualquier otra manera no son vinculantes y los licitantes no deben confiar en ellas', 'The approval is set forth in an Addendum; approvals made in any other manner are not binding, and bidders shall not rely on them', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (197, 4, 'El Dueño la menciona en la invitación a licitar', 'The Owner mentions it in the Invitation to Bid', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (198, 2, 198, '¿Cuál es el plazo límite general para emitir las Adendas (Addenda) que modifican o interpretan los Documentos de Licitación?', 'What is the general deadline for issuing Addenda that modify or interpret the Bidding Documents?', 'Antes de presentar su oferta, cada licitante debe asegurarse de haber recibido todas las adendas emitidas y reconocer su recibo dentro de la propia oferta.', 'Before submitting its bid, each bidder must ascertain that it has received all Addenda issued and acknowledge receipt of them within the bid itself.', 'AIA A701-2018, §§ 3.4.3 y 3.4.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (198, 1, 'No más tarde de cuatro días antes de la fecha de recepción de ofertas, salvo la adenda que retire la solicitud de ofertas o que posponga esa fecha', 'No later than four days before the date for receipt of bids, except for an addendum withholding the request for bids or postponing that date', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (198, 2, 'El mismo día de la recepción de ofertas, antes de la hora de apertura', 'On the day of receipt of bids, before the opening time', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (198, 3, 'Al menos diez días antes, sin excepción alguna', 'At least ten days before, without any exception', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (198, 4, 'No hay plazo definido; basta con publicarlas donde estén archivados los documentos', 'There is no defined deadline; it is enough to publish them where the documents are on file', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (199, 2, 199, 'En el formulario de oferta de un licitante, el monto aparece escrito en palabras como una cantidad y en números como otra distinta. ¿Qué monto rige?', 'In a bidder''s bid form, the amount is written in words as one amount and in figures as a different amount. Which amount governs?', 'Las sumas deben expresarse en palabras y en números, salvo indicación contraria del formulario; en caso de discrepancia, gobierna la cantidad escrita en palabras.', 'Amounts must be expressed in words and in figures, unless the form indicates otherwise; in the event of a discrepancy, the amount written in words governs.', 'AIA A701-2018, § 4.1.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (199, 1, 'El monto en números, por ser más preciso', 'The amount in figures, because it is more precise', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (199, 2, 'El promedio de ambos montos', 'The average of the two amounts', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (199, 3, 'Ninguno, porque la oferta queda anulada automáticamente', 'Neither, because the bid is automatically nullified', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (199, 4, 'El monto expresado en palabras', 'The amount expressed in words', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (200, 2, 200, 'Si el licitante seleccionado se niega a celebrar el Contrato con el Dueño o no entrega las fianzas exigidas, la garantía de oferta (bid security) que acompañó su oferta:', 'If the selected bidder refuses to enter into the Contract with the Owner or fails to furnish the required bonds, the bid security that accompanied its bid:', 'Cuando la garantía es una fianza, se emite en el formulario AIA A310, Bid Bond, salvo que los Documentos de Licitación dispongan otra cosa.', 'When the security is a bond, it is issued on AIA Form A310, Bid Bond, unless the Bidding Documents provide otherwise.', 'AIA A701-2018, §§ 4.2.2 y 4.2.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (200, 1, 'Se devuelve íntegra en todos los casos', 'Is returned in full in all cases', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (200, 2, 'Se transfiere al segundo licitante más bajo', 'Is transferred to the second-lowest bidder', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (200, 3, 'Se pierde a favor del Dueño como daños liquidados (liquidated damages), no como penalidad', 'Is forfeited to the Owner as liquidated damages, not as a penalty', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (200, 4, 'Queda retenida por el Arquitecto como parte de sus honorarios', 'Is retained by the Architect as part of its fee', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (201, 2, 201, 'Al considerar las ofertas y adjudicar, ¿cómo puede el Dueño tratar los Alternates solicitados y cómo se determina al licitante responsable más bajo?', 'In considering bids and making the award, how may the Owner treat the requested Alternates, and how is the lowest responsible bidder determined?', 'Todos los alternates solicitados deben ser ofertados; si un alternate no produce cambio en la oferta base, el licitante debe escribir ''No Change''.', 'All requested Alternates must be bid; if an Alternate produces no change in the base bid, the bidder must write ''No Change.''', 'AIA A701-2018, §§ 5.3.2 y 4.1.5');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (201, 1, 'Debe aceptarlos en el orden exacto en que aparecen listados y adjudicar solo sobre la oferta base', 'It must accept them in the exact order in which they are listed and award only on the base bid', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (201, 2, 'Puede aceptarlos en cualquier orden o combinación, y el licitante responsable más bajo se determina sobre la base de la oferta base más los alternates aceptados', 'It may accept them in any order or combination, and the lowest responsible bidder is determined on the basis of the base bid plus the accepted Alternates', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (201, 3, 'Los alternates deben adjudicarse a un contratista distinto del adjudicatario', 'The Alternates must be awarded to a contractor other than the awardee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (201, 4, 'Los alternates pierden validez después de la apertura de ofertas', 'The Alternates lose validity after the opening of bids', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (202, 2, 202, 'Antes de ejecutarse el Contrato, el Arquitecto notifica al licitante seleccionado que el Dueño o el Arquitecto tienen objeción razonable contra una persona o entidad propuesta por él. El licitante puede:', 'Before the Contract is executed, the Architect notifies the selected bidder that the Owner or the Architect has a reasonable objection to a person or entity it has proposed. The bidder may:', 'El Dueño puede aceptar el precio ajustado por la sustitución o descalificar al licitante; en ninguno de los dos casos procede la confiscación de la garantía.', 'The Owner may accept the price adjusted for the substitution or disqualify the bidder; in neither case is forfeiture of the security warranted.', 'AIA A701-2018, § 6.3.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (202, 1, 'Demandar al Dueño por los daños causados por la objeción', 'Sue the Owner for the damages caused by the objection', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (202, 2, 'Ejecutar esa porción con personal propio y sin ajuste de precio', 'Perform that portion with its own personnel and with no price adjustment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (202, 3, 'Pierde automáticamente la garantía de oferta', 'Automatically loses its bid security', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (202, 4, 'Retirar su oferta o presentar un sustituto aceptable, con el ajuste de precio correspondiente por la diferencia de costo; si retira la oferta o es descalificado, no pierde la garantía de oferta', 'Withdraw its bid or present an acceptable substitute, with the corresponding price adjustment for the difference in cost; if it withdraws its bid or is disqualified, it does not lose its bid security', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (203, 2, 203, '¿En qué tipo de proyecto se usa típicamente el A101-2017, el acuerdo entre Dueño y Contratista con base de pago de suma estipulada?', 'In what type of project is the A101-2017 typically used, the Owner-Contractor agreement with a stipulated sum basis of payment?', 'En el A101 los pagos de avance son mensuales y se calculan con base en el schedule of values y el porcentaje de avance de cada partida, con la retención que el propio Acuerdo establezca.', 'Under the A101, progress payments are monthly and are calculated on the basis of the schedule of values and the percentage of completion of each item, with the retainage established by the Agreement itself.', 'AIA A101-2017');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (203, 1, 'Proyectos cuyo diseño apenas comienza y cuyo alcance aún es indefinido', 'Projects whose design is only just beginning and whose scope is still undefined', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (203, 2, 'Proyectos con el diseño completo, licitados competitivamente, donde el Dueño busca el precio fijo total (lump sum) más conveniente', 'Projects with the design complete, competitively bid, where the Owner seeks the most advantageous total fixed price (lump sum)', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (203, 3, 'Proyectos en los que el Contratista financia la construcción', 'Projects in which the Contractor finances the construction', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (203, 4, 'Contratos de gerencia de construcción sin precio de obra definido', 'Construction management contracts with no defined Work price', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (204, 2, 204, '¿Cómo se tratan las allowances (montos asignados para partidas aún no definidas del todo) dentro del A101-2017?', 'How are allowances (amounts allocated for items not yet fully defined) treated under the A101-2017?', 'El Artículo 4 del A101 lista, dentro de la Contract Sum, los alternates incluidos, las allowances identificadas una por una y los precios unitarios aplicables.', 'Article 4 of the A101 lists, within the Contract Sum, the alternates included, the allowances identified one by one, and the applicable unit prices.', 'AIA A101-2017, § 4.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (204, 1, 'Forman parte de la Suma del Contrato y cada allowance se identifica expresamente en el Acuerdo', 'They form part of the Contract Sum, and each allowance is expressly identified in the Agreement', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (204, 2, 'Quedan fuera de la Suma del Contrato y se pagan con fondos separados del prestamista', 'They are outside the Contract Sum and are paid from the lender''s separate funds', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (204, 3, 'Las fija el Arquitecto después de la terminación sustancial', 'The Architect sets them after Substantial Completion', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (204, 4, 'Solo pueden aplicarse a porciones ejecutadas por subcontratistas', 'They may only be applied to portions performed by subcontractors', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (205, 2, 205, 'En el A102-2017, donde el pago es el costo de la obra más un honorario con precio máximo garantizado (GMP), ¿qué ocurre si el costo final tiende a superar el GMP?', 'Under the A102-2017, where payment is the Cost of the Work plus a fee with a Guaranteed Maximum Price (GMP), what happens if the final cost tends to exceed the GMP?', 'El GMP es la protección de tope del Dueño dentro de un esquema de costos reembolsables más honorario, y por eso el A102 define con detalle qué conceptos integran el costo de la obra.', 'The GMP is the Owner''s ceiling protection within a reimbursable-cost-plus-fee scheme, and that is why the A102 defines in detail which items make up the Cost of the Work.', 'AIA A102-2017');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (205, 1, 'El Dueño paga el exceso automáticamente con la siguiente solicitud de pago', 'The Owner automatically pays the excess with the next Application for Payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (205, 2, 'El Arquitecto decide discrecionalmente quién absorbe el exceso', 'The Architect decides at its discretion who absorbs the excess', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (205, 3, 'El contrato se convierte automáticamente en uno de suma estipulada', 'The contract automatically becomes a stipulated sum contract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (205, 4, 'La Suma del Contrato no puede exceder el GMP; el Contratista absorbe los costos por encima del tope, salvo que el GMP se ajuste mediante los mecanismos previstos en el contrato', 'The Contract Sum may not exceed the GMP; the Contractor absorbs the costs above the cap, unless the GMP is adjusted through the mechanisms provided in the contract', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (206, 2, 206, '¿Qué derecho característico tiene el Dueño bajo el A102-2017 para controlar los costos que le son cargados?', 'What characteristic right does the Owner have under the A102-2017 to control the costs charged to it?', 'En los contratos de costo más honorario no hay un precio cerrado, así que los amplios derechos de auditoría del Dueño sustituyen la certeza que daría una suma estipulada.', 'In cost-plus-fee contracts there is no fixed price, so the Owner''s broad audit rights substitute for the certainty that a stipulated sum would provide.', 'AIA A102-2017');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (206, 1, 'Sustituir a cualquier subcontratista sin aviso previo', 'To replace any subcontractor without prior notice', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (206, 2, 'Auditar y verificar que los costos fueron realmente incurridos por el Contratista y que son reembolsables conforme al Acuerdo', 'To audit and verify that the costs were actually incurred by the Contractor and that they are reimbursable under the Agreement', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (206, 3, 'Fijar unilateralmente el honorario del Contratista al final de la obra', 'To set the Contractor''s fee unilaterally at the end of the Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (206, 4, 'Aprobar personalmente cada compra de materiales del Contratista', 'To personally approve each purchase of materials by the Contractor', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (207, 2, 207, 'En Florida, cuando el contrato directo supera los $5.000, ¿qué debe hacer el solicitante del permiso respecto del Notice of Commencement antes de que se realice la primera inspección de la obra?', 'In Florida, when the direct contract exceeds $5,000, what must the permit applicant do with respect to the Notice of Commencement before the first inspection of the Work is performed?', 'Este trámite vincula el permiso con el régimen de gravámenes de la construcción: sin él, el proceso de permitting queda incompleto aunque el permiso ya se haya emitido.', 'That filing ties the permit to the construction lien regime: without it, the permitting process remains incomplete even though the permit has already been issued.', 'Estatutos de Florida, § 713.135');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (207, 1, 'Enviarlo por correo certificado al Arquitecto del proyecto', 'Send it by certified mail to the project Architect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (207, 2, 'Registrar un segundo Notice of Commencement ante el DBPR del estado', 'Record a second Notice of Commencement with the state DBPR', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (207, 3, 'Presentar ante la autoridad emisora del permiso una copia certificada del Notice of Commencement registrado, o una declaración juramentada de que fue presentado para su registro, y fijar una copia en el sitio de la obra', 'File with the permit-issuing authority a certified copy of the recorded Notice of Commencement, or an affidavit that it was submitted for recording, and post a copy at the job site', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (207, 4, 'Entregarlo únicamente a los subcontratistas que lo soliciten por escrito', 'Deliver it only to subcontractors who request it in writing', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (208, 2, 208, 'Si el Notice of Commencement registrado en Florida no indica otra fecha de terminación, ¿cuándo expira por defecto?', 'If the Notice of Commencement recorded in Florida does not state another termination date, when does it expire by default?', 'La vigencia del Notice of Commencement marca el marco temporal de los derechos de gravamen del proyecto, por lo que en obras largas debe vigilarse su renovación o nuevo registro.', 'The term of the Notice of Commencement sets the time frame for the project''s lien rights, so on long jobs its renewal or re-recording must be watched.', 'Estatutos de Florida, § 713.13');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (208, 1, 'Al año de su registro', 'One year after it is recorded', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (208, 2, 'A los 90 días de su registro', '90 days after it is recorded', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (208, 3, 'A los seis meses de emitido el permiso de construcción', 'Six months after the building permit is issued', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (208, 4, 'Nunca expira mientras la obra siga en curso', 'It never expires while the Work remains in progress', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (209, 2, 209, 'Según el Florida Building Code, un permiso de construcción se considera en progreso activo cuando:', 'According to the Florida Building Code, a building permit is considered to be in active progress when:', 'En cambio, el permiso se invalida si la obra no comienza dentro de los seis meses de su emisión o si el trabajo se suspende o abandona por un período de seis meses.', 'By contrast, the permit becomes invalid if the Work does not commence within six months after its issuance, or if the work is suspended or abandoned for a period of six months.', 'Florida Building Code 2023, § 105.4.1.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (209, 1, 'El Contratista visita el sitio al menos una vez al mes', 'The Contractor visits the site at least once a month', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (209, 2, 'El permiso ha recibido una inspección aprobada dentro de los últimos 180 días', 'The permit has received an approved inspection within the last 180 days', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (209, 3, 'El Dueño certifica por escrito que el financiamiento sigue vigente', 'The Owner certifies in writing that financing remains in place', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (209, 4, 'El contrato de construcción no ha tenido modificaciones', 'The construction contract has had no modifications', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (210, 2, 210, '¿Quién determina el momento y la secuencia en que deben realizarse las inspecciones requeridas por el Florida Building Code en una obra?', 'Who determines the timing and sequence in which the inspections required by the Florida Building Code must be performed on a job?', 'La inspección final se realiza cuando el edificio está completo y listo para ser ocupado, paso previo a la emisión del Certificate of Occupancy.', 'The final inspection is performed when the building is complete and ready to be occupied, the step prior to issuance of the Certificate of Occupancy.', 'Florida Building Code 2023, § 110.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (210, 1, 'El Arquitecto del proyecto', 'The project Architect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (210, 2, 'El Contratista, según su cronograma de obra', 'The Contractor, according to its construction schedule', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (210, 3, 'El building official (oficial de construcción) de la jurisdicción', 'The building official of the jurisdiction', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (210, 4, 'El Dueño, al momento de firmar el contrato', 'The Owner, at the time it signs the contract', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (211, 2, 211, 'Según el § 1.6.2 del A201-2017, ¿cómo debe entregarse el aviso de un Claim (Notice of Claims) para que se considere debidamente notificado (duly served)?', 'Under § 1.6.2 of A201-2017, how must notice of a Claim (Notice of Claims) be delivered in order to be considered duly served?', 'Los avisos ordinarios del Contrato admiten varias formas de entrega, pero el aviso de Claims tiene una regla especial y más estricta: solo se tiene por debidamente servido si se entrega por correo certificado o registrado o por un courier que proporcione prueba de entrega.', 'Ordinary notices under the Contract may be delivered in several ways, but notice of Claims has a special and stricter rule: it is deemed duly served only if delivered by certified or registered mail or by a courier that provides proof of delivery.', 'AIA A201-2017, § 1.6.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (211, 1, 'Por cualquier medio escrito dirigido al representante designado, incluido el correo ordinario', 'By any written means addressed to the designated representative, including ordinary mail', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (211, 2, 'Entregándolo en persona al representante designado, con acuse de recibo verbal', 'By delivering it in person to the designated representative, with verbal acknowledgment of receipt', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (211, 3, 'Solo por correo certificado o registrado, o por mensajero (courier) que proporcione prueba de entrega, al representante designado de la parte a quien se dirige', 'Only by certified or registered mail, or by a courier that provides proof of delivery, to the designated representative of the party to whom it is addressed', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (211, 4, 'Por correo electrónico con confirmación automática de lectura del sistema', 'By email with automatic system read confirmation', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (212, 2, 212, 'Antes del inicio de la Obra, el Contratista pide por escrito al Dueño evidencia razonable de que hizo los arreglos financieros para cumplir sus obligaciones. Según el § 2.2.1 del A201-2017, mientras el Dueño no entregue esa evidencia:', 'Before the Work begins, the Contractor requests in writing that the Owner provide reasonable evidence that the Owner has made financial arrangements to fulfill the Owner''s obligations. Under § 2.2.1 of A201-2017, as long as the Owner does not provide that evidence:', 'La evidencia de financiamiento es una protección previa al arranque: si el Contratista la solicita por escrito antes de comenzar y el Dueño no la entrega, el Contratista no está obligado a iniciar la Obra, y el tiempo perdido se compensa con la extensión correspondiente del Plazo.', 'Evidence of financial arrangements is a protection before startup: if the Contractor requests it in writing before beginning and the Owner does not provide it, the Contractor is not obligated to commence the Work, and the time lost is compensated with the corresponding extension of the Contract Time.', 'AIA A201-2017, § 2.2.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (212, 1, 'El Contratista debe comenzar la Obra y presentar un Claim después si el Dueño no paga', 'The Contractor must commence the Work and file a Claim afterward if the Owner does not pay', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (212, 2, 'El Contratista no tiene obligación de comenzar la Obra hasta que el Dueño la proporcione, y si el inicio se demora por esa causa el Plazo del Contrato se extiende apropiadamente', 'The Contractor has no obligation to commence the Work until the Owner provides it, and if commencement is delayed for that reason, the Contract Time shall be extended appropriately', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (212, 3, 'El Contratista puede terminar el Contrato de inmediato y cobrar ganancia sobre la obra no ejecutada', 'The Contractor may terminate the Contract immediately and collect profit on the unperformed work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (212, 4, 'El Arquitecto debe certificar la solvencia del Dueño como condición del primer pago', 'The Architect must certify the Owner''s solvency as a condition of the first payment', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (213, 2, 213, 'Ya iniciada la Obra, el Dueño dejó de pagar conforme al Contrato y el Contratista le pidió por escrito la evidencia de arreglos financieros del § 2.2. Si el Dueño no la entrega dentro de los catorce días de la solicitud, según el § 2.2.2 el Contratista puede:', 'After the Work has begun, the Owner stopped paying in accordance with the Contract and the Contractor requested in writing the evidence of financial arrangements under § 2.2. If the Owner does not provide it within fourteen days of the request, under § 2.2.2 the Contractor may:', 'El remedio es la detención inmediata de la Obra tras esos 14 días sin evidencia, con ajuste de tiempo y de suma por los costos de la parada; y si la solicitud obedece a un cambio que altera materialmente la Suma, la detención puede limitarse a la porción de la Obra afectada por ese cambio.', 'The remedy is the immediate stoppage of the Work after those 14 days without evidence, with an adjustment of time and of the Contract Sum for the stoppage costs; and if the request arises from a change that materially alters the Contract Sum, the stoppage may be limited to the portion of the Work affected by that change.', 'AIA A201-2017, § 2.2.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (213, 1, 'Detener la Obra de inmediato y notificar al Dueño que la detuvo, con extensión del Plazo y aumento de la Suma por sus costos razonables de parada, demora y rearranque, más los intereses previstos', 'Stop the Work immediately and notify the Owner that it has stopped the Work, with an extension of the Contract Time and an increase of the Contract Sum for its reasonable costs of shutdown, delay, and start-up, plus the interest provided for', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (213, 2, 'Esperar treinta días adicionales antes de tomar cualquier medida', 'Wait an additional thirty days before taking any action', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (213, 3, 'Terminar el Contrato sin más trámite y reclamar el valor total del Contrato', 'Terminate the Contract without further formality and claim the full value of the Contract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (213, 4, 'Retener como prenda los materiales y equipos de los Subcontratistas hasta que el Dueño pague', 'Retain as security the Subcontractors'' materials and equipment until the Owner pays', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (214, 2, 214, 'El Contratista incumple o descuida la ejecución conforme a los Documentos y, recibido el aviso del Dueño, no comienza ni continúa la corrección de ese incumplimiento con diligencia y prontitud dentro de un período de diez días. Según el § 2.5 del A201-2017, el Dueño puede:', 'The Contractor defaults or neglects to carry out the Work in accordance with the Documents and, after receiving the Owner''s notice, does not begin and continue correction of that default with diligence and promptness within a ten-day period. Under § 2.5 of A201-2017, the Owner may:', 'Es la facultad de autoayuda del Dueño (carry out the Work): nace tras el período de corrección de diez días, exige la aprobación previa del Arquitecto tanto para la acción como para los montos, y si el Contratista disiente de la acción o de los costos, su vía es presentar un Claim bajo el Artículo 15.', 'It is the Owner''s self-help remedy (carry out the Work): it arises after the ten-day correction period, requires the Architect''s prior approval for both the action and the amounts, and if the Contractor disagrees with the action or the costs, its avenue is to file a Claim under Article 15.', 'AIA A201-2017, § 2.5');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (214, 1, 'Terminar el Contrato por causa sin más requisitos', 'Terminate the Contract for cause without further requirements', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (214, 2, 'Contratar a otro contratista y cargar el doble del costo al Contratista', 'Hire another contractor and charge the Contractor double the cost', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (214, 3, 'Suspender la Obra por tiempo indefinido sin ajuste alguno', 'Suspend the Work indefinitely without any adjustment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (214, 4, 'Corregir el incumplimiento por su cuenta, con aprobación previa del Arquitecto, reembolsándose del costo razonable (incluidos los servicios adicionales del Arquitecto) con cargo a los pagos, y si estos no alcanzan, el Contratista paga la diferencia', 'Correct the default on its own, with the Architect''s prior approval, reimbursing itself for the reasonable cost (including the Architect''s additional services) out of payments, and if those are insufficient, the Contractor shall pay the difference', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (215, 2, 215, 'Según el § 3.5.1 del A201-2017, la garantía del Contratista NO cubre el remedio de daños o defectos causados por:', 'Under § 3.5.1 of A201-2017, the Contractor''s warranty does NOT cover the remedying of damage or defects caused by:', 'La garantía asegura materiales y equipos de buena calidad y nuevos (salvo que los Documentos exijan o permitan otra cosa) y una Obra conforme y libre de defectos, salvo los inherentes a la calidad requerida o permitida; sus exclusiones expresas son el abuso, las alteraciones ajenas, el mantenimiento u operación inadecuados y el desgaste normal.', 'The warranty assures materials and equipment of good quality and new (unless the Documents require or permit otherwise) and Work that conforms and is free of defects, except those inherent in the quality required or permitted; its express exclusions are abuse, alterations by others, improper maintenance or operation, and ordinary wear and tear.', 'AIA A201-2017, § 3.5.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (215, 1, 'Defectos de mano de obra en la instalación de materiales nuevos', 'Workmanship defects in the installation of new materials', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (215, 2, 'Abuso, alteraciones a la Obra no ejecutadas por el Contratista, mantenimiento u operación inadecuados, o el desgaste normal por el uso', 'Abuse, alterations to the Work not performed by the Contractor, improper maintenance or operation, or ordinary wear and tear from use', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (215, 3, 'Materiales que no sean de buena calidad al momento de su instalación', 'Materials that are not of good quality at the time of their installation', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (215, 4, 'Trabajos que no se ajusten a los requisitos de los Documentos del Contrato', 'Work that does not conform to the requirements of the Contract Documents', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (216, 2, 216, 'Si el Contratista no presenta el cronograma de submittals (submittal schedule) o no entrega los submittals conforme al cronograma aprobado, según el § 3.10.2 del A201-2017:', 'If the Contractor does not submit the submittal schedule or does not submit submittals in accordance with the approved schedule, under § 3.10.2 of A201-2017:', 'El cronograma de submittals debe coordinarse con el cronograma de construcción y dejar al Arquitecto un tiempo razonable de revisión; quien incumple ese deber no puede luego convertir el tiempo de revisión en fundamento de más dinero o más plazo.', 'The submittal schedule must be coordinated with the construction schedule and allow the Architect a reasonable time for review; whoever breaches that duty cannot then convert the review time into grounds for more money or more time.', 'AIA A201-2017, § 3.10.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (216, 1, 'No tendrá derecho a aumento de la Suma del Contrato ni a extensión del Plazo con base en el tiempo requerido para la revisión de los submittals', 'It shall not be entitled to an increase in the Contract Sum or an extension of the Contract Time based on the time required for review of the submittals', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (216, 2, 'El Arquitecto pierde el derecho de revisar los submittals presentados tarde', 'The Architect loses the right to review submittals submitted late', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (216, 3, 'El Dueño debe pagar una penalidad diaria por cada día de revisión', 'The Owner must pay a daily penalty for each day of review', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (216, 4, 'El Contrato se convierte en uno de administración sin cronograma exigible', 'The Contract becomes a management contract with no enforceable schedule', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (217, 2, 217, 'Respecto de los Shop Drawings, Product Data y Samples, el § 3.12.4 del A201-2017 establece que:', 'With respect to Shop Drawings, Product Data, and Samples, § 3.12.4 of A201-2017 provides that:', 'Por eso la revisión del Arquitecto es limitada (§ 4.2.7) y por eso un submittal aprobado no modifica el Contrato: cualquier cambio real frente a los Documentos requiere Change Order, Construction Change Directive o un cambio menor autorizado.', 'That is why the Architect''s review is limited (§ 4.2.7) and why an approved submittal does not modify the Contract: any actual change from the Documents requires a Change Order, a Construction Change Directive, or an authorized minor change in the Work.', 'AIA A201-2017, § 3.12.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (217, 1, 'Al ser aprobados pasan a formar parte de los Documentos del Contrato', 'Once approved, they become part of the Contract Documents', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (217, 2, 'Sustituyen a las Especificaciones en caso de conflicto entre ambos', 'They supersede the Specifications in the event of a conflict between the two', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (217, 3, 'Tienen la misma jerarquía que los Planos para definir el alcance de la Obra', 'They have the same hierarchy as the Drawings to define the scope of the Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (217, 4, 'No son Documentos del Contrato: su propósito es demostrar cómo el Contratista propone ajustarse a la información dada y al concepto de diseño expresado en los Documentos del Contrato', 'They are not Contract Documents: their purpose is to show how the Contractor proposes to conform to the information given and the design concept expressed in the Contract Documents', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (218, 2, 218, 'Bajo el § 3.18.1 del A201-2017, la obligación del Contratista de indemnizar al Dueño, al Arquitecto y sus consultores alcanza los reclamos por lesiones corporales, enfermedad o muerte y por daños a propiedad tangible distinta de la propia Obra, pero solo:', 'Under § 3.18.1 of A201-2017, the Contractor''s obligation to indemnify the Owner, the Architect, and their consultants extends to claims for bodily injury, sickness, or death and for damage to tangible property other than the Work itself, but only:', 'La indemnización es proporcional a la negligencia: opera en la medida causada por la parte contratista y su cadena, incluye los honorarios de abogados y subsiste aunque el reclamo también haya sido causado en parte por una parte indemnizada.', 'The indemnification is proportional to negligence: it applies to the extent caused by the contracting party and its chain, includes attorneys'' fees, and subsists even though the claim was also caused in part by an indemnified party.', 'AIA A201-2017, § 3.18.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (218, 1, 'Cuando el daño haya sido causado exclusivamente por el Dueño', 'When the damage was caused exclusively by the Owner', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (218, 2, 'En la medida en que hayan sido causados por los actos u omisiones negligentes del Contratista, un Subcontratista o cualquier persona empleada por ellos o de quien respondan', 'To the extent caused by the negligent acts or omissions of the Contractor, a Subcontractor, or any person employed by them or for whom they may be liable', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (218, 3, 'Cuando exista sentencia firme que así lo declare', 'When a final judgment so declares', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (218, 4, 'Hasta el monto de la retención acumulada del proyecto', 'Up to the amount of the project''s accumulated retainage', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (219, 2, 219, 'Para que el Dueño ocupe o use una porción terminada o parcialmente terminada de la Obra bajo el § 9.9.1 del A201-2017 se requiere, entre otras condiciones:', 'For the Owner to occupy or use a completed or partially completed portion of the Work under § 9.9.1 of A201-2017, the following is required, among other conditions:', 'La ocupación parcial puede comenzar aunque la porción no esté sustancialmente terminada, si se cumplen esas condiciones y el Contratista no la retiene sin razón; y conforme al § 9.9.3, salvo acuerdo distinto, esa ocupación no constituye aceptación de Obra que no cumpla los Documentos del Contrato.', 'Partial occupancy may begin even if the portion is not substantially complete, if those conditions are met and the Contractor does not withhold it without reason; and under § 9.9.3, unless otherwise agreed, that occupancy does not constitute acceptance of Work that does not comply with the Contract Documents.', 'AIA A201-2017, §§ 9.9.1 y 9.9.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (219, 1, 'Que el Arquitecto haya emitido ya el certificado de pago final de esa porción', 'That the Architect has already issued the final certificate for payment for that portion', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (219, 2, 'Que la porción haya sido aceptada como si fuera la terminación sustancial de todo el Proyecto', 'That the portion has been accepted as if it were the Substantial Completion of the entire Project', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (219, 3, 'El consentimiento de la aseguradora y la autorización de las autoridades públicas con jurisdicción, con acuerdo escrito entre Dueño y Contratista sobre las responsabilidades de cada uno (pagos, retención, seguridad, mantenimiento, servicios y seguros)', 'The consent of the insurer and the authorization of the public authorities having jurisdiction, with a written agreement between the Owner and the Contractor as to each party''s responsibilities (payments, retainage, security, maintenance, services, and insurance)', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (219, 4, 'La renuncia escrita del Contratista a cualquier reclamo futuro sobre esa porción', 'The Contractor''s written waiver of any future claim regarding that portion', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (220, 2, 220, 'Durante la Obra, el Contratista encuentra un material o sustancia peligrosa oculta y no revelada, no tratada en los Documentos, frente a la cual las precauciones razonables serían inadecuadas para evitar lesiones corporales o la muerte previsibles (por ejemplo, asbesto o PCB). Según el § 10.3.1 del A201-2017, al reconocer la condición el Contratista debe:', 'During the Work, the Contractor encounters a concealed and undisclosed hazardous material or substance, not addressed in the Documents, against which reasonable precautions would be inadequate to prevent foreseeable bodily injury or death (for example, asbestos or PCBs). Under § 10.3.1 of A201-2017, upon recognizing the condition, the Contractor must:', 'La detención es inmediata pero se limita al área afectada; la responsabilidad del § 10.3 es del Dueño solo respecto de materiales no traídos al sitio por el Contratista, sus Subcontratistas, proveedores o quienes de ellos dependan.', 'The stoppage is immediate but is limited to the affected area; responsibility under § 10.3 rests with the Owner only with respect to material not brought to the site by the Contractor, its Subcontractors, suppliers, or those dependent on them.', 'AIA A201-2017, § 10.3.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (220, 1, 'Detener de inmediato la Obra en el área afectada y notificar la condición al Dueño y al Arquitecto', 'Immediately stop the Work in the affected area and notify the Owner and the Architect of the condition', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (220, 2, 'Retirar el material con su propio personal protegido y continuar la Obra sin interrumpirla', 'Remove the material with its own protected personnel and continue the Work without interrupting it', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (220, 3, 'Cubrir el material y denunciarlo al final del proyecto junto con el pago final', 'Cover the material and report it at the end of the project together with final payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (220, 4, 'Suspender toda la Obra del Proyecto y abandonar el sitio hasta que el Dueño resuelva', 'Suspend the entire Work of the Project and abandon the site until the Owner resolves it', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (221, 2, 221, 'Recibido el aviso de material peligroso del § 10.3.1, ¿qué establece el § 10.3.2 del A201-2017 sobre la verificación y la reanudación de la Obra?', 'Upon receiving the notice of hazardous material under § 10.3.1, what does § 10.3.2 of A201-2017 provide regarding verification and resumption of the Work?', 'El Dueño debe informar por escrito al Contratista y al Arquitecto los nombres y calificaciones de quienes harán las pruebas o la remoción, y si alguno objeta razonablemente a la persona propuesta, el Dueño deberá proponer otra sin objeción.', 'The Owner must inform the Contractor and the Architect in writing of the names and qualifications of those who will perform the testing or removal, and if any of them reasonably objects to the person proposed, the Owner shall propose another to whom there is no reasonable objection.', 'AIA A201-2017, § 10.3.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (221, 1, 'El Contratista contrata el laboratorio y reanuda la Obra cuando él lo estime seguro, sin ajuste de precio ni de plazo', 'The Contractor hires the laboratory and resumes the Work when it deems it safe, with no adjustment to price or time', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (221, 2, 'El Arquitecto verifica el material con su propio personal y ordena la reanudación verbalmente', 'The Architect verifies the material with its own personnel and verbally orders resumption', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (221, 3, 'La afianzadora decide si el material es peligroso y fija el costo de su remoción', 'The surety decides whether the material is hazardous and sets the cost of its removal', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (221, 4, 'El Dueño obtiene los servicios de un laboratorio licenciado para verificar la presencia o ausencia del material y, si está presente, para que sea vuelto inofensivo (rendered harmless); la Obra se reanuda por acuerdo escrito y, por Change Order, el Plazo se extiende apropiadamente y la Suma aumenta con los costos razonables adicionales de parada, demora y rearranque del Contratista', 'The Owner shall obtain the services of a licensed laboratory to verify the presence or absence of the material and, if it is present, to have it rendered harmless; the Work shall be resumed by written agreement and, by Change Order, the Contract Time shall be extended appropriately and the Contract Sum increased by the Contractor''s reasonable additional costs of shutdown, delay, and start-up', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (222, 2, 222, 'La renuncia de subrogación (waiver of subrogation) del § 11.3.1 del A201-2017 significa que el Dueño y el Contratista renuncian a todos sus derechos entre sí y frente a los Subcontratistas, el Arquitecto, sus consultores y los Contratistas Separados:', 'The waiver of subrogation in § 11.3.1 of A201-2017 means that the Owner and the Contractor waive all rights against each other and against the Subcontractors, the Architect, their consultants, and the Separate Contractors:', 'La renuncia se limita a la medida de la cobertura de propiedad existente, las pólizas no deben prohibirla y sigue siendo eficaz aunque la persona que renuncia tuviera un deber de indemnización o no hubiera pagado la prima directamente.', 'The waiver is limited to the extent of the existing property coverage, the policies must not prohibit it, and it remains effective even if the person waiving had a duty to indemnify or did not pay the premium directly.', 'AIA A201-2017, § 11.3.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (222, 1, 'Por cualquier daño a la Obra, esté o no asegurado', 'For any damage to the Work, whether or not it is insured', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (222, 2, 'Por daños causados por incendio u otras causas de pérdida, en la medida en que esas pérdidas estén cubiertas por el seguro de propiedad exigido por el Acuerdo u otro seguro de propiedad aplicable al Proyecto, salvo los derechos sobre el producto de ese seguro', 'For damage caused by fire or other causes of loss, to the extent that such losses are covered by the property insurance required by the Agreement or other property insurance applicable to the Project, except for rights to the proceeds of that insurance', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (222, 3, 'Solo por daños causados personalmente por el Dueño o por el Contratista', 'Only for damage personally caused by the Owner or by the Contractor', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (222, 4, 'Por daños consecuenciales derivados del atraso de la Obra', 'For consequential damages arising from delay of the Work', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (223, 2, 223, 'Si el Dueño prefiere aceptar una Obra que no está de acuerdo con los requisitos de los Documentos en lugar de exigir su retiro y corrección, según el § 12.3 del A201-2017:', 'If the Owner prefers to accept Work that is not in accordance with the requirements of the Documents instead of requiring its removal and correction, under § 12.3 of A201-2017:', 'La aceptación de obra no conforme es una facultad del Dueño alternativa a la corrección: se cambia la exigencia de rehacer el trabajo por una rebaja equitativa del precio, y la regla se aplica aun después del pago final.', 'Acceptance of nonconforming Work is an Owner power that is an alternative to correction: the requirement to redo the work is exchanged for an equitable reduction of the price, and the rule applies even after final payment.', 'AIA A201-2017, § 12.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (223, 1, 'La Suma del Contrato no puede modificarse después del pago final', 'The Contract Sum cannot be modified after final payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (223, 2, 'El Contratista debe corregirla de todos modos dentro del año de corrección', 'The Contractor must correct it anyway within the one-year correction period', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (223, 3, 'La Suma del Contrato se reduce en la medida apropiada y equitativa, y ese ajuste procede aunque ya se haya efectuado el pago final', 'The Contract Sum shall be reduced to the appropriate and equitable extent, and that adjustment applies even if final payment has already been made', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (223, 4, 'El Arquitecto queda liberado de toda responsabilidad por haber certificado esa Obra', 'The Architect is released from all responsibility for having certified that Work', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (224, 2, 224, 'Unas pruebas adicionales ordenadas conforme al § 13.4.2 revelan que la porción de la Obra probada no cumple los requisitos de los Documentos del Contrato. Según el § 13.4.3 del A201-2017, todos los costos derivados de ese incumplimiento, incluidos los de los procedimientos repetidos y la compensación por los servicios y gastos del Arquitecto, son a cargo de:', 'Additional testing ordered pursuant to § 13.4.2 reveals that the portion of the Work tested does not comply with the requirements of the Contract Documents. Under § 13.4.3 of A201-2017, all costs arising from that noncompliance, including those of repeated procedures and compensation for the Architect''s services and expenses, shall be borne by:', 'La regla general del § 13.4.2 pone las pruebas adicionales a costa del Dueño, pero se invierte cuando el resultado demuestra el incumplimiento: entonces el Contratista absorbe también las repeticiones y los servicios adicionales del Arquitecto que el fracaso hizo necesarios.', 'The general rule of § 13.4.2 places additional testing at the Owner''s cost, but it is reversed when the result demonstrates the noncompliance: then the Contractor also bears the repeated procedures and the Architect''s additional services that the failure made necessary.', 'AIA A201-2017, §§ 13.4.2 y 13.4.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (224, 1, 'El Contratista', 'The Contractor', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (224, 2, 'El Dueño, porque él autorizó las pruebas adicionales', 'The Owner, because the Owner authorized the additional testing', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (224, 3, 'La agencia independiente de pruebas que las ejecutó', 'The independent testing agency that performed it', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (224, 4, 'El Subcontratista que instaló la porción, en todos los casos y exclusivamente', 'The Subcontractor that installed the portion, in all cases and exclusively', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (225, 2, 225, 'Mientras un Claim está pendiente de resolución final, y salvo acuerdo escrito en contrario o lo previsto en el § 9.7 y en el Artículo 14, el § 15.1.4.1 del A201-2017 dispone que:', 'While a Claim is pending final resolution, and except as otherwise agreed in writing or as provided in § 9.7 and Article 14, § 15.1.4.1 of A201-2017 provides that:', 'Es la regla de continuidad (continuing contract performance): la disputa se tramita en paralelo sin paralizar ni la ejecución ni la corriente de pagos, sin perjuicio de los remedios especiales de detención por falta de pago y de terminación.', 'It is the rule of continuing contract performance: the dispute is processed in parallel without halting either performance or the flow of payments, without prejudice to the special remedies of stoppage for nonpayment and termination.', 'AIA A201-2017, § 15.1.4.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (225, 1, 'El Contratista puede detener la Obra y el Dueño puede retener todos los pagos', 'The Contractor may stop the Work and the Owner may withhold all payments', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (225, 2, 'El Claim congela automáticamente todos los plazos del Contrato', 'The Claim automatically freezes all Contract time limits', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (225, 3, 'El Initial Decision Maker asume la administración diaria de la Obra', 'The Initial Decision Maker assumes the day-to-day administration of the Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (225, 4, 'El Contratista debe proseguir diligentemente con la ejecución del Contrato y el Dueño debe continuar haciendo los pagos de acuerdo con los Documentos del Contrato', 'The Contractor shall proceed diligently with performance of the Contract and the Owner shall continue to make payments in accordance with the Contract Documents', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (226, 2, 226, 'En la renuncia mutua a los Claims por daños consecuenciales del § 15.1.7 del A201-2017, el Contratista renuncia a reclamar, entre otros conceptos, gastos de su oficina principal y pérdidas de financiamiento, negocio y reputación; sin embargo, esa renuncia NO abarca:', 'In the mutual waiver of Claims for consequential damages in § 15.1.7 of A201-2017, the Contractor waives claims for, among other items, its principal office expenses and losses of financing, business, and reputation; however, that waiver does NOT extend to:', 'Del lado del Dueño, la renuncia incluye rentas, pérdida de uso, ingresos, ganancia, financiamiento, negocio y reputación; y la propia sección aclara que nada en ella impide la imposición de liquidated damages cuando correspondan.', 'On the Owner''s side, the waiver includes rent, loss of use, income, profit, financing, business, and reputation; and the section itself clarifies that nothing in it prevents the imposition of liquidated damages when applicable.', 'AIA A201-2017, § 15.1.7');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (226, 1, 'Los daños liquidados pactados por atraso', 'Liquidated damages agreed upon for delay', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (226, 2, 'La ganancia anticipada que surge directamente de la Obra (anticipated profit arising directly from the Work)', 'Anticipated profit arising directly from the Work', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (226, 3, 'Cualquier reclamo presentado antes del pago final', 'Any claim submitted before final payment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (226, 4, 'Los costos de parada y rearranque por suspensión del Dueño', 'Shutdown and start-up costs due to suspension by the Owner', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (227, 2, 227, '¿Cuál de los siguientes Claims NO se refiere al Initial Decision Maker para decisión inicial, según el § 15.2.1 del A201-2017?', 'Which of the following Claims is NOT referred to the Initial Decision Maker for an initial decision, under § 15.2.1 of A201-2017?', 'Están excluidos de la decisión inicial los Claims cuya condición se descubre por primera vez después de expirado el período de corrección de la Obra del § 12.2.2 y los que surgen bajo los §§ 10.3, 10.4 y 11.5; para todos los demás, la decisión inicial sí es condición precedente de la mediación.', 'Excluded from the initial decision are Claims whose condition is first discovered after expiration of the period for correction of the Work in § 12.2.2 and those arising under §§ 10.3, 10.4, and 11.5; for all others, the initial decision is a condition precedent to mediation.', 'AIA A201-2017, § 15.2.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (227, 1, 'Un Claim del Contratista por aumento de la Suma derivado de un cambio ordenado en la Obra', 'A Contractor''s Claim for an increase in the Contract Sum arising from an ordered change in the Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (227, 2, 'Un Claim por extensión del Plazo causado por actos del Dueño', 'A Claim for an extension of the Contract Time caused by acts of the Owner', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (227, 3, 'Un Claim que surge bajo el § 10.3, de materiales y sustancias peligrosas', 'A Claim arising under § 10.3, hazardous materials and substances', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (227, 4, 'Un Claim por el costo de destapar una porción de la Obra que resultó conforme', 'A Claim for the cost of uncovering a portion of the Work that proved to be conforming', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (228, 2, 228, 'El Subcontratista pide por escrito al Contratista la información necesaria para evaluar, avisar o hacer valer sus derechos de gravamen (mechanic''s lien). Según el § 3.3.6 del A401-2017, el Contratista debe entregarla:', 'The Subcontractor requests in writing from the Contractor the information necessary to evaluate, give notice of, or enforce its mechanic''s lien rights. Under § 3.3.6 of A401-2017, the Contractor must provide it:', 'Si el Contratista no tiene esa información, debe solicitarla al Dueño conforme al Artículo 2 del A201 y entregar prontamente al Subcontratista la que reciba; sin el título registrado y el interés del Dueño, el Subcontratista no puede perfeccionar su lien en Florida.', 'If the Contractor does not have that information, it must request it from the Owner in accordance with Article 2 of A201 and promptly deliver to the Subcontractor whatever it receives; without record title and the Owner''s interest, the Subcontractor cannot perfect its lien in Florida.', 'AIA A401-2017, § 3.3.6');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (228, 1, 'Dentro de los treinta días de recibida la solicitud escrita, o antes si la ley lo exige, incluyendo una declaración correcta del título legal registrado de la propiedad (el sitio) y del interés del Dueño en ella', 'Within thirty days of receipt of the written request, or sooner if the law requires it, including a correct statement of the record legal title to the property (the site) and the Owner''s interest in it', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (228, 2, 'Solo cuando el Dueño lo autorice expresamente por escrito', 'Only when the Owner expressly authorizes it in writing', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (228, 3, 'Dentro de los siete días laborables siguientes al pago final del subcontrato', 'Within seven business days following final payment under the subcontract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (228, 4, 'Únicamente a través del Arquitecto, que es quien custodia esa información', 'Only through the Architect, who is the custodian of that information', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (229, 2, 229, 'Según el § 3.4.1 del A401-2017, los liquidated damages previstos en el Contrato Principal pueden cargarse al Subcontratista:', 'Under § 3.4.1 of A401-2017, liquidated damages provided in the Prime Contract may be charged to the Subcontractor:', 'Es la regla de causalidad del traslado de daños liquidados: el flujo descendente (flow-down) no convierte al Subcontratista en asegurador del atraso total del proyecto, sino solo del atraso que él mismo provoca dentro de su porción.', 'It is the causation rule for the pass-through of liquidated damages: the flow-down does not make the Subcontractor an insurer of the overall project delay, but only of the delay that it itself causes within its portion.', 'AIA A401-2017, § 3.4.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (229, 1, 'En su totalidad, si el proyecto termina tarde por cualquier causa', 'In their entirety, if the project finishes late for any cause', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (229, 2, 'En la proporción que fije el Arquitecto al final del proyecto', 'In the proportion set by the Architect at the end of the project', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (229, 3, 'Solo si el Subcontratista firmó una garantía personal de cumplimiento', 'Only if the Subcontractor signed a personal guaranty of performance', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (229, 4, 'Solo en la medida en que hayan sido causados por el Subcontratista o por cualquier persona de quien este responda, y en ningún caso por demoras o causas ajenas al alcance de su Subcontrato', 'Only to the extent they were caused by the Subcontractor or by any person for whom the Subcontractor may be liable, and in no case for delays or causes outside the scope of its Subcontract', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (230, 2, 230, 'Un Claim del Subcontratista pasará a formar parte de un Claim que el Contratista está obligado a presentar bajo el Contrato Principal dentro de un plazo y una forma determinados. Según el § 5.3 del A401-2017, ese Claim del Subcontratista debe ser recibido por el Contratista:', 'A Subcontractor''s Claim will become part of a Claim that the Contractor is required to submit under the Prime Contract within a specified time and in a specified form. Under § 5.3 of A401-2017, that Subcontractor''s Claim must be received by the Contractor:', 'El margen de dos días laborables es lo que permite al Contratista incorporar el reclamo del Subcontratista y cumplir su propio plazo; si el Subcontratista no lo presenta a tiempo, queda sujeto a las mismas consecuencias que afectarían al Contratista.', 'The two-business-day margin is what allows the Contractor to incorporate the Subcontractor''s claim and meet its own deadline; if the Subcontractor does not submit it in time, it is subject to the same consequences that would affect the Contractor.', 'AIA A401-2017, § 5.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (230, 1, 'El mismo día en que vence el plazo del Contratista bajo el Contrato Principal', 'On the same day the Contractor''s deadline under the Prime Contract expires', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (230, 2, 'No menos de dos días laborables antes del momento en que debe presentarse el Claim del Contratista', 'Not less than two business days before the time at which the Contractor''s Claim must be submitted', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (230, 3, 'Dentro de los veintiún días siguientes al evento que lo origina', 'Within twenty-one days following the event giving rise to it', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (230, 4, 'Solo después de que el Initial Decision Maker se pronuncie sobre el Claim del Contratista', 'Only after the Initial Decision Maker has ruled on the Contractor''s Claim', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (231, 2, 231, 'Según el § 7.1 del A401-2017, además de las causales que el Contrato Principal le reconoce al Contratista frente al Dueño, el Subcontratista puede terminar el Subcontrato por falta de pago de las sumas debidas bajo el Subcontrato durante un período de:', 'Under § 7.1 of A401-2017, in addition to the grounds that the Prime Contract affords the Contractor against the Owner, the Subcontractor may terminate the Subcontract for failure to pay amounts due under the Subcontract for a period of:', 'Si la terminación ejercida por el Subcontratista obedece a una causa que no es su culpa ni la de su cadena, puede recuperar del Contratista el pago por la Obra ejecutada, la pérdida probada en materiales y equipos, la ganancia razonable sobre la Obra no ejecutada y los costos derivados de la terminación.', 'If the termination exercised by the Subcontractor arises from a cause that is not the fault of the Subcontractor or of those in its chain, it may recover from the Contractor payment for the Work performed, proven loss on materials and equipment, reasonable profit on the unperformed Work, and the costs arising from the termination.', 'AIA A401-2017, § 7.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (231, 1, 'Siete días', 'Seven days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (231, 2, 'Treinta días', 'Thirty days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (231, 3, 'Sesenta días o más', 'Sixty days or more', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (231, 4, 'Noventa días o más', 'Ninety days or more', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (232, 2, 232, 'Según el § 12.1.4 del A401-2017, el Subcontratista debe entregar los certificados de seguro que acreditan el cumplimiento del Artículo 12 en estos momentos:', 'Under § 12.1.4 of A401-2017, the Subcontractor must furnish the insurance certificates evidencing compliance with Article 12 at the following times:', 'Además, con la Solicitud Final de Pago debe presentarse un certificado adicional que evidencie la continuación de la cobertura de responsabilidad, incluida la de operaciones terminadas (completed operations), y luego al renovarse esa cobertura hasta que expire el período exigido.', 'In addition, with the Final Application for Payment an additional certificate must be submitted evidencing continuation of liability coverage, including completed operations coverage, and thereafter as that coverage is renewed until the required period expires.', 'AIA A401-2017, § 12.1.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (232, 1, 'Antes de comenzar su Obra, al renovar o reemplazar cada póliza requerida y cuando el Contratista lo pida por escrito, debiendo mostrar los certificados al Contratista y al Dueño como asegurados adicionales en su responsabilidad civil general comercial (CGL) y en cualquier póliza excess o umbrella', 'Before commencing its Work, upon renewal or replacement of each required policy, and when the Contractor requests it in writing, showing the certificates to the Contractor and to the Owner as additional insureds on its commercial general liability (CGL) insurance and on any excess or umbrella policy', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (232, 2, 'Solamente al momento de firmar el Subcontrato', 'Only at the time of signing the Subcontract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (232, 3, 'Solamente junto con la solicitud de pago final', 'Only together with the final payment application', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (232, 4, 'Cuando el Arquitecto lo solicite en la reunión previa a la construcción', 'When the Architect requests it at the preconstruction meeting', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (233, 2, 233, 'Un licitante descubre una ambigüedad en los Documentos de Licitación. Según los §§ 3.2.2 y 3.2.3 del A701-2018, su solicitud escrita de aclaración o interpretación debe ser recibida por el Arquitecto al menos ____ antes de la fecha de recepción de ofertas, y toda modificación o interpretación solo será vinculante si se hace mediante:', 'A bidder discovers an ambiguity in the Bidding Documents. Under §§ 3.2.2 and 3.2.3 of A701-2018, its written request for clarification or interpretation must be received by the Architect at least ____ before the date for receipt of bids, and any modification or interpretation will be binding only if made by means of:', 'El mismo principio rige para las sustituciones aprobadas antes de la apertura (§ 3.3.4): fuera de la Adenda no existe interpretación ni aprobación en la que el licitante pueda apoyarse, por muy oficial que parezca la comunicación.', 'The same principle governs substitutions approved before the opening of bids (§ 3.3.4): outside an Addendum there is no interpretation or approval on which the bidder may rely, however official the communication may appear.', 'AIA A701-2018, §§ 3.2.2 y 3.2.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (233, 1, 'Cuatro días; una carta aclaratoria del Arquitecto', 'Four days; a clarifying letter from the Architect', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (233, 2, 'Diez días; un memorando del Dueño a todos los licitantes', 'Ten days; a memorandum from the Owner to all bidders', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (233, 3, 'Catorce días; la Change Order correspondiente', 'Fourteen days; the corresponding Change Order', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (233, 4, 'Siete días; una Adenda (Addendum), porque las hechas de cualquier otra manera no son vinculantes y los licitantes no deben confiar en ellas', 'Seven days; an Addendum, since those made in any other manner are not binding and bidders shall not rely upon them', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (234, 2, 234, 'Salvo que la ley lo prohíba, según el § 5.2 del A701-2018 (Rejection of Bids), al considerar las ofertas recibidas el Dueño tiene derecho a:', 'Unless prohibited by law, under § 5.2 of A701-2018 (Rejection of Bids), when considering the bids received, the Owner has the right to:', 'Ese derecho de rechazo total es el complemento de su facultad de adjudicación del § 5.3.1: puede dispensar informalidades y aceptar la oferta que a su juicio más convenga a sus intereses, sin quedar atado a aceptar alguna.', 'That right of total rejection complements its award power under § 5.3.1: it may waive informalities and accept the bid that in its judgment best serves its interests, without being bound to accept any bid.', 'AIA A701-2018, § 5.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (234, 1, 'Rechazar cualquiera o todas las ofertas (Bids)', 'Reject any or all bids (Bids)', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (234, 2, 'Adjudicar obligatoriamente a la oferta más baja presentada', 'Mandatorily award to the lowest bid submitted', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (234, 3, 'Devolver todas las garantías de oferta solo si adjudica el Contrato', 'Return all bid guarantees only if it awards the Contract', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (234, 4, 'Rechazar únicamente las ofertas que presenten errores aritméticos', 'Reject only bids that contain arithmetic errors', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (235, 2, 235, 'Según el § 5.3.1 del A701-2018, la intención declarada del Dueño al adjudicar es hacerlo al:', 'Under § 5.3.1 of A701-2018, the Owner''s declared intent when awarding is to award to the:', 'Responsive significa que la oferta cumple lo pedido en los Documentos de Licitación y responsible, que el licitante es capaz y solvente para ejecutar; la adjudicación sobre esa base es distinta de los Alternates del § 5.3.2, que fijan cómo se calcula quién es ese licitante más bajo.', 'Responsive means that the bid complies with what is requested in the Bidding Documents, and responsible, that the bidder is capable and solvent to perform; an award on that basis is distinct from the Alternates under § 5.3.2, which establish how it is determined who that lowest bidder is.', 'AIA A701-2018, § 5.3.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (235, 1, 'Licitante con la oferta más baja, sin evaluación adicional', 'Bidder with the lowest bid, without additional evaluation', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (235, 2, 'Licitante que ofrezca el plazo de ejecución más corto', 'Bidder offering the shortest performance period', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (235, 3, 'Licitante responsable más bajo (lowest responsive and responsible Bidder) cuya oferta se ajustó a los Documentos de Licitación, pudiendo el Dueño dispensar informalidades e irregularidades y aceptar la oferta que a su juicio sea de mayor interés para él', 'Lowest responsive and responsible Bidder whose bid conformed to the Bidding Documents, the Owner being permitted to waive informalities and irregularities and to accept the bid that in its judgment is of greatest interest to it', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (235, 4, 'Licitante que presente la menor cantidad de alternates solicitados', 'Bidder submitting the fewest requested alternates', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (236, 2, 236, 'Según el § 5.2.2 del A101-2017, una vez que el Contratista ha ejecutado plenamente el Contrato (salvo su deber de corrección del Artículo 12 del A201 y otros requisitos que se extiendan más allá del pago final) y el Arquitecto ha emitido el Certificate for Payment final, el pago final del Dueño debe hacerse a más tardar:', 'Under § 5.2.2 of A101-2017, once the Contractor has fully performed the Contract (except for its obligation to correct the Work under Article 12 of A201 and other requirements extending beyond final payment) and the Architect has issued the final Certificate for Payment, the Owner''s final payment must be made no later than:', 'El pago final constituye la totalidad del saldo no pagado de la Suma del Contrato; el A101 fija así un límite temporal cierto que el A201 por sí solo no contiene, y los pagos vencidos y no pagados devengan el interés previsto en el § 5.3 del Acuerdo.', 'Final payment constitutes the entire unpaid balance of the Contract Sum; A101 thus sets a definite time limit that A201 alone does not contain, and amounts due and unpaid bear the interest provided in § 5.3 of the Agreement.', 'AIA A101-2017, § 5.2.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (236, 1, 'Treinta días después de la emisión del Certificate for Payment final del Arquitecto', 'Thirty days after issuance of the Architect''s final Certificate for Payment', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (236, 2, 'Siete días después de la emisión de ese certificado final', 'Seven days after issuance of that final certificate', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (236, 3, 'Al cumplirse un año de la terminación sustancial de la Obra', 'Upon reaching one year from Substantial Completion of the Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (236, 4, 'Cuando el building official emita el certificado de ocupación definitivo', 'When the building official issues the final certificate of occupancy', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (237, 2, 237, 'En un proyecto bajo el A102-2017 (costo de la obra más honorario con GMP), ¿cuál de los siguientes conceptos NO forma parte del Costo de la Obra reembolsable, según su Artículo 8?', 'In a project under A102-2017 (cost of the work plus a fee with a GMP), which of the following items is NOT part of the reimbursable Cost of the Work, under its Article 8?', 'El Artículo 8 excluye también los salarios y gastos de la oficina principal del Contratista, los gastos generales no incluidos expresamente en el Artículo 7, sus gastos de capital (incluidos los intereses sobre el capital empleado en la Obra) y todo costo que, sin Change Order aprobada, haría exceder el precio máximo garantizado.', 'Article 8 also excludes the Contractor''s principal office salaries and expenses, general expenses not expressly included in Article 7, its capital expenses (including interest on capital employed in the Work), and any cost that, without an approved Change Order, would cause the Guaranteed Maximum Price to be exceeded.', 'AIA A102-2017, Artículo 8 (§ 8.1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (237, 1, 'La mano de obra del personal de campo asignado a la obra en el sitio', 'The labor of field personnel assigned to the work at the site', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (237, 2, 'El alquiler de la maquinaria y el equipo necesarios para ejecutar la Obra', 'The rental of machinery and equipment necessary to perform the Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (237, 3, 'Los materiales y equipos incorporados permanentemente a la Obra', 'Materials and equipment permanently incorporated into the Work', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (237, 4, 'Los costos debidos a la negligencia del Contratista, de los Subcontratistas o de los proveedores, o al incumplimiento de una responsabilidad específica del Contrato', 'Costs due to the negligence of the Contractor, Subcontractors, or suppliers, or to the failure to fulfill a specific responsibility under the Contract', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (238, 2, 238, 'Un equipo debe reemplazarse de inmediato en una situación de emergencia y no es posible obtener antes el permiso correspondiente. Según el § 105.2.1 del Florida Building Code, la solicitud de permiso debe presentarse al building official:', 'Equipment must be replaced immediately in an emergency situation and it is not possible to obtain the corresponding permit beforehand. Under § 105.2.1 of the Florida Building Code, the permit application must be submitted to the building official:', 'La emergencia permite ejecutar primero el reemplazo o la reparación indispensable, pero no elimina el permiso: solo desplaza su solicitud al siguiente día laborable, y el trabajo ejecutado queda igualmente sujeto a inspección y al cumplimiento del código.', 'The emergency allows the indispensable replacement or repair to be performed first, but it does not eliminate the permit: it only postpones its application to the next working business day, and the work performed remains equally subject to inspection and to compliance with the code.', 'Florida Building Code 2023, § 105.2.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (238, 1, 'Dentro de los treinta días siguientes a la reparación', 'Within thirty days following the repair', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (238, 2, 'Nunca, porque la emergencia exime por completo del permiso', 'Never, because the emergency completely exempts it from the permit', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (238, 3, 'Dentro del siguiente día laborable (next working business day)', 'Within the next working business day', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (238, 4, 'Antes de realizar la reparación, sin excepción alguna', 'Before performing the repair, without any exception', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (239, 2, 239, 'Según el § 110.1 del Florida Building Code, la construcción o el trabajo para el cual se requiere permiso debe permanecer, hasta ser aprobado:', 'Under § 110.1 of the Florida Building Code, the construction or work for which a permit is required must remain, until it is approved:', 'Ni el building official ni la jurisdicción responden por los gastos de remover o reponer material que haya que retirar para poder inspeccionar; y una inspección aprobada no debe interpretarse como aprobación de una violación del código o de otras ordenanzas.', 'Neither the building official nor the jurisdiction is liable for the expenses of removing or replacing material that has to be removed in order to inspect it; and an approved inspection must not be construed as approval of a violation of the code or of other ordinances.', 'Florida Building Code 2023, § 110.1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (239, 1, 'Cubierto y protegido contra la intemperie para no deteriorarse', 'Covered and protected from the weather so that it does not deteriorate', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (239, 2, 'Sellado y fuera del alcance de los inspectores hasta la inspección final', 'Sealed and out of reach of the inspectors until the final inspection', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (239, 3, 'Ocupado solo por el personal esencial del Contratista', 'Occupied only by the Contractor''s essential personnel', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (239, 4, 'Accesible y expuesto para fines de inspección, siendo deber del solicitante del permiso mantenerlo así', 'Accessible and exposed for inspection purposes, it being the permit applicant''s duty to keep it that way', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (240, 2, 240, 'Según el § 111.3 del Florida Building Code (Temporary occupancy), el building official está autorizado a emitir un certificado de ocupación temporal (temporary certificate of occupancy):', 'Under § 111.3 of the Florida Building Code (Temporary occupancy), the building official is authorized to issue a temporary certificate of occupancy:', 'El certificado temporal permite ocupar con seguridad una parte del edificio mientras se completa el resto de la obra permitida; ocupar la estructura sin ese certificado o sin el certificado de ocupación definitivo constituye una violación del código.', 'The temporary certificate allows safe occupancy of a part of the building while the rest of the permitted work is completed; occupying the structure without that certificate or without the final certificate of occupancy constitutes a violation of the code.', 'Florida Building Code 2023, § 111.3');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (240, 1, 'Solo cuando la totalidad de la obra del permiso esté terminada y pagada', 'Only when all of the work under the permit is finished and paid for', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (240, 2, 'Antes de que se complete la totalidad de la obra cubierta por el permiso, siempre que la porción o porciones puedan ocuparse de manera segura, fijando el período durante el cual el certificado temporal será válido', 'Before the entirety of the work covered by the permit is completed, provided that the portion or portions can be safely occupied, setting the period during which the temporary certificate will be valid', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (240, 3, 'Únicamente para edificios de una planta y uso residencial', 'Only for one-story buildings for residential use', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (240, 4, 'A solicitud del Arquitecto, sin intervención del Contratista ni fijación de plazo', 'At the Architect''s request, without involvement of the Contractor and without setting a time limit', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (241, 3, 241, 'Según OSHA 29 CFR 1926, en construcción la protección contra caídas debe proveerse cuando el trabajador está a una altura de:', 'According to OSHA 29 CFR 1926, in construction, fall protection must be provided when the worker is at a height of:', 'La regla general de construcción (1926.501) exige protección contra caídas a los 6 pies: barandas, redes de seguridad o sistema personal de detención de caídas.', 'The general construction rule (1926.501) requires fall protection at 6 feet: guardrails, safety nets or a personal fall arrest system.', 'OSHA 29 CFR 1926, Subparte M');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (241, 1, '4 pies o más', '4 feet or more', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (241, 2, '6 pies o más', '6 feet or more', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (241, 3, '10 pies o más', '10 feet or more', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (241, 4, 'Solo en techos inclinados', 'Only on sloped roofs', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (242, 3, 242, 'En una excavación, los sistemas de protección contra derrumbes (taludes, entibado o cajones de zanja) son obligatorios a partir de una profundidad de:', 'In an excavation, cave-in protective systems (sloping, shoring or trench boxes) are mandatory starting at a depth of:', 'OSHA exige sistema de protección en zanjas de 5 pies o más de profundidad (y también en menores si la persona competente detecta riesgo de derrumbe).', 'OSHA requires a protective system in trenches 5 feet or more in depth (and also in shallower ones if the competent person detects a cave-in risk).', 'OSHA 29 CFR 1926, Subparte P');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (242, 1, '3 pies', '3 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (242, 2, '4 pies', '4 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (242, 3, '5 pies', '5 feet', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (242, 4, '8 pies', '8 feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (243, 3, 243, 'Una escalera portátil usada para acceder a un nivel superior debe extenderse por encima de ese nivel al menos:', 'A portable ladder used to access an upper level must extend above that level by at least:', 'Los rieles laterales deben extenderse mínimo 3 pies (36 pulgadas) sobre la superficie de desembarco para dar un agarre seguro al subir y bajar.', 'The side rails must extend at least 3 feet (36 inches) above the landing surface to provide a secure handhold when stepping up and down.', 'OSHA 29 CFR 1926.1053');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (243, 1, '1 pie (12 pulgadas)', '1 foot (12 inches)', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (243, 2, '2 pies (24 pulgadas)', '2 feet (24 inches)', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (243, 3, '3 pies (36 pulgadas)', '3 feet (36 inches)', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (243, 4, 'No necesita extenderse', 'It does not need to extend', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (244, 3, 244, 'La prueba de asentamiento (slump test) del concreto fresco mide:', 'The slump test of fresh concrete measures:', 'El slump test mide la consistencia/trabajabilidad del concreto fresco. La resistencia se verifica con cilindros de prueba rotos en laboratorio, no con el cono de asentamiento.', 'The slump test measures the consistency/workability of the fresh concrete. Strength is verified with test cylinders broken in a laboratory, not with the slump cone.', 'Principles & Practices of Commercial Construction');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (244, 1, 'La resistencia a compresión a 28 días', 'The compressive strength at 28 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (244, 2, 'La consistencia y trabajabilidad de la mezcla', 'The consistency and workability of the mix', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (244, 3, 'El contenido de aire del concreto endurecido', 'The air content of the hardened concrete', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (244, 4, 'El tiempo de fraguado final', 'The final setting time', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (245, 3, 245, 'Una barra de refuerzo grado 60 tiene una resistencia de fluencia (yield strength) de:', 'A Grade 60 reinforcing bar has a yield strength of:', 'El número del grado indica la fluencia en miles de psi: grado 60 = 60.000 psi. Es el dato que el examen espera que leas directo de la designación de la barra.', 'The grade number indicates the yield strength in thousands of psi: Grade 60 = 60,000 psi. It is the value the exam expects you to read directly from the bar''s designation.', 'Principles & Practices of Commercial Construction');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (245, 1, '6.000 psi', '6,000 psi', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (245, 2, '40.000 psi', '40,000 psi', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (245, 3, '60.000 psi', '60,000 psi', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (245, 4, '600.000 psi', '600,000 psi', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (246, 3, 246, 'En un programa CPM, la ruta crítica es:', 'In a CPM schedule, the critical path is:', 'La ruta crítica es la cadena más larga de actividades dependientes; cualquier atraso en ella atrasa el proyecto entero, porque sus actividades tienen holgura cero.', 'The critical path is the longest chain of dependent activities; any delay in it delays the entire project, because its activities have zero float.', 'Principles & Practices of Commercial Construction · Programación');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (246, 1, 'La ruta con más actividades', 'The path with the most activities', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (246, 2, 'La secuencia de actividades más larga, que determina la duración mínima del proyecto', 'The longest sequence of activities, which determines the minimum duration of the project', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (246, 3, 'La ruta con mayor costo acumulado', 'The path with the highest accumulated cost', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (246, 4, 'La lista de actividades ya completadas', 'The list of activities already completed', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (247, 3, 247, 'Sobre las cerchas (trusses) de madera con placas metálicas, la guía BCSI establece que:', 'Regarding wood trusses with metal plates, the BCSI guide establishes that:', 'Las cerchas son componentes diseñados por ingeniería: cortarlas, perforarlas o modificarlas sin aprobación invalida el diseño. La BCSI regula su manejo, instalación y arriostramiento temporal y permanente.', 'Trusses are engineered components: cutting, drilling or modifying them without approval invalidates the design. The BCSI governs their handling, installation and temporary and permanent bracing.', 'BCSI — Building Component Safety Information');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (247, 1, 'Pueden cortarse en obra para ajustarlas al diseño', 'They may be cut in the field to adjust them to the design', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (247, 2, 'No deben cortarse ni modificarse sin la aprobación de un profesional de diseño/ingeniería', 'They must not be cut or modified without the approval of a design/engineering professional', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (247, 3, 'Solo requieren arriostramiento al final de la instalación', 'They only require bracing at the end of installation', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (247, 4, 'Su arriostramiento temporal es opcional', 'Their temporary bracing is optional', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (248, 3, 248, '¿Por qué el Florida Building Code pone tanto peso en las cargas de viento?', 'Why does the Florida Building Code place so much weight on wind loads?', 'Florida es zona de huracanes: el código exige que componentes, conexiones y la trayectoria continua de cargas resistan las presiones de viento de diseño, del techo a la cimentación.', 'Florida is a hurricane zone: the code requires that components, connections and the continuous load path resist the design wind pressures, from the roof to the foundation.', 'Florida Building Code — Building');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (248, 1, 'Porque Florida prohíbe los techos planos', 'Because Florida prohibits flat roofs', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (248, 2, 'Porque la trayectoria de cargas (load path) debe llevar las fuerzas del huracán desde el techo hasta la cimentación en una zona de alta velocidad de viento', 'Because the load path must carry the hurricane forces from the roof to the foundation in a high wind speed zone', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (248, 3, 'Solo aplica a edificios frente al mar', 'It only applies to oceanfront buildings', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (248, 4, 'Es un requisito únicamente comercial', 'It is a requirement that is only commercial', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (249, 3, 249, 'Al recibir un tema de energía en el examen (envolvente, aislamiento, eficiencia), el volumen del FBC donde se busca la respuesta es:', 'When you get an energy topic on the exam (envelope, insulation, efficiency), the FBC volume where the answer is found is:', 'El volumen Energy Conservation regula la envolvente térmica, el aislamiento y la eficiencia de sistemas. Saber en qué volumen vive cada tema es la mitad de la técnica de examen.', 'The Energy Conservation volume regulates the thermal envelope, insulation and system efficiency. Knowing in which volume each topic lives is half of the exam technique.', 'Florida Building Code — Energy Conservation');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (249, 1, 'FBC — Accessibility', 'FBC — Accessibility', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (249, 2, 'FBC — Existing Building', 'FBC — Existing Building', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (249, 3, 'FBC — Energy Conservation', 'FBC — Energy Conservation', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (249, 4, 'FBC — Residential, siempre', 'FBC — Residential, always', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (250, 3, 250, 'Un juego de planos trae una planta dibujada a escala 1/4" = 1''-0". Una pared que en el papel mide 3 pulgadas mide en la obra real:', 'A set of drawings shows a floor plan drawn at a scale of 1/4" = 1''-0". A wall that measures 3 inches on paper measures in the actual work:', 'A 1/4" = 1 pie, cada pulgada en papel equivale a 4 pies reales. 3 pulgadas × 4 = 12 pies. La lectura de escalas es parte fija del bloque de planos y especificaciones.', 'At 1/4" = 1 foot, each inch on paper equals 4 real feet. 3 inches × 4 = 12 feet. Reading scales is a fixed part of the drawings and specifications block.', 'Principles & Practices of Commercial Construction · Lectura de planos');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (250, 1, '3 pies', '3 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (250, 2, '6 pies', '6 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (250, 3, '12 pies', '12 feet', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (250, 4, '24 pies', '24 feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (251, 3, 251, 'Según OSHA 29 CFR 1926.502(b)(1), ¿a qué altura sobre la superficie de trabajo o de tránsito debe quedar el borde superior del riel superior de un sistema de barandas?', 'According to OSHA 29 CFR 1926.502(b)(1), at what height above the walking/working surface must the top edge of the top rail of a guardrail system be located?', 'La norma fija el riel superior a 42 pulgadas, con una tolerancia de más o menos 3 pulgadas, sobre la superficie de trabajo. El riel intermedio se coloca aproximadamente a mitad de esa altura.', 'The standard sets the top rail at 42 inches, with a tolerance of plus or minus 3 inches, above the working surface. The midrail is placed approximately at half that height.', 'OSHA 29 CFR 1926.502(b)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (251, 1, '36 pulgadas', '36 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (251, 2, '39 pulgadas', '39 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (251, 3, '42 pulgadas (±3 pulgadas)', '42 inches (±3 inches)', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (251, 4, '48 pulgadas', '48 inches', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (252, 3, 252, 'Cuando se instalan redes de seguridad como sistema de protección contra caídas, ¿a qué distancia máxima por debajo de la superficie de trabajo deben colocarse?', 'When safety nets are installed as a fall protection system, what is the maximum distance below the working surface at which they must be placed?', 'Las redes se instalan tan cerca como sea posible de la superficie de trabajo, pero nunca a más de 30 pies por debajo de ese nivel.', 'Nets are installed as close as practicable below the working surface, but never more than 30 feet below that level.', 'OSHA 29 CFR 1926.502(c)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (252, 1, '30 pies', '30 feet', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (252, 2, '10 pies', '10 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (252, 3, '20 pies', '20 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (252, 4, '45 pies', '45 feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (253, 3, 253, '¿Qué capacidad mínima de soporte exige OSHA para los puntos de anclaje de un sistema personal de detención de caídas?', 'What minimum support capacity does OSHA require for the anchorage points of a personal fall arrest system?', 'Cada anclaje debe soportar al menos 5.000 libras por empleado conectado, o bien ser diseñado, instalado y usado bajo la supervisión de una persona calificada como parte de un sistema completo con factor de seguridad de al menos dos.', 'Each anchorage must be capable of supporting at least 5,000 pounds per employee attached, or be designed, installed, and used under the supervision of a qualified person as part of a complete system maintaining a safety factor of at least two.', 'OSHA 29 CFR 1926.502(d)(15)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (253, 1, '1.800 libras por empleado', '1,800 pounds per employee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (253, 2, '2.500 libras por empleado', '2,500 pounds per employee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (253, 3, '3.600 libras por empleado', '3,600 pounds per employee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (253, 4, '5.000 libras por empleado', '5,000 pounds per employee', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (254, 3, 254, '¿Qué fuerza mínima debe resistir sin fallar el riel superior de una baranda, aplicada hacia afuera o hacia abajo a no más de 2 pulgadas del borde superior?', 'What minimum force must the top rail of a guardrail withstand without failure, applied outward or downward within 2 inches of the top edge?', 'El riel superior debe resistir al menos 200 libras de fuerza sin fallar. El riel intermedio, por su parte, debe resistir al menos 150 libras.', 'The top rail must withstand at least 200 pounds of force without failure. The midrail, in turn, must withstand at least 150 pounds.', 'OSHA 29 CFR 1926.502(b)(3)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (254, 1, '150 libras', '150 pounds', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (254, 2, '200 libras', '200 pounds', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (254, 3, '250 libras', '250 pounds', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (254, 4, '500 libras', '500 pounds', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (255, 3, 255, 'Las cubiertas instaladas sobre huecos en superficies de trabajo o de tránsito deben ser capaces de soportar, como mínimo:', 'Covers installed over holes in walking/working surfaces must be capable of supporting, at a minimum:', 'OSHA exige que las cubiertas soporten al menos el doble del peso combinado de empleados, equipo y materiales que puedan apoyarse en ellas, y que queden aseguradas contra desplazamiento accidental.', 'OSHA requires that covers support at least twice the combined weight of employees, equipment, and materials that may be supported on them, and that they be secured against accidental displacement.', 'OSHA 29 CFR 1926.502(i)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (255, 1, 'El peso de un solo empleado', 'The weight of a single employee', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (255, 2, '1,5 veces el peso previsto', '1.5 times the anticipated weight', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (255, 3, 'Al menos el doble del peso de los empleados, el equipo y los materiales que puedan pasar sobre ellas', 'At least twice the weight of the employees, equipment, and materials that may be supported on them', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (255, 4, 'Cuatro veces el peso previsto', 'Four times the anticipated weight', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (256, 3, 256, 'Según OSHA 1926.451(a)(1), cada andamio y cada uno de sus componentes deben ser capaces de soportar su propio peso más, como mínimo:', 'According to OSHA 1926.451(a)(1), each scaffold and each of its components must be capable of supporting its own weight plus, at a minimum:', 'La capacidad exigida para andamios y sus componentes es de al menos 4 veces la carga máxima prevista, incluyendo el peso del propio andamio.', 'The required capacity for scaffolds and their components is at least 4 times the maximum intended load, including the weight of the scaffold itself.', 'OSHA 29 CFR 1926.451(a)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (256, 1, 'Dos veces la carga máxima prevista', 'Twice the maximum intended load', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (256, 2, 'Cuatro veces la carga máxima prevista', 'Four times the maximum intended load', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (256, 3, 'Una vez y media la carga máxima prevista', 'One and a half times the maximum intended load', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (256, 4, 'Diez veces la carga máxima prevista', 'Ten times the maximum intended load', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (257, 3, 257, 'Un andamio apoyado cuya altura supera cuatro veces la dimensión menor de su base debe:', 'A supported scaffold whose height exceeds four times the least dimension of its base must:', 'Cuando la relación altura a base menor pasa de 4 a 1, el andamio debe retenerse contra el vuelco con amarres, vientos o arriostramiento equivalente.', 'When the height-to-base ratio exceeds 4 to 1, the scaffold must be restrained against tipping with ties, guys, bracing, or an equivalent means.', 'OSHA 29 CFR 1926.451(c)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (257, 1, 'Asegurarse contra el vuelco mediante amarres, vientos (guying), riostras u otro medio equivalente', 'Be restrained from tipping by guying, tying, bracing, or other equivalent means', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (257, 2, 'Reducir su carga de trabajo a la mitad', 'Have its working load reduced by half', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (257, 3, 'Usarse únicamente con ruedas bloqueadas', 'Be used only with locked casters', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (257, 4, 'Elevarse solo sobre terreno pavimentado', 'Be erected only on paved ground', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (258, 3, 258, 'En trabajos sobre andamios, la protección contra caídas para cada empleado se exige cuando trabaja a más de:', 'In scaffold work, fall protection for each employee is required when working at more than:', 'Para andamios el umbral es de más de 10 pies sobre el nivel inferior, distinto del umbral general de 6 pies de la Subparte M para otras superficies.', 'For scaffolds, the threshold is more than 10 feet above the lower level, unlike the general 6-foot threshold of Subpart M for other surfaces.', 'OSHA 29 CFR 1926.451(g)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (258, 1, '6 pies sobre el nivel inferior', '6 feet above a lower level', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (258, 2, '8 pies sobre el nivel inferior', '8 feet above a lower level', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (258, 3, '15 pies sobre el nivel inferior', '15 feet above a lower level', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (258, 4, '10 pies sobre el nivel inferior', '10 feet above a lower level', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (259, 3, 259, 'En una zanja de 4 pies o más de profundidad, el medio de salida (escalera, rampa o escalera de mano) debe ubicarse de modo que ningún empleado tenga que recorrer lateralmente más de:', 'In a trench 4 feet or more in depth, the means of egress (ladder, stairway, or ramp) must be located so that no employee is required to travel laterally more than:', 'En zanjas de 4 pies o más de profundidad, la salida debe estar a no más de 25 pies de recorrido lateral de cualquier trabajador dentro de la excavación.', 'In trenches 4 feet or more in depth, egress must be located within no more than 25 feet of lateral travel from any worker inside the excavation.', 'OSHA 29 CFR 1926.651(c)(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (259, 1, '15 pies', '15 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (259, 2, '25 pies', '25 feet', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (259, 3, '50 pies', '50 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (259, 4, '35 pies', '35 feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (260, 3, 260, 'El material excavado (espolón) y el equipo deben mantenerse alejados del borde de la excavación, o contenidos con dispositivos de retención, a una distancia mínima de:', 'Excavated material (spoil) and equipment must be kept back from the edge of the excavation, or restrained by retaining devices, at a minimum distance of:', 'La distancia mínima es de 2 pies desde el borde, para evitar que el material o el equipo rueden o caigan dentro de la excavación sobre los trabajadores.', 'The minimum distance is 2 feet from the edge, to prevent material or equipment from rolling or falling into the excavation onto the workers.', 'OSHA 29 CFR 1926.651(j)(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (260, 1, '6 pulgadas', '6 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (260, 2, '1 pie', '1 foot', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (260, 3, 'Al ras del borde, si el suelo es firme', 'Flush with the edge, if the soil is firm', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (260, 4, '2 pies', '2 feet', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (261, 3, 261, '¿Cuándo debe la persona competente inspeccionar la excavación, las áreas adyacentes y los sistemas de protección?', 'When must the competent person inspect the excavation, the adjacent areas, and the protective systems?', 'La inspección es diaria y previa al inicio del trabajo, y debe repetirse tras cualquier evento que aumente el riesgo, como una tormenta de lluvia.', 'The inspection is daily and prior to the start of work, and must be repeated after any event that increases the hazard, such as a rainstorm.', 'OSHA 29 CFR 1926.651(k)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (261, 1, 'Una vez por semana', 'Once a week', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (261, 2, 'Solo al inicio del proyecto', 'Only at the start of the project', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (261, 3, 'Diariamente antes de comenzar el trabajo, durante el turno según sea necesario, y después de cada tormenta de lluvia u otro evento que aumente el peligro', 'Daily before the start of work, during the shift as needed, and after every rainstorm or other hazard-increasing occurrence', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (261, 4, 'Únicamente cuando un empleado reporte una condición insegura', 'Only when an employee reports an unsafe condition', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (262, 3, 262, 'En una excavación, una atmósfera se considera deficiente en oxígeno cuando el nivel de oxígeno es:', 'In an excavation, an atmosphere is considered oxygen-deficient when the oxygen level is:', 'Por debajo del 19,5% de oxígeno la atmósfera es deficiente y OSHA exige ventilación adecuada o protección respiratoria antes de que los empleados trabajen en la excavación.', 'Below 19.5% oxygen the atmosphere is deficient, and OSHA requires adequate ventilation or respiratory protection before employees work in the excavation.', 'OSHA 29 CFR 1926.651(g)(1)(i)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (262, 1, 'Menor del 19,5%', 'Less than 19.5%', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (262, 2, 'Menor del 16%', 'Less than 16%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (262, 3, 'Menor del 20,9%', 'Less than 20.9%', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (262, 4, 'Menor del 23,5%', 'Less than 23.5%', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (263, 3, 263, 'Según la Tabla B-1 del Apéndice B de la Subparte P, ¿cuál es el talud máximo permitido para una excavación en suelo Tipo C de menos de 20 pies de profundidad?', 'According to Table B-1 of Appendix B to Subpart P, what is the maximum allowable slope for an excavation in Type C soil less than 20 feet deep?', 'El suelo Tipo C, el menos estable, exige el talud más tendido: 1½ horizontal por 1 vertical (34°). El Tipo A permite ¾:1 (53°) y el Tipo B, 1:1 (45°).', 'Type C soil, the least stable, requires the flattest slope: 1½ horizontal to 1 vertical (34°). Type A allows ¾:1 (53°) and Type B, 1:1 (45°).', 'OSHA 29 CFR 1926, Subparte P, Apéndice B, Tabla B-1');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (263, 1, '¾:1 (53°)', '¾:1 (53°)', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (263, 2, '1:1 (45°)', '1:1 (45°)', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (263, 3, 'Vertical (90°)', 'Vertical (90°)', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (263, 4, '1½:1 (34°)', '1½:1 (34°)', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (264, 3, 264, 'Según el Apéndice B de la Subparte P, las configuraciones de talud con banqueo (benching) están contempladas únicamente para suelos:', 'According to Appendix B to Subpart P, benching slope configurations are provided only for soils:', 'El Apéndice B solo muestra configuraciones con banqueo para suelos Tipo A y Tipo B; para el Tipo C solo se permite el talud simple de 1½:1 o un sistema de soporte o apuntalamiento.', 'Appendix B shows benching configurations only for Type A and Type B soils; for Type C, only the simple 1½:1 slope or a support or shoring system is permitted.', 'OSHA 29 CFR 1926, Subparte P, Apéndice B');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (264, 1, 'Tipo C', 'Type C', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (264, 2, 'Tipo A solamente', 'Type A only', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (264, 3, 'Tipos A y B', 'Types A and B', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (264, 4, 'Tipos B y C', 'Types B and C', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (265, 3, 265, 'Una excavación tendrá 22 pies de profundidad y no seguirá las configuraciones de las tablas del Apéndice B. Su sistema de taludes debe ser:', 'An excavation will be 22 feet deep and will not follow the configurations of the Appendix B tables. Its sloping system must be:', 'Las tablas del Apéndice B cubren excavaciones de hasta 20 pies de profundidad; por encima de esa profundidad, el sistema de taludes o banqueo lo diseña un ingeniero profesional registrado.', 'The Appendix B tables cover excavations up to 20 feet in depth; above that depth, the sloping or benching system is designed by a registered professional engineer.', 'OSHA 29 CFR 1926.652 y Subparte P, Apéndice B');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (265, 1, 'Aprobado por el superintendente de obra', 'Approved by the job superintendent', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (265, 2, 'Diseñado o aprobado por un ingeniero profesional registrado', 'Designed or approved by a registered professional engineer', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (265, 3, 'Decidido en campo por la persona competente', 'Decided in the field by the competent person', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (265, 4, 'Igual al requerido para suelo Tipo A', 'The same as required for Type A soil', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (266, 3, 266, 'En el montaje de estructuras de acero (Subparte R), la protección contra caídas para los empleados en general (que no son conectores ni trabajan en decking dentro de una CDZ) se exige a alturas mayores de:', 'In structural steel erection (Subpart R), fall protection for employees in general (who are not connectors and do not work on decking within a CDZ) is required at heights greater than:', 'La Subparte R fija su propio umbral: en montaje de acero la protección contra caídas se requiere a más de 15 pies sobre el nivel inferior, no a los 6 pies de la regla general.', 'Subpart R sets its own threshold: in steel erection, fall protection is required at more than 15 feet above the lower level, not at the 6 feet of the general rule.', 'OSHA 29 CFR 1926.760(a)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (266, 1, '15 pies', '15 feet', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (266, 2, '6 pies', '6 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (266, 3, '10 pies', '10 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (266, 4, '25 pies', '25 feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (267, 3, 267, 'En el montaje de acero, los conectores deben contar con un sistema personal completo de detención de caídas cuando trabajan a más de:', 'In steel erection, connectors must be provided with a complete personal fall arrest system when working at more than:', 'Entre 15 y 30 pies el conector puede trabajar con equipo de detención o posicionamiento y red o sistema disponible; por encima de dos pisos o 30 pies, lo que sea menor, el sistema personal de detención completo es obligatorio.', 'Between 15 and 30 feet the connector may work with fall arrest or positioning equipment and a net or system available; above two stories or 30 feet, whichever is less, the complete personal fall arrest system is mandatory.', 'OSHA 29 CFR 1926.760(b)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (267, 1, 'Un piso o 15 pies, lo que sea menor', 'One story or 15 feet, whichever is less', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (267, 2, 'Tres pisos o 45 pies, lo que sea menor', 'Three stories or 45 feet, whichever is less', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (267, 3, 'Dos pisos o 30 pies, lo que sea menor', 'Two stories or 30 feet, whichever is less', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (267, 4, 'Cuatro pisos o 50 pies, lo que sea menor', 'Four stories or 50 feet, whichever is less', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (268, 3, 268, 'Dentro de una zona de decking controlado (CDZ), ¿cuál es el área máxima de decking metálico que puede permanecer sin fijar ni asegurar en cualquier momento?', 'Within a controlled decking zone (CDZ), what is the maximum area of metal decking that may remain unfastened or unsecured at any time?', 'El decking sin asegurar no puede exceder 3.000 pies cuadrados dentro de la CDZ, que a su vez no puede medir más de 90 pies de ancho ni extenderse más de 90 pies desde el borde de ataque.', 'Unsecured decking may not exceed 3,000 square feet within the CDZ, which in turn may not be more than 90 feet wide nor extend more than 90 feet from the leading edge.', 'OSHA 29 CFR 1926.760(c)(5)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (268, 1, '1.000 pies cuadrados', '1,000 square feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (268, 2, '3.000 pies cuadrados', '3,000 square feet', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (268, 3, '2.000 pies cuadrados', '2,000 square feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (268, 4, '5.000 pies cuadrados', '5,000 square feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (269, 3, 269, 'Según OSHA 1926.404(b)(1), la protección con interruptor de falla a tierra (GFCI), o un programa asegurado de conductor de puesta a tierra, es obligatoria en obra para:', 'According to OSHA 1926.404(b)(1), ground-fault circuit interrupter (GFCI) protection, or an assured equipment grounding conductor program, is mandatory on construction sites for:', 'La exigencia cubre los receptáculos temporales de 120 voltios, monofásicos, de 15 y 20 amperios usados por los empleados en la obra; el empleador puede optar por GFCI o por el programa asegurado de puesta a tierra.', 'The requirement covers the temporary 120-volt, single-phase, 15- and 20-ampere receptacles used by employees on the job; the employer may choose GFCI or the assured grounding program.', 'OSHA 29 CFR 1926.404(b)(1)(ii)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (269, 1, 'Todos los receptáculos de 240 voltios', 'All 240-volt receptacles', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (269, 2, 'Solo los receptáculos del tablero principal', 'Only the receptacles at the main panel', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (269, 3, 'Los receptáculos que forman parte del cableado permanente del edificio', 'Receptacles that are part of the building''s permanent wiring', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (269, 4, 'Los receptáculos de 120 voltios, monofásicos, de 15 y 20 amperios que no forman parte del cableado permanente del edificio y que están en uso por los empleados', '120-volt, single-phase, 15- and 20-ampere receptacles that are not part of the building''s permanent wiring and are in use by employees', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (270, 3, 270, 'En el programa asegurado de conductor de puesta a tierra (AEGCP), las pruebas de continuidad y de conexión correcta de los cordones y receptáculos deben repetirse a intervalos que no excedan:', 'In the assured equipment grounding conductor program (AEGCP), tests for continuity and for proper attachment of cords and receptacles must be repeated at intervals not exceeding:', 'El intervalo general de prueba es de 3 meses; solo los cordones y receptáculos fijos que no están expuestos a daño pueden probarse a intervalos de hasta 6 meses.', 'The general test interval is 3 months; only fixed cords and receptacles that are not exposed to damage may be tested at intervals of up to 6 months.', 'OSHA 29 CFR 1926.404(b)(1)(iii)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (270, 1, '3 meses', '3 months', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (270, 2, '1 mes', '1 month', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (270, 3, '6 meses para todo el equipo', '6 months for all equipment', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (270, 4, '12 meses', '12 months', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (271, 3, 271, 'Según la Tabla D-2 de OSHA 1926.52, ¿cuál es el nivel máximo de ruido permitido para una exposición de 8 horas diarias?', 'According to Table D-2 of OSHA 1926.52, what is the maximum permissible noise level for an exposure of 8 hours per day?', 'A 90 dBA se permiten 8 horas; a 95 dBA el máximo baja a 4 horas y a 100 dBA a 2 horas. El ruido de impulso o impacto, además, nunca debe superar 140 dB de presión sonora pico.', 'At 90 dBA, 8 hours are permitted; at 95 dBA the maximum drops to 4 hours, and at 100 dBA to 2 hours. Impulse or impact noise, in addition, must never exceed 140 dB peak sound pressure level.', 'OSHA 29 CFR 1926.52, Tabla D-2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (271, 1, '85 dBA', '85 dBA', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (271, 2, '95 dBA', '95 dBA', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (271, 3, '90 dBA', '90 dBA', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (271, 4, '100 dBA', '100 dBA', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (272, 3, 272, 'Según la Tabla A de OSHA 1926.1408, ¿cuál es la distancia mínima de seguridad entre una grúa (o cualquier parte de ella o de su carga) y una línea eléctrica energizada de hasta 50 kV?', 'According to Table A of OSHA 1926.1408, what is the minimum clearance distance between a crane (or any part of it or of its load) and an energized power line of up to 50 kV?', 'Para líneas de hasta 50 kV la distancia mínima es de 10 pies; sube a 15 pies para más de 50 y hasta 200 kV, y a 20 pies para más de 200 y hasta 350 kV.', 'For lines up to 50 kV the minimum distance is 10 feet; it rises to 15 feet for more than 50 up to 200 kV, and to 20 feet for more than 200 up to 350 kV.', 'OSHA 29 CFR 1926.1408, Tabla A');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (272, 1, '15 pies', '15 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (272, 2, '10 pies', '10 feet', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (272, 3, '20 pies', '20 feet', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (272, 4, '25 pies', '25 feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (273, 3, 273, 'Al trabajar con grúas cerca de líneas eléctricas aéreas, OSHA exige tratar toda línea como:', 'When working with cranes near overhead power lines, OSHA requires treating every line as:', 'Toda línea se presume energizada salvo confirmación del dueño o la empresa de servicio eléctrico y puesta a tierra visible; sobre esa base se planifica la distancia de seguridad de la Tabla A.', 'Every line is presumed energized unless confirmed by the owner or the electric utility and visibly grounded; the Table A clearance distance is planned on that basis.', 'OSHA 29 CFR 1926.1408');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (273, 1, 'Desenergizada si no se observan chispas', 'De-energized if no sparks are observed', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (273, 2, 'Desenergizada fuera del horario de mayor consumo', 'De-energized outside peak consumption hours', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (273, 3, 'Energizada solo cuando supera los 50 kV', 'Energized only when it exceeds 50 kV', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (273, 4, 'Energizada, hasta que el propietario u operador de la línea confirme que está desenergizada y con puesta a tierra visible', 'Energized, until the owner or operator of the line confirms that it is de-energized and visibly grounded', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (274, 3, 274, 'Antes de la entrada a un espacio confinado que requiere permiso, la medición atmosférica debe realizarse en este orden:', 'Before entry into a permit-required confined space, atmospheric testing must be performed in this order:', 'El orden es oxígeno, combustibles y tóxicos: el oxígeno se mide primero porque los sensores de gases combustibles necesitan niveles adecuados de oxígeno para dar lecturas confiables.', 'The order is oxygen, combustibles, and toxics: oxygen is measured first because combustible-gas sensors require adequate oxygen levels to give reliable readings.', 'OSHA 29 CFR 1926.1204, Subparte AA (espacios confinados en construcción)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (274, 1, 'Oxígeno primero, luego gases y vapores combustibles, y por último gases y vapores tóxicos', 'Oxygen first, then combustible gases and vapors, and last toxic gases and vapors', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (274, 2, 'Gases tóxicos primero, luego oxígeno y luego combustibles', 'Toxic gases first, then oxygen, then combustibles', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (274, 3, 'Gases combustibles primero, luego oxígeno y luego tóxicos', 'Combustible gases first, then oxygen, then toxics', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (274, 4, 'Oxígeno primero, luego tóxicos y luego combustibles', 'Oxygen first, then toxics, then combustibles', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (275, 3, 275, 'Durante la entrada a un espacio confinado con permiso, el personal mínimo que debe permanecer fuera del espacio es:', 'During entry into a permit-required confined space, the minimum personnel who must remain outside the space is:', 'Debe haber al menos un asistente fuera del espacio durante toda la operación de entrada, encargado de monitorear a los entrantes y de activar el procedimiento de rescate sin entrar él mismo.', 'There must be at least one attendant outside the space during the entire entry operation, responsible for monitoring the entrants and initiating the rescue procedure without entering himself.', 'OSHA 29 CFR 1926.1204 y 1926.1209, Subparte AA');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (275, 1, 'El supervisor de entrada, dentro del espacio', 'The entry supervisor, inside the space', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (275, 2, 'Nadie, si el espacio está ventilado', 'No one, if the space is ventilated', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (275, 3, 'Al menos un asistente (attendant) fuera del espacio, en comunicación con los entrantes', 'At least one attendant outside the space, in communication with the entrants', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (275, 4, 'Dos rescatistas dentro del espacio', 'Two rescuers inside the space', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (276, 3, 276, 'Según OSHA 1926.1053, los peldaños o travesaños de las escaleras portátiles y fijas deben estar espaciados, entre líneas centrales, no menos de 10 pulgadas ni más de:', 'According to OSHA 1926.1053, the rungs or cleats of portable and fixed ladders must be spaced, between center lines, not less than 10 inches nor more than:', 'El espaciamiento uniforme entre peldaños debe estar entre 10 y 14 pulgadas medido entre líneas centrales, tanto en escaleras portátiles como fijas.', 'The uniform spacing between rungs must be between 10 and 14 inches measured between center lines, in both portable and fixed ladders.', 'OSHA 29 CFR 1926.1053(a)(3)(i)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (276, 1, '12 pulgadas', '12 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (276, 2, '14 pulgadas', '14 inches', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (276, 3, '16 pulgadas', '16 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (276, 4, '18 pulgadas', '18 inches', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (277, 3, 277, 'Según la definición de OSHA 29 CFR 1926.32(f), una persona competente es quien:', 'According to the definition in OSHA 29 CFR 1926.32(f), a competent person is one who:', 'La definición combina dos elementos: capacidad de reconocer peligros existentes y predecibles, y autoridad real para corregirlos de inmediato. Sin esa autorización, la persona no califica como competente aunque tenga el conocimiento.', 'The definition combines two elements: the capability to recognize existing and predictable hazards, and real authority to correct them immediately. Without that authorization, the person does not qualify as competent even if he has the knowledge.', 'OSHA 29 CFR 1926.32(f)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (277, 1, 'Posee una certificación estatal de seguridad ocupacional', 'Holds a state occupational safety certification', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (277, 2, 'Es un ingeniero profesional registrado', 'Is a registered professional engineer', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (277, 3, 'Lleva más de diez años trabajando en la empresa', 'Has worked for the company for more than ten years', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (277, 4, 'Es capaz de identificar peligros existentes y predecibles en el entorno o en las condiciones de trabajo, y tiene autorización para tomar medidas correctivas prontas para eliminarlos', 'Is capable of identifying existing and predictable hazards in the surroundings or in the working conditions, and has authorization to take prompt corrective measures to eliminate them', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (278, 3, 278, 'Al levantar un muro de mampostería, la zona de acceso limitado que debe establecerse junto al muro es igual a:', 'When erecting a masonry wall, the limited access zone that must be established adjacent to the wall is equal to:', 'La zona de acceso limitado equivale a la altura del muro más 4 pies, corre a todo lo largo del muro y se ubica del lado sin andamio, donde solo puede entrar el personal que construye el muro.', 'The limited access zone equals the height of the wall plus 4 feet, runs the entire length of the wall, and is located on the unscaffolded side, where only the personnel constructing the wall may enter.', 'OSHA 29 CFR 1926.706(a)(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (278, 1, 'La altura del muro más 4 pies, a todo lo largo del muro y por el lado donde no está el andamio', 'The height of the wall plus 4 feet, along the entire length of the wall and on the side where there is no scaffold', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (278, 2, 'La mitad de la altura del muro', 'Half the height of the wall', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (278, 3, '10 pies fijos medidos desde el muro', 'A fixed 10 feet measured from the wall', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (278, 4, 'La altura del muro más 10 pies', 'The height of the wall plus 10 feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (279, 3, 279, 'Los muros de mampostería deben estar adecuadamente arriostrados para evitar que se vuelquen o desplomen cuando superan:', 'Masonry walls must be adequately braced to prevent them from overturning or collapsing when they exceed:', 'Todo muro de mampostería de más de 8 pies de altura debe arriostrarse y mantenerse así hasta que los elementos permanentes de apoyo de la estructura estén en su lugar.', 'Every masonry wall more than 8 feet high must be braced and remain braced until the permanent supporting elements of the structure are in place.', 'OSHA 29 CFR 1926.706(b)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (279, 1, '6 pies de altura', '6 feet in height', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (279, 2, '12 pies de altura', '12 feet in height', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (279, 3, '8 pies de altura', '8 feet in height', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (279, 4, '10 pies de altura', '10 feet in height', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (280, 3, 280, 'Los insertos de izaje que se embeben o se fijan en los paneles prefabricados tipo tilt-up deben ser capaces de soportar, como mínimo:', 'Lifting inserts that are cast into or attached to precast tilt-up panels must be capable of supporting, at a minimum:', 'Para paneles tilt-up el factor es de 2 veces la carga máxima prevista; para los demás elementos prefabricados sube a 4 veces, y el herraje de izaje debe soportar 5 veces la carga.', 'For tilt-up panels the factor is 2 times the maximum intended load; for the other precast elements it rises to 4 times, and lifting hardware must support 5 times the load.', 'OSHA 29 CFR 1926.704(b)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (280, 1, 'Cuatro veces la carga máxima prevista', 'Four times the maximum intended load', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (280, 2, 'Dos veces la carga máxima prevista', 'Two times the maximum intended load', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (280, 3, 'Cinco veces la carga máxima prevista', 'Five times the maximum intended load', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (280, 4, 'Tres veces la carga máxima prevista', 'Three times the maximum intended load', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (281, 3, 281, 'El herraje de izaje (lifting hardware) empleado para levantar elementos prefabricados de concreto debe ser capaz de soportar:', 'The lifting hardware used to lift precast concrete elements must be capable of supporting:', 'El herraje de izaje es el componente con el factor más alto de la Subparte Q: 5 veces la carga máxima prevista, por encima de los insertos embebidos.', 'Lifting hardware is the component with the highest factor in Subpart Q: 5 times the maximum intended load, above the embedded inserts.', 'OSHA 29 CFR 1926.704(d)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (281, 1, 'Dos veces la carga máxima prevista', 'Two times the maximum intended load', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (281, 2, 'Tres veces la carga máxima prevista', 'Three times the maximum intended load', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (281, 3, 'Cuatro veces la carga máxima prevista', 'Four times the maximum intended load', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (281, 4, 'Cinco veces la carga máxima prevista', 'Five times the maximum intended load', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (282, 3, 282, 'Según la práctica recomendada del ACI para el curado del concreto, el período de curado debe mantenerse hasta que el concreto alcance, como mínimo:', 'According to ACI recommended practice for curing concrete, the curing period must be maintained until the concrete reaches, at a minimum:', 'El ACI 308 fija el criterio de duración del curado en alcanzar al menos el 70% de f''c; como referencia, con cemento Portland Tipo I eso equivale aproximadamente a 7 días de curado, y con Tipo III, de alta resistencia temprana, a unos 3 días.', 'ACI 308 sets the curing-duration criterion at reaching at least 70% of f''c; as a reference, with Type I Portland cement that is roughly equivalent to 7 days of curing, and with Type III, high-early-strength cement, to about 3 days.', 'ACI 308, Guide to External Curing of Concrete; ACI 301');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (282, 1, 'El 70% de la resistencia a compresión especificada (f''c)', '70% of the specified compressive strength (f''c)', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (282, 2, 'El 50% de la resistencia especificada', '50% of the specified strength', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (282, 3, 'El 90% de la resistencia especificada', '90% of the specified strength', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (282, 4, 'El 100% de la resistencia especificada', '100% of the specified strength', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (283, 3, 283, 'En los ensayos de resistencia del concreto estructural, una «prueba de resistencia» según el ACI 318 es:', 'In strength testing of structural concrete, a «strength test» according to ACI 318 is:', 'Cada prueba de resistencia es el promedio de dos cilindros compañeros de la misma muestra ensayados a 28 días. La aceptación exige además que el promedio de tres pruebas consecutivas alcance f''c y que ninguna prueba caiga más de 500 psi por debajo de f''c.', 'Each strength test is the average of two companion cylinders from the same sample tested at 28 days. Acceptance also requires that the average of three consecutive tests reach f''c and that no test fall more than 500 psi below f''c.', 'ACI 318, Sección 26.12 (evaluación y aceptación del concreto)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (283, 1, 'El resultado del cilindro con menor resistencia', 'The result of the cylinder with the lowest strength', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (283, 2, 'El promedio de tres cilindros de muestras distintas', 'The average of three cylinders from different samples', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (283, 3, 'El promedio de dos cilindros elaborados de la misma muestra y ensayados a los 28 días', 'The average of two cylinders made from the same sample and tested at 28 days', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (283, 4, 'El promedio de cuatro cilindros ensayados a los 7 días', 'The average of four cylinders tested at 7 days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (284, 3, 284, 'Para un concreto con resistencia especificada f''c de 4.000 psi, ¿por debajo de qué valor una prueba de resistencia deja de ser aceptable según el ACI 318?', 'For a concrete with a specified strength f''c of 4,000 psi, below what value does a strength test become unacceptable under ACI 318?', 'Cuando f''c es de 5.000 psi o menor, ninguna prueba puede caer más de 500 psi por debajo de f''c: 4.000 − 500 = 3.500 psi. Para resistencias mayores, el límite es el 10% por debajo de f''c.', 'When f''c is 5,000 psi or less, no test may fall more than 500 psi below f''c: 4,000 − 500 = 3,500 psi. For higher strengths, the limit is 10% below f''c.', 'ACI 318, Sección 26.12 (criterios de aceptación)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (284, 1, '3.750 psi', '3,750 psi', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (284, 2, '3.500 psi', '3,500 psi', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (284, 3, '4.000 psi', '4,000 psi', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (284, 4, '3.000 psi', '3,000 psi', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (285, 3, 285, '¿Cuál es el recubrimiento mínimo de concreto sobre el acero de refuerzo para elementos vaciados contra el terreno y en contacto permanente con él?', 'What is the minimum concrete cover over reinforcing steel for members cast against the ground and permanently in contact with it?', 'Es el recubrimiento mayor de la tabla del ACI 318: 3 pulgadas cuando el concreto se vacía directamente contra la tierra y queda expuesto a ella de forma permanente.', 'It is the greatest cover in the ACI 318 table: 3 inches when concrete is cast directly against the ground and permanently exposed to it.', 'ACI 318, Tabla 20.6.1.3.1 (recubrimientos especificados)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (285, 1, '¾ de pulgada', '¾ inch', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (285, 2, '1½ pulgadas', '1½ inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (285, 3, '2 pulgadas', '2 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (285, 4, '3 pulgadas', '3 inches', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (286, 3, 286, 'Según la especificación por propiedades de ASTM C270, la resistencia mínima a compresión a los 28 días del mortero Tipo M es de:', 'According to the property specification of ASTM C270, the minimum compressive strength at 28 days of Type M mortar is:', 'El Tipo M es el mortero de mayor resistencia de la especificación: 2.500 psi. Le siguen el Tipo S con 1.800 psi, el Tipo N con 750 psi y el Tipo O con 350 psi.', 'Type M is the highest-strength mortar in the specification: 2,500 psi. It is followed by Type S with 1,800 psi, Type N with 750 psi, and Type O with 350 psi.', 'ASTM C270, Standard Specification for Mortar for Unit Masonry');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (286, 1, '2.500 psi', '2,500 psi', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (286, 2, '1.800 psi', '1,800 psi', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (286, 3, '750 psi', '750 psi', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (286, 4, '350 psi', '350 psi', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (287, 3, 287, '¿Qué resistencia mínima a compresión a los 28 días corresponde al mortero Tipo N, el de uso general en mampostería sobre el nivel del terreno?', 'What minimum compressive strength at 28 days corresponds to Type N mortar, the general-purpose mortar for above-grade masonry?', 'El Tipo N alcanza 750 psi: es el mortero de propósito general para muros de mampostería no sometidos a cargas altas ni a contacto severo con el suelo, a diferencia del Tipo M (2.500 psi).', 'Type N reaches 750 psi: it is the general-purpose mortar for masonry walls not subjected to high loads or severe contact with the ground, unlike Type M (2,500 psi).', 'ASTM C270, Standard Specification for Mortar for Unit Masonry');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (287, 1, '350 psi', '350 psi', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (287, 2, '1.800 psi', '1,800 psi', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (287, 3, '750 psi', '750 psi', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (287, 4, '2.500 psi', '2,500 psi', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (288, 3, 288, 'Un montante de madera vendido como «2×4» tiene, una vez seco y cepillado, una sección real de:', 'A wood stud sold as a «2×4» has, once dried and surfaced, an actual cross-section of:', 'El «2×4» es la dimensión nominal; tras el secado y el cepillado la pieza mide 1,5 × 3,5 pulgadas, y con esa medida real se calcula el entramado.', 'The «2×4» is the nominal dimension; after drying and surfacing the piece measures 1.5 × 3.5 inches, and framing is calculated with that actual size.', 'American Softwood Lumber Standard PS 20 (dimensiones nominales y reales de la madera aserrada)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (288, 1, '2 × 4 pulgadas exactas', 'Exactly 2 × 4 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (288, 2, '1,5 × 3,5 pulgadas', '1.5 × 3.5 inches', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (288, 3, '1¾ × 3¾ pulgadas', '1¾ × 3¾ inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (288, 4, '1,25 × 3,25 pulgadas', '1.25 × 3.25 inches', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (289, 3, 289, '¿Cuál es la sección real de una vigueta de madera de dimensión nominal 2×10, seca y cepillada?', 'What is the actual cross-section of a wood joist of nominal dimension 2×10, dried and surfaced?', 'En piezas de 8 pulgadas nominales o más, el ancho real se reduce ¾ de pulgada en vez de ½, por lo que el 2×10 mide 1,5 × 9,25 pulgadas.', 'In pieces of 8 nominal inches or more, the actual width is reduced by ¾ inch instead of ½ inch, so the 2×10 measures 1.5 × 9.25 inches.', 'American Softwood Lumber Standard PS 20');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (289, 1, '1,5 × 9,5 pulgadas', '1.5 × 9.5 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (289, 2, '1,5 × 10 pulgadas', '1.5 × 10 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (289, 3, '2 × 9,25 pulgadas', '2 × 9.25 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (289, 4, '1,5 × 9,25 pulgadas', '1.5 × 9.25 inches', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (290, 3, 290, 'En el sistema de especificaciones CSI MasterFormat, el concreto (incluidos encofrados, refuerzo y concreto vaciado en sitio) se especifica en:', 'In the CSI MasterFormat specification system, concrete (including formwork, reinforcement, and cast-in-place concrete) is specified in:', 'La División 03 es Concreto; la 04 es Mampostería, la 05 Metales y la 06 Madera, Plásticos y Compuestos. La División 01, en cambio, recoge los Requisitos Generales aplicables a todo el proyecto.', 'Division 03 is Concrete; 04 is Masonry, 05 is Metals, and 06 is Wood, Plastics, and Composites. Division 01, by contrast, contains the General Requirements applicable to the entire project.', 'CSI MasterFormat, Divisiones 01 a 07');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (290, 1, 'División 03, Concreto', 'Division 03, Concrete', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (290, 2, 'División 04, Mampostería', 'Division 04, Masonry', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (290, 3, 'División 05, Metales', 'Division 05, Metals', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (290, 4, 'División 06, Madera, Plásticos y Compuestos', 'Division 06, Wood, Plastics, and Composites', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (291, 3, 291, 'Las especificaciones de techos, impermeabilización y aislamiento térmico del edificio se encuentran en la División:', 'The specifications for roofing, waterproofing, and thermal insulation of the building are found in Division:', 'La División 07, Thermal and Moisture Protection, agrupa techos, impermeabilización, aislamiento térmico, barreras de aire y selladores de juntas.', 'Division 07, Thermal and Moisture Protection, groups roofing, waterproofing, thermal insulation, air barriers, and joint sealants.', 'CSI MasterFormat, División 07');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (291, 1, 'División 09, Acabados', 'Division 09, Finishes', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (291, 2, 'División 08, Aberturas', 'Division 08, Openings', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (291, 3, 'División 07, Protección Térmica y contra Humedad', 'Division 07, Thermal and Moisture Protection', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (291, 4, 'División 12, Mobiliario', 'Division 12, Furnishings', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (292, 3, 292, 'El movimiento de tierras del sitio (excavación, relleno, compactación y nivelación) se especifica en la División:', 'Site earthwork (excavation, fill, compaction, and grading) is specified in Division:', 'La División 31 es Earthwork. La 32 cubre las mejoras exteriores como pavimentos y paisajismo, y la 33 las utilidades del sitio: agua, drenaje sanitario y pluvial y distribución eléctrica.', 'Division 31 is Earthwork. Division 32 covers exterior improvements such as paving and landscaping, and 33 covers site utilities: water, sanitary and storm drainage, and electrical distribution.', 'CSI MasterFormat, Divisiones 31 a 33');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (292, 1, 'División 02, Condiciones Existentes', 'Division 02, Existing Conditions', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (292, 2, 'División 31, Movimiento de Tierras (Earthwork)', 'Division 31, Earthwork', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (292, 3, 'División 33, Utilidades', 'Division 33, Utilities', 0);
