INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (293, 3, 293, 'En un cronograma CPM, una actividad tiene inicio temprano (ES) el día 4 e inicio tardío (LS) el día 11. Su holgura total es de:', 'In a CPM schedule, an activity has an early start (ES) on day 4 and a late start (LS) on day 11. Its total float is:', 'Holgura total = LS − ES = 11 − 4 = 7 días. Es el tiempo que la actividad puede atrasarse sin mover la fecha de terminación del proyecto; también puede calcularse como LF − EF.', 'Total float = LS − ES = 11 − 4 = 7 days. It is the time the activity can be delayed without moving the project completion date; it can also be calculated as LF − EF.', 'Método de la ruta crítica (CPM), cálculo de holguras: práctica estándar de programación de obra');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (293, 1, '15 días', '15 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (293, 2, '4 días', '4 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (293, 3, '11 días', '11 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (293, 4, '7 días', '7 days', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (294, 3, 294, 'Una actividad termina en su fecha temprana (EF) el día 10 y su sucesora más temprana puede comenzar el día 13 (ES). La holgura libre de la actividad es de:', 'An activity finishes at its early finish (EF) on day 10 and its earliest successor can begin on day 13 (ES). The free float of the activity is:', 'Holgura libre = ES de la sucesora − EF de la actividad = 13 − 10 = 3 días. Consumir la holgura libre no atrasa el inicio temprano de ninguna sucesora, a diferencia de la holgura total.', 'Free float = ES of the successor − EF of the activity = 13 − 10 = 3 days. Using up free float does not delay the early start of any successor, unlike total float.', 'Método de la ruta crítica (CPM), cálculo de holguras');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (294, 1, '3 días', '3 days', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (294, 2, '0 días', '0 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (294, 3, '13 días', '13 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (294, 4, '23 días', '23 days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (295, 3, 295, 'Según el Código de Accesibilidad de Florida (FBC Accessibility), el ancho libre mínimo de una puerta en una ruta accesible, medido con la puerta abierta a 90 grados, es de:', 'According to the Florida Accessibility Code (FBC Accessibility), the minimum clear width of a door on an accessible route, measured with the door open at 90 degrees, is:', 'El vano libre mínimo es de 32 pulgadas entre la cara de la puerta abierta a 90° y el tope del marco opuesto. Las 36 pulgadas corresponden al ancho mínimo general de la ruta accesible.', 'The minimum clear opening is 32 inches between the face of the door open at 90° and the stop on the opposite jamb. The 36 inches correspond to the general minimum width of the accessible route.', 'FBC Accessibility, Sección 404.2.3 (basado en ADA 2010)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (295, 1, '28 pulgadas', '28 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (295, 2, '30 pulgadas', '30 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (295, 3, '32 pulgadas', '32 inches', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (295, 4, '36 pulgadas', '36 inches', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (296, 3, 296, 'La pendiente longitudinal máxima permitida en una rampa accesible según el FBC Accessibility es de:', 'The maximum longitudinal slope permitted on an accessible ramp under the FBC Accessibility code is:', 'La pendiente de la rampa no puede superar 1:12, su pendiente transversal no puede pasar de 1:50 y los descansos deben tener al menos 60 pulgadas de longitud en el sentido de la marcha.', 'The ramp slope may not exceed 1:12, its cross slope may not exceed 1:50, and landings must be at least 60 inches long in the direction of travel.', 'FBC Accessibility, Sección 405 (rampas)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (296, 1, '1:8', '1:8', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (296, 2, '1:12', '1:12', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (296, 3, '1:16', '1:16', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (296, 4, '1:20', '1:20', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (297, 3, 297, 'En una rampa accesible, la parte superior de los pasamanos debe ubicarse, sobre la superficie de la rampa, entre:', 'On an accessible ramp, the top of the handrails must be located, above the ramp surface, between:', 'Los pasamanos de rampas y escaleras accesibles se instalan con su superficie de agarre entre 34 y 38 pulgadas sobre la superficie, de forma continua a ambos lados.', 'Handrails for accessible ramps and stairs are installed with their gripping surface between 34 and 38 inches above the surface, continuous on both sides.', 'FBC Accessibility, Sección 505.4 (pasamanos)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (297, 1, '28 y 32 pulgadas', '28 and 32 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (297, 2, '30 y 34 pulgadas', '30 and 34 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (297, 3, '36 y 42 pulgadas', '36 and 42 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (297, 4, '34 y 38 pulgadas', '34 and 38 inches', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (298, 3, 298, 'Según el Capítulo 6 del FBC Existing Building, una alteración se clasifica como Nivel 3 cuando:', 'Under Chapter 6 of the FBC Existing Building code, an alteration is classified as Level 3 when:', 'El Nivel 3 se define por superficie, no por costo: el área de trabajo supera el 50% del área del edificio. El Nivel 1 cubre remoción y reemplazo con materiales nuevos del mismo propósito, y el Nivel 2 la reconfiguración de espacios o sistemas.', 'Level 3 is defined by area, not by cost: the work area exceeds 50% of the building area. Level 1 covers removal and replacement with new materials serving the same purpose, and Level 2 covers the reconfiguration of spaces or systems.', 'FBC Existing Building, Capítulo 6, Sección 604');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (298, 1, 'El área de trabajo excede el 50% del área del edificio', 'The work area exceeds 50% of the building area', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (298, 2, 'Se cambia la ocupación del edificio', 'The occupancy of the building is changed', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (298, 3, 'Se agrega un piso completo a la estructura', 'A full story is added to the structure', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (298, 4, 'El costo de la obra supera el 50% del valor del edificio', 'The cost of the work exceeds 50% of the value of the building', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (299, 3, 299, 'En una vivienda nueva en la Zona Climática 2 de Florida (la mayor parte del estado, incluido Jacksonville), el valor R mínimo prescriptivo del aislamiento del techo según el FBC Energy Conservation es:', 'In a new dwelling in Florida Climate Zone 2 (most of the state, including Jacksonville), the minimum prescriptive R-value for ceiling insulation under the FBC Energy Conservation code is:', 'La Tabla R402.1.2 exige techo R-38 en la Zona Climática 2 y R-30 en la Zona 1 (extremo sur del estado); la pared de entramado de madera requiere R-13 en ambas zonas y el SHGC máximo de las ventanas es 0,25.', 'Table R402.1.2 requires ceiling R-38 in Climate Zone 2 and R-30 in Zone 1 (the southern tip of the state); wood-frame walls require R-13 in both zones, and the maximum SHGC for windows is 0.25.', 'FBC Energy Conservation, Tabla R402.1.2');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (299, 1, 'R-19', 'R-19', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (299, 2, 'R-30', 'R-30', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (299, 3, 'R-38', 'R-38', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (299, 4, 'R-49', 'R-49', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (300, 3, 300, 'Según la Sección 1609.1.1 del Florida Building Code (Building), las cargas de viento de todo edificio o estructura deben determinarse de acuerdo con:', 'According to Section 1609.1.1 of the Florida Building Code (Building), the wind loads on every building or structure must be determined in accordance with:', 'El FBC remite el cálculo de cargas de viento a los Capítulos 26 a 30 de ASCE 7, suponiendo el viento proveniente de cualquier dirección horizontal y las presiones actuando normales a la superficie; las figuras 1609.3 dan las velocidades últimas de diseño (Vult) según la categoría de riesgo.', 'The FBC refers wind-load determination to Chapters 26 through 30 of ASCE 7, assuming wind coming from any horizontal direction and pressures acting normal to the surface; Figures 1609.3 give the ultimate design wind speeds (Vult) according to risk category.', 'FBC Building, Sección 1609.1.1 (8ª edición, 2023)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (300, 1, 'El manual del fabricante de los conectores estructurales', 'The structural connector manufacturer''s manual', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (300, 2, 'Los Capítulos 26 a 30 de ASCE 7', 'Chapters 26 through 30 of ASCE 7', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (300, 3, 'La norma ASTM E1996 por sí sola', 'The ASTM E1996 standard by itself', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (300, 4, 'El criterio del inspector municipal de cada jurisdicción', 'The judgment of the municipal inspector of each jurisdiction', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (301, 3, 301, 'En un sistema de barandas, cuando no existe pared ni parapeto de al menos 21 pulgadas de alto, los rieles intermedios (midrails) deben instalarse:', 'In a guardrail system, when there is no wall or parapet at least 21 inches high, midrails must be installed:', 'OSHA exige que los rieles intermedios se instalen a una altura intermedia (midway) entre el borde superior del sistema de barandas y el nivel de trabajo o de tránsito.', 'OSHA requires midrails to be installed at a height midway between the top edge of the guardrail system and the walking/working level.', 'OSHA 29 CFR 1926.502(b)(2)(i)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (301, 1, 'A la mitad de la altura entre el borde superior de la baranda y el nivel de trabajo', 'Midway between the top edge of the guardrail system and the walking/working level', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (301, 2, 'En el tercio inferior, pegados a la superficie de trabajo', 'In the lower third, flush against the working surface', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (301, 3, 'Solo si la baranda supera las 48 pulgadas de altura', 'Only if the guardrail exceeds 48 inches in height', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (301, 4, 'Directamente bajo el riel superior, a no más de 6 pulgadas de él', 'Directly below the top rail, no more than 6 inches from it', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (302, 3, 302, 'Usados como protección contra objetos que caen, los rodapiés (toeboards) deben tener una altura vertical mínima de:', 'Used as protection against falling objects, toeboards must have a minimum vertical height of:', 'El rodapié debe medir como mínimo 3½ pulgadas de altura vertical desde su borde superior hasta el nivel de la superficie de trabajo, con una holgura máxima de ¼ de pulgada sobre esa superficie.', 'The toeboard must be at least 3½ inches in vertical height from its top edge to the level of the walking/working surface, with a clearance of no more than ¼ inch above that surface.', 'OSHA 29 CFR 1926.502(j)(3)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (302, 1, '2 pulgadas', '2 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (302, 2, '3 pulgadas', '3 inches', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (302, 3, '3½ pulgadas', '3½ inches', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (302, 4, '6 pulgadas', '6 inches', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (303, 3, 303, 'Un empleado que está construyendo un borde de avance (leading edge) ubicado a 6 pies o más sobre el nivel inferior debe estar protegido contra caídas mediante:', 'An employee who is constructing a leading edge located 6 feet or more above a lower level must be protected from falling by:', 'La regla de los bordes sin protección se aplica también a quien construye el borde de avance: barandas, redes o sistema personal de detención de caídas; solo si el empleador demuestra que esos sistemas son inviables o crean un peligro mayor puede recurrir a un plan de protección contra caídas.', 'The unprotected-edge rule also applies to the employee building the leading edge: guardrails, safety nets, or a personal fall arrest system; only if the employer demonstrates that those systems are infeasible or create a greater hazard may it resort to a fall protection plan.', 'OSHA 29 CFR 1926.501(b)(2)(i)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (303, 1, 'Únicamente un monitor de seguridad que observe el borde', 'A safety monitor watching the edge only', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (303, 2, 'Un cinturón de posicionamiento conectado al encofrado', 'A positioning belt connected to the formwork', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (303, 3, 'Barandas, redes de seguridad o un sistema personal de detención de caídas', 'Guardrail systems, safety net systems, or a personal fall arrest system', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (303, 4, 'Nada, porque el trabajo en el borde de avance está exento de la Subparte M', 'Nothing, because leading edge work is exempt from Subpart M', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (304, 3, 304, 'Según OSHA 1926.100, los empleados deben usar casco de protección (protective helmet) cuando trabajan en áreas donde existe peligro de lesión en la cabeza por:', 'According to OSHA 1926.100, employees must wear a protective helmet when working in areas where there is a possible danger of head injury from:', 'La norma de protección de la cabeza aplica donde haya posibilidad de lesión por impacto, por objetos que caen o vuelan, o por choque eléctrico y quemaduras; el casco debe cumplir el estándar ANSI Z89.1.', 'The head protection rule applies where there is a possible danger of head injury from impact, from falling or flying objects, or from electrical shock and burns; the helmet must comply with the ANSI Z89.1 standard.', 'OSHA 29 CFR 1926.100(a)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (304, 1, 'Ruido superior a 90 decibeles', 'Noise above 90 decibels', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (304, 2, 'Impacto, objetos que caen o vuelan, o choque eléctrico y quemaduras', 'Impact, falling or flying objects, or electrical shock and burns', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (304, 3, 'Temperaturas extremas únicamente', 'Extreme temperatures only', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (304, 4, 'Contacto con productos químicos líquidos', 'Contact with liquid chemicals', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (305, 3, 305, 'Si en la obra no hay una enfermería, clínica, hospital o médico razonablemente accesible en tiempo y distancia, OSHA 1926.50 exige que en el sitio haya:', 'If there is no infirmary, clinic, hospital, or physician reasonably accessible in time and distance to the jobsite, OSHA 1926.50 requires that at the site there be:', 'En ausencia de atención médica razonablemente accesible, debe estar disponible en la obra una persona con certificado válido en primeros auxilios (Cruz Roja Americana, U.S. Bureau of Mines o capacitación equivalente que pueda verificarse con documentos).', 'Where medical attention is not reasonably accessible, a person with a valid first aid certificate (American Red Cross, U.S. Bureau of Mines, or equivalent training that can be verified with documents) must be available at the jobsite.', 'OSHA 29 CFR 1926.50(c)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (305, 1, 'Un botiquín sellado dentro de la oficina del superintendente', 'A sealed first aid kit inside the superintendent''s office', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (305, 2, 'Un vehículo de la empresa estacionado junto a la entrada', 'A company vehicle parked next to the entrance', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (305, 3, 'El número del hospital pegado en el tablero de avisos', 'The hospital''s phone number posted on the bulletin board', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (305, 4, 'Una persona con certificado válido de capacitación en primeros auxilios disponible para prestar esa ayuda', 'A person with a valid certificate in first aid training available to render that aid', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (306, 3, 306, 'Tras la muerte de un empleado por un incidente relacionado con el trabajo, el empleador debe reportar la fatalidad a OSHA dentro de:', 'After the death of an employee from a work-related incident, the employer must report the fatality to OSHA within:', 'La Parte 1904 exige reportar toda fatalidad laboral a OSHA dentro de las 8 horas siguientes a la muerte del empleado.', 'Part 1904 requires every work-related fatality to be reported to OSHA within 8 hours following the death of the employee.', 'OSHA 29 CFR 1904.39(a)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (306, 1, '8 horas', '8 hours', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (306, 2, '24 horas', '24 hours', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (306, 3, '72 horas', '72 hours', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (306, 4, '10 días calendario', '10 calendar days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (307, 3, 307, 'La hospitalización interna (in-patient) de un empleado, una amputación o la pérdida de un ojo por un incidente laboral deben reportarse a OSHA dentro de:', 'An employee''s in-patient hospitalization, an amputation, or the loss of an eye from a work-related incident must be reported to OSHA within:', 'Esos tres eventos (hospitalización interna, amputación y pérdida de un ojo) se reportan a OSHA dentro de las 24 horas; el plazo de 8 horas es solo para las fatalidades.', 'Those three events (in-patient hospitalization, amputation, and loss of an eye) must be reported to OSHA within 24 hours; the 8-hour deadline applies only to fatalities.', 'OSHA 29 CFR 1904.39(a)(2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (307, 1, '8 horas', '8 hours', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (307, 2, '24 horas', '24 hours', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (307, 3, '5 días laborables', '5 business days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (307, 4, 'Al cierre del registro anual (OSHA 300)', 'At the close of the annual log (OSHA 300)', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (308, 3, 308, 'El resumen anual de lesiones y enfermedades (formulario OSHA 300-A), ya certificado por un ejecutivo de la empresa, debe publicarse en un lugar visible a más tardar el 1 de febrero y permanecer expuesto hasta el:', 'The annual summary of injuries and illnesses (OSHA Form 300-A), once certified by a company executive, must be posted in a conspicuous place no later than February 1 and must remain posted until:', 'El resumen anual se publica a más tardar el 1 de febrero del año siguiente al cubierto por los registros y debe mantenerse expuesto, sin alteraciones, hasta el 30 de abril.', 'The annual summary must be posted no later than February 1 of the year following the year covered by the records and must remain posted, unaltered, until April 30.', 'OSHA 29 CFR 1904.32(b)(6)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (308, 1, '1 de marzo', 'March 1', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (308, 2, '15 de febrero', 'February 15', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (308, 3, '30 de abril', 'April 30', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (308, 4, '31 de diciembre del mismo año', 'December 31 of the same year', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (309, 3, 309, 'El límite de exposición permisible (PEL) de OSHA para la sílice cristalina respirable en la construcción, calculado como promedio ponderado de 8 horas (TWA), es de:', 'OSHA''s permissible exposure limit (PEL) for respirable crystalline silica in construction, calculated as an 8-hour time-weighted average (TWA), is:', 'Ningún empleado puede estar expuesto a más de 50 μg/m³ de sílice cristalina respirable como TWA de 8 horas; los 25 μg/m³ corresponden al nivel de acción (action level) definido en la misma norma.', 'No employee may be exposed to more than 50 μg/m³ of respirable crystalline silica as an 8-hour TWA; 25 μg/m³ is the action level defined in the same standard.', 'OSHA 29 CFR 1926.1153(d)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (309, 1, '25 microgramos por metro cúbico de aire', '25 micrograms per cubic meter of air', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (309, 2, '50 microgramos por metro cúbico de aire', '50 micrograms per cubic meter of air', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (309, 3, '100 microgramos por metro cúbico de aire', '100 micrograms per cubic meter of air', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (309, 4, '250 microgramos por metro cúbico de aire', '250 micrograms per cubic meter of air', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (310, 3, 310, 'Según la norma de sílice en construcción, el empleador debe poner la vigilancia médica (medical surveillance) a disposición, sin costo para el empleado, de cada trabajador que:', 'Under the construction silica standard, the employer must make medical surveillance available, at no cost to the employee, to each employee who:', 'El disparador de la vigilancia médica en construcción es el uso requerido de respirador por 30 días o más al año bajo la norma de sílice; el examen inicial debe ofrecerse dentro de los 30 días siguientes a la asignación inicial.', 'The medical surveillance trigger in construction is being required to use a respirator for 30 or more days per year under the silica standard; the initial examination must be offered within 30 days after the initial assignment.', 'OSHA 29 CFR 1926.1153(h)(1)(i)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (310, 1, 'Trabaje con concreto al menos un día al año', 'Works with concrete at least one day per year', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (310, 2, 'Esté expuesto por encima del nivel de acción un solo día', 'Is exposed above the action level on a single day', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (310, 3, 'Haya presentado una queja por polvo en la obra', 'Has filed a dust complaint on the jobsite', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (310, 4, 'Tenga que usar respirador conforme a esta norma durante 30 días o más al año', 'Will be required to use a respirator under this standard for 30 or more days per year', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (311, 3, 311, 'Respecto a la limpieza (housekeeping) en trabajos con sílice cristalina respirable, OSHA prohíbe:', 'Regarding housekeeping in work involving respirable crystalline silica, OSHA prohibits:', 'La norma prohíbe el barrido y el cepillado en seco donde puedan contribuir a la exposición, a menos que el barrido húmedo, la aspiradora HEPA u otros métodos que minimicen la exposición no sean viables.', 'The standard prohibits dry sweeping and dry brushing where they could contribute to exposure, unless wet sweeping, HEPA-filtered vacuuming, or other methods that minimize exposure are not feasible.', 'OSHA 29 CFR 1926.1153(f)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (311, 1, 'El barrido en seco o el cepillado en seco cuando pueda contribuir a la exposición, salvo que los métodos húmedos o la aspiradora con filtro HEPA no sean viables', 'Dry sweeping or dry brushing when it could contribute to exposure, unless wet methods or a HEPA-filtered vacuum are not feasible', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (311, 2, 'El uso de aspiradoras con filtro HEPA dentro de edificios', 'The use of HEPA-filtered vacuums inside buildings', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (311, 3, 'El barrido húmedo en áreas exteriores', 'Wet sweeping in exterior areas', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (311, 4, 'El uso de aire comprimido para cualquier tarea de la obra', 'The use of compressed air for any task on the jobsite', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (312, 3, 312, 'En la construcción, la protección respiratoria sigue los requisitos de 29 CFR 1910.134 (remitidos por 1926.103). Según esa norma, antes de que un empleado sea sometido a la prueba de ajuste (fit test) o deba usar un respirador en el trabajo, el empleador debe:', 'In construction, respiratory protection follows the requirements of 29 CFR 1910.134 (referenced by 1926.103). Under that standard, before an employee is fit tested or required to use a respirator at work, the employer must:', 'La evaluación médica es previa: debe realizarse antes de la prueba de ajuste y antes de exigir el uso del respirador, y se proporciona sin costo para el empleado.', 'The medical evaluation is prior: it must be performed before the fit test and before requiring respirator use, and it is provided at no cost to the employee.', 'OSHA 29 CFR 1926.103, que remite a 29 CFR 1910.134(e)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (312, 1, 'Proporcionarle una evaluación médica que determine su capacidad para usar un respirador', 'Provide the employee with a medical evaluation to determine the employee''s ability to use a respirator', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (312, 2, 'Entregarle el respirador y capacitarlo en su limpieza', 'Give him the respirator and train him in its cleaning', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (312, 3, 'Hacerle una prueba de función pulmonar en la propia obra', 'Perform a pulmonary function test at the jobsite itself', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (312, 4, 'Obtener una autorización firmada por el empleado', 'Obtain a signed authorization from the employee', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (313, 3, 313, 'Cuando en una obra se trabaja sobre equipos o circuitos desenergizados, OSHA 1926.417 exige que esos equipos o circuitos:', 'When work is performed on de-energized equipment or circuits on a jobsite, OSHA 1926.417 requires that such equipment or circuits:', 'La sección de bloqueo y etiquetado en construcción ordena dejar el equipo o circuito desenergizado fuera de operación y colocar etiquetas en todos los puntos desde donde pueda energizarse; los controles que se desactivan durante el trabajo también se etiquetan.', 'The lockout and tagging section in construction requires de-energized equipment or circuits to be rendered inoperative and tags placed at all points from which they can be energized; controls that are deactivated during the work are also tagged.', 'OSHA 29 CFR 1926.417(b)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (313, 1, 'Se conecten a tierra con un cable temporal visible', 'Be grounded with a visible temporary cable', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (313, 2, 'Permanezcan encendidos pero con el interruptor señalizado', 'Remain energized but with the switch marked', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (313, 3, 'Sean puestos fuera de operación (rendered inoperative) y tengan etiquetas (tags) en todos los puntos donde puedan ser energizados', 'Be rendered inoperative and have tags placed at all points where they can be energized', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (313, 4, 'Sean retirados físicamente del área de trabajo', 'Be physically removed from the work area', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (314, 3, 314, 'Antes de permitir que los empleados comiencen una demolición, OSHA 1926.850 exige:', 'Before allowing employees to begin a demolition, OSHA 1926.850 requires:', 'El estudio de ingeniería previo, a cargo de una persona competente, evalúa el estado de la armadura, los pisos y las paredes y el riesgo de colapso no planificado, incluidas las estructuras adyacentes donde los empleados puedan estar expuestos; el empleador debe tener evidencia escrita de su realización.', 'The pre-demolition engineering survey, performed by a competent person, evaluates the condition of the framing, floors, and walls and the risk of unplanned collapse, including adjacent structures where employees may be exposed; the employer must have written evidence that it was performed.', 'OSHA 29 CFR 1926.850(a)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (314, 1, 'Que el edificio haya estado desocupado por 30 días', 'That the building has been vacant for 30 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (314, 2, 'La aprobación escrita de la compañía de seguros del propietario', 'The written approval of the owner''s insurance company', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (314, 3, 'Un permiso emitido por la oficina local de OSHA', 'A permit issued by the local OSHA office', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (314, 4, 'Un estudio de ingeniería (engineering survey) hecho por una persona competente para determinar el estado de la estructura y la posibilidad de un colapso no planificado, con evidencia escrita de que se realizó', 'An engineering survey performed by a competent person to determine the condition of the structure and the possibility of an unplanned collapse, with written evidence that it was performed', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (315, 3, 315, 'Antes de comenzar el trabajo de demolición, las líneas de servicio de electricidad, gas, agua, vapor, alcantarillado y demás servicios deben:', 'Before demolition work begins, the electric, gas, water, steam, sewer, and other utility service lines must:', 'Todas las líneas de servicio se cierran, tapan o controlan fuera de la línea del edificio antes de iniciar la demolición, y en cada caso se avisa con anticipación a la compañía de servicios públicos correspondiente.', 'All utility service lines must be shut off, capped, or otherwise controlled outside the building line before demolition begins, and in each case the corresponding utility company must be notified in advance.', 'OSHA 29 CFR 1926.850(c)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (315, 1, 'Quedar encendidas hasta terminar el primer piso', 'Stay energized until the first floor is finished', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (315, 2, 'Apagarse, taparse o controlarse de otro modo fuera de la línea del edificio (outside the building line), notificando antes a la empresa de servicios involucrada', 'Be shut off, capped, or otherwise controlled outside the building line, notifying the utility company involved in advance', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (315, 3, 'Marcarse con pintura en el pavimento y nada más', 'Be marked with paint on the pavement and nothing more', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (315, 4, 'Ser cortadas por los propios trabajadores de demolición a medida que avanza el trabajo', 'Be cut by the demolition workers themselves as the work progresses', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (316, 3, 316, 'Todo canalón de materiales (material chute) instalado con un ángulo de más de 45 grados respecto a la horizontal debe:', 'Any material chute installed at an angle of more than 45 degrees from the horizontal must:', 'Los canalones con inclinación mayor de 45 grados deben ir totalmente cerrados; las aberturas de carga no pueden pasar de 48 pulgadas de altura medidas a lo largo de la pared del canalón y deben mantenerse cerradas cuando no se usan.', 'Chutes inclined at more than 45 degrees must be entirely enclosed; loading openings may not exceed 48 inches in height measured along the wall of the chute and must be kept closed when not in use.', 'OSHA 29 CFR 1926.852(b)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (316, 1, 'Estar señalizado con cinta de precaución', 'Be marked with caution tape', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (316, 2, 'Ser enteramente cerrado (entirely enclosed), salvo las aberturas con cierre a nivel de piso para introducir el material', 'Be entirely enclosed, except for openings with closures at floor level for introducing material', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (316, 3, 'Tener una red de seguridad instalada debajo', 'Have a safety net installed underneath', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (316, 4, 'Operarse solo durante horas de luz natural', 'Be operated only during daylight hours', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (317, 3, 317, 'Cuando una plataforma de andamio queda a más de 2 pies por encima o por debajo de un punto de acceso, OSHA exige proporcionar:', 'When a scaffold platform is more than 2 feet above or below a point of access, OSHA requires providing:', 'Con desniveles mayores de 2 pies entre el punto de acceso y la plataforma deben proveerse medios de acceso seguros como escaleras portátiles o de gancho, torres de escalera (stair towers), rampas o pasarelas.', 'With differences in elevation of more than 2 feet between the point of access and the platform, safe means of access must be provided, such as portable or hook-on ladders, stair towers, ramps, or walkways.', 'OSHA 29 CFR 1926.451(e)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (317, 1, 'Una cuerda de descenso con nudos', 'A knotted descent rope', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (317, 2, 'Que el empleado suba por los travesaños del propio andamio', 'That the employee climb the cross braces of the scaffold itself', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (317, 3, 'Escaleras portátiles o acoplables, torres de escalera, rampas, pasarelas u otro medio de acceso seguro previsto en la norma', 'Portable or attachable ladders, stair towers, ramps, walkways, or other safe means of access provided in the standard', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (317, 4, 'Un montacargas de materiales operado por el capataz', 'A material hoist operated by the foreman', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (318, 3, 318, 'Para cumplir los requisitos de calificación de OSHA, un señalero de grúas (signal person) debe demostrar que cumple los requisitos de conocimiento y competencia:', 'To meet OSHA''s qualification requirements, a crane signal person must demonstrate that he or she meets the knowledge and competency requirements:', 'El señalero debe conocer y entender las señales utilizadas (el Método Estándar si son manuales), ser competente en su aplicación y tener una comprensión básica de la operación y las limitaciones del equipo, y demostrarlo con una prueba oral o escrita y una prueba práctica.', 'The signal person must know and understand the signals used (the Standard Method if hand signals are used), be competent in their application, and have a basic understanding of the equipment''s operation and limitations, and demonstrate it with an oral or written test and a practical test.', 'OSHA 29 CFR 1926.1428(c)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (318, 1, 'Solo con una carta de su empleador anterior', 'Only with a letter from his or her previous employer', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (318, 2, 'Únicamente aprobando el examen de operador de grúa', 'Only by passing the crane operator examination', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (318, 3, 'Con dos años de experiencia comprobada, sin necesidad de pruebas', 'With two years of verified experience, with no need for tests', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (318, 4, 'Mediante una prueba oral o escrita y una prueba práctica, evaluadas por un evaluador calificado (de terceros o del empleador)', 'By means of an oral or written test and a practical test, evaluated by a qualified evaluator (third-party or the employer''s)', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (319, 3, 319, 'El equipo de aparejo (rigging equipment) usado para el manejo de materiales debe inspeccionarse:', 'Rigging equipment used for material handling must be inspected:', 'La inspección del aparejo es previa al uso en cada turno y adicional durante el uso si las condiciones lo requieren; todo equipo de aparejo defectuoso debe retirarse de servicio.', 'Rigging inspection is performed before use on each shift and additionally during use if conditions require it; any defective rigging equipment must be removed from service.', 'OSHA 29 CFR 1926.251(a)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (319, 1, 'Una vez al año, por el fabricante', 'Once a year, by the manufacturer', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (319, 2, 'Antes de su uso en cada turno y según sea necesario durante su uso; el equipo defectuoso se retira de servicio', 'Before use on each shift and as necessary during use; defective equipment is removed from service', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (319, 3, 'Solo cuando se note un daño visible', 'Only when visible damage is noticed', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (319, 4, 'Al final de cada semana de trabajo', 'At the end of each work week', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (320, 3, 320, 'Todo acero de refuerzo sobresaliente (protruding reinforcing steel) sobre el cual o dentro del cual un empleado pudiera caer debe:', 'All protruding reinforcing steel on or into which an employee could fall must:', 'Las varillas sobresalientes representan un riesgo de empalamiento: la norma exige protegerlas (con cubiertas reforzadas, protectores tipo canalón u otra protección eficaz) para eliminar ese peligro.', 'Protruding reinforcing steel presents an impalement hazard: the standard requires it to be guarded (with reinforced caps, trough-type covers, or other effective protection) to eliminate that hazard.', 'OSHA 29 CFR 1926.701(b)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (320, 1, 'Protegerse (guarded) para eliminar el peligro de empalamiento (impalement)', 'Be guarded to eliminate the impalement hazard', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (320, 2, 'Pintarse de un color visible', 'Be painted a visible color', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (320, 3, 'Cortarse al ras del concreto el mismo día', 'Be cut flush with the concrete the same day', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (320, 4, 'Señalizarse con banderines cada 6 pies', 'Be flagged every 6 feet', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (321, 3, 321, 'Los encofrados y apuntalamientos (forms and shores), salvo los de losas sobre el terreno y los encofrados deslizantes, no deben retirarse hasta que:', 'Forms and shores, except those for slabs on grade and sliding forms, must not be removed until:', 'El retiro depende de la resistencia alcanzada y no de un plazo fijo: el empleador debe determinar que el concreto soporta su peso y las cargas sobrepuestas, conforme a las condiciones estipuladas en planos y especificaciones o mediante ensayos con un método ASTM apropiado.', 'Removal depends on the strength attained and not on a fixed period: the employer must determine that the concrete supports its own weight and the superimposed loads, in accordance with the conditions stipulated in the plans and specifications or through testing with an appropriate ASTM method.', 'OSHA 29 CFR 1926.703(e)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (321, 1, 'Hayan pasado 28 días desde el vaciado', '28 days have passed since the pour', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (321, 2, 'El arquitecto lo autorice por escrito', 'The architect authorizes it in writing', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (321, 3, 'Se complete el curado de toda la estructura', 'The curing of the entire structure is complete', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (321, 4, 'El empleador determine que el concreto ha ganado resistencia suficiente para soportar su propio peso y las cargas sobrepuestas', 'The employer determines that the concrete has gained sufficient strength to support its own weight and the superimposed loads', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (322, 3, 322, 'En el montaje de acero estructural, cada columna debe anclarse con un mínimo de:', 'In structural steel erection, each column must be anchored with a minimum of:', 'Todas las columnas se anclan con un mínimo de cuatro pernos de anclaje, y cada conjunto de perno, soldadura de placa base y cimentación debe resistir una carga excéntrica de 300 libras ubicada a 18 pulgadas de la cara exterior de la columna.', 'All columns must be anchored with a minimum of four anchor rods, and each anchor rod, base plate weld, and foundation assembly must resist an eccentric load of 300 pounds located 18 inches from the outer face of the column.', 'OSHA 29 CFR 1926.755(a)(1)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (322, 1, '2 pernos de anclaje (anchor rods)', '2 anchor rods', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (322, 2, 'Pernos de anclaje solo si la columna supera los 20 pies de altura', 'Anchor rods only if the column exceeds 20 feet in height', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (322, 3, '4 pernos de anclaje (anchor rods)', '4 anchor rods', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (322, 4, '1 perno de anclaje en cada ala de la columna', '1 anchor rod in each flange of the column', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (323, 3, 323, 'Según el estándar PS 20 (American Softwood Lumber Standard), la madera aserrada clasificada como «seca» (dry, marcada S-DRY) es la que fue secada a un contenido de humedad máximo de:', 'According to standard PS 20 (American Softwood Lumber Standard), lumber classified as "dry" (marked S-DRY) is lumber that was dried to a maximum moisture content of:', 'La definición de madera seca en PS 20 es un contenido de humedad máximo de 19 % al momento del cepillado (surfaced dry); la madera por encima de ese valor se considera verde (S-GRN) y se cepilla a tamaños ligeramente mayores para compensar la contracción.', 'The PS 20 definition of dry lumber is a maximum moisture content of 19 percent at the time of surfacing (surfaced dry); lumber above that value is considered green (S-GRN) and is surfaced to slightly larger sizes to compensate for shrinkage.', 'American Softwood Lumber Standard PS 20 (definición de madera seca); corroborado en USDA Wood Handbook, Capítulo 5');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (323, 1, '12 %', '12 %', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (323, 2, '19 %', '19 %', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (323, 3, '15 %', '15 %', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (323, 4, '25 %', '25 %', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (324, 3, 324, 'En el formato de tres partes de CSI (SectionFormat) para una sección de especificaciones, los materiales, fabricantes, productos y requisitos de desempeño de lo que se va a incorporar al proyecto se describen en:', 'In the CSI three-part format (SectionFormat) for a specification section, the materials, manufacturers, products, and performance requirements for what will be incorporated into the project are described in:', 'El formato CSI divide cada sección en Parte 1 General (requisitos administrativos y de procedimiento), Parte 2 Products (sistemas, ensamblajes, materiales, fabricantes y desempeño) y Parte 3 Execution (instalación y aplicación en campo).', 'The CSI format divides each section into Part 1 – General (administrative and procedural requirements), Part 2 – Products (systems, assemblies, materials, manufacturers, and performance), and Part 3 – Execution (field installation and application).', 'CSI SectionFormat (formato de tres partes de las secciones de especificaciones)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (324, 1, 'La Parte 1, General', 'Part 1, General', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (324, 2, 'La División 01 del manual de proyecto', 'Division 01 of the project manual', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (324, 3, 'La Parte 3, Execution', 'Part 3, Execution', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (324, 4, 'La Parte 2, Products', 'Part 2, Products', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (325, 3, 325, 'En CSI MasterFormat, el acero estructural, las viguetas metálicas (steel joists) y las plataformas metálicas (metal decking) se especifican en:', 'In CSI MasterFormat, structural steel, steel joists, and metal decking are specified in:', 'La División 05 (Metals) cubre el acero estructural, las viguetas y plataformas metálicas y las fabricaciones en metal; la División 03 es concreto y la 06 es madera, plásticos y compuestos.', 'Division 05 (Metals) covers structural steel, metal joists and decking, and metal fabrications; Division 03 is concrete and Division 06 is wood, plastics, and composites.', 'CSI MasterFormat, División 05 (Metals)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (325, 1, 'La División 05, Metals', 'Division 05, Metals', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (325, 2, 'La División 03, Concrete', 'Division 03, Concrete', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (325, 3, 'La División 02, Existing Conditions', 'Division 02, Existing Conditions', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (325, 4, 'La División 06, Wood, Plastics, and Composites', 'Division 06, Wood, Plastics, and Composites', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (326, 3, 326, 'En un plano de sitio (site plan) con topografía, una línea de contorno o curva de nivel (contour line) es la línea que:', 'On a site plan with topography, a contour line is the line that:', 'Cada curva de nivel une puntos de igual elevación respecto al datum del proyecto; cuando las curvas están muy juntas el terreno es inclinado y cuando están separadas el terreno es plano.', 'Each contour line connects points of equal elevation with respect to the project datum; when the lines are close together the terrain is steep, and when they are far apart the terrain is flat.', 'Lectura de planos de sitio y topográficos (curvas de nivel): práctica estándar de lectura de planos');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (326, 1, 'Marca el lindero entre dos parcelas', 'Marks the boundary between two parcels', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (326, 2, 'Indica el recorrido de la tubería de drenaje enterrada', 'Indicates the route of the buried drainage pipe', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (326, 3, 'Delimita el área pavimentada del proyecto', 'Delimits the paved area of the project', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (326, 4, 'Une los puntos del terreno que tienen la misma elevación', 'Connects the points on the ground that have the same elevation', 1);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (327, 3, 327, 'En el cálculo CPM, una actividad tiene una terminación tardía (LF) el día 24 y una duración de 6 días. Su inicio tardío (LS) es el día:', 'In the CPM calculation, an activity has a late finish (LF) on day 24 and a duration of 6 days. Its late start (LS) is day:', 'En la pasada hacia atrás (backward pass), el inicio tardío se obtiene restando la duración a la terminación tardía: LS = LF − duración = 24 − 6 = día 18.', 'In the backward pass, the late start is obtained by subtracting the duration from the late finish: LS = LF − duration = 24 − 6 = day 18.', 'Método de la ruta crítica (CPM), pasada hacia atrás (backward pass): práctica estándar de programación de obra');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (327, 1, '18', '18', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (327, 2, '30', '30', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (327, 3, '24', '24', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (327, 4, '12', '12', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (328, 3, 328, 'Con la estimación PERT de tres puntos, una actividad tiene tiempo optimista de 4 días, más probable de 7 días y pesimista de 16 días. Su duración esperada es de:', 'With the three-point PERT estimate, an activity has an optimistic time of 4 days, a most likely time of 7 days, and a pessimistic time of 16 days. Its expected duration is:', 'PERT pondera el tiempo más probable por cuatro: te = (O + 4M + P) / 6 = (4 + 28 + 16) / 6 = 48 / 6 = 8 días. El promedio simple de los tres valores daría 9 días, pero ese es el promedio triangular, no el de PERT.', 'PERT weights the most likely time by four: te = (O + 4M + P) / 6 = (4 + 28 + 16) / 6 = 48 / 6 = 8 days. The simple average of the three values would give 9 days, but that is the triangular average, not the PERT average.', 'Estimación PERT de tres puntos: práctica estándar de programación de obra');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (328, 1, '9 días', '9 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (328, 2, '7 días', '7 days', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (328, 3, '8 días', '8 days', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (328, 4, '10 días', '10 days', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (329, 3, 329, 'Según el Florida Building Code, el diseño y la construcción de edificios ubicados en áreas de peligro de inundación (flood hazard areas), incluidas las áreas costeras de alto peligro, deben hacerse de acuerdo con:', 'According to the Florida Building Code, the design and construction of buildings and structures located in flood hazard areas, including coastal high hazard areas, must be in accordance with:', 'El FBC remite el diseño resistente a inundaciones al capítulo 5 de ASCE 7 y a ASCE 24, que fijan las elevaciones de inundación de diseño, los materiales resistentes y la protección contra las cargas de inundación.', 'The FBC refers flood-resistant design to Chapter 5 of ASCE 7 and to ASCE 24, which establish the design flood elevations, flood-resistant materials, and protection against flood loads.', 'Florida Building Code — Building, Sección 1612.4');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (329, 1, 'El capítulo 5 de ASCE 7 y la norma ASCE 24 (Flood Resistant Design and Construction)', 'Chapter 5 of ASCE 7 and the ASCE 24 standard (Flood Resistant Design and Construction)', 1);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (329, 2, 'Únicamente la ordenanza local de llanuras de inundación', 'Only the local floodplain ordinance', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (329, 3, 'La guía de diseño del fabricante de los materiales', 'The materials manufacturer''s design guide', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (329, 4, 'El código residencial del condado', 'The county residential code', 0);
INSERT INTO preguntas (id, parte_id, orden, pregunta, pregunta_en, explicacion, explicacion_en, fuente) VALUES (330, 3, 330, 'Según el Florida Building Code, una «región de escombros arrastrados por el viento» (wind-borne debris region), donde las aberturas vidriadas deben ser resistentes al impacto o estar protegidas, es toda área:', 'According to the Florida Building Code, a "wind-borne debris region," where glazed openings must be impact resistant or protected, is any area:', 'La definición combina distancia a la costa y velocidad del viento: a menos de 1 milla de la línea de pleamar media basta una Vult de 130 mph, y en cualquier punto una Vult de 140 mph o más convierte el área en región de escombros arrastrados por el viento.', 'The definition combines distance to the coast and wind speed: within 1 mile of the coastal mean high water line, an ultimate design wind speed (Vult) of 130 mph suffices, and at any location a Vult of 140 mph or more makes the area a wind-borne debris region.', 'Florida Building Code — Building, Sección 1609.1.2 y definición de Wind-Borne Debris Region (Capítulo 2)');
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (330, 1, 'De los condados de Miami-Dade y Broward únicamente', 'In Miami-Dade and Broward counties only', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (330, 2, 'Donde la velocidad básica del viento sea de 120 mph o más', 'Where the basic wind speed is 120 mph or more', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (330, 3, 'Ubicada en una zona de inundación costera categoría V', 'Located in a coastal flood zone category V', 0);
INSERT INTO opciones (pregunta_id, orden, texto, texto_en, es_correcta) VALUES (330, 4, 'Dentro de 1 milla de la línea costera de pleamar media con velocidad de diseño última (Vult) de 130 mph o más, o cualquier área con Vult de 140 mph o más', 'Within 1 mile of the coastal mean high water line with an ultimate design wind speed (Vult) of 130 mph or more, or any area with a Vult of 140 mph or more', 1);
