-- Banco de preguntas GC Florida — version final: 330 preguntas bilingues ES/EN verificadas (2026-10-27)

CREATE TABLE IF NOT EXISTS fuentes_oficiales (
  id INTEGER PRIMARY KEY,
  nombre TEXT NOT NULL,
  tipo TEXT NOT NULL,
  referencia TEXT NOT NULL,
  nota TEXT
);


CREATE TABLE IF NOT EXISTS partes (
  id INTEGER PRIMARY KEY,
  nombre TEXT NOT NULL UNIQUE
);


-- ============================================================
-- MEDICION DE PROGRESO: cada intento del simulacro se guarda
-- aqui (fecha, modo, nota total y detalle por parte) para
-- poder ver la evolucion del estudiante intento a intento.
-- ============================================================

CREATE TABLE IF NOT EXISTS intentos (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  creado_en TEXT NOT NULL DEFAULT (datetime('now')),
  modo TEXT NOT NULL,
  total_preguntas INTEGER NOT NULL,
  correctas INTEGER NOT NULL,
  porcentaje REAL NOT NULL,
  detalle TEXT
);


-- Banco GC Florida v3 bilingue: recrea preguntas y opciones (intentos y fuentes se conservan)
DROP TABLE IF EXISTS opciones;
DROP TABLE IF EXISTS preguntas;
CREATE TABLE preguntas (id INTEGER PRIMARY KEY, parte_id INTEGER NOT NULL REFERENCES partes(id), orden INTEGER NOT NULL, pregunta TEXT NOT NULL, pregunta_en TEXT, explicacion TEXT NOT NULL, explicacion_en TEXT, fuente TEXT NOT NULL, tema TEXT);
CREATE TABLE opciones (id INTEGER PRIMARY KEY AUTOINCREMENT, pregunta_id INTEGER NOT NULL REFERENCES preguntas(id), orden INTEGER NOT NULL, texto TEXT NOT NULL, texto_en TEXT, es_correcta INTEGER NOT NULL DEFAULT 0, UNIQUE(pregunta_id, orden));
CREATE INDEX idx_opciones_pregunta ON opciones(pregunta_id);
CREATE INDEX idx_preguntas_parte ON preguntas(parte_id);







