UPDATE preguntas SET explicacion = 'La s. 865.09 establece que el registro del nombre ficticio vence el 31 de diciembre del quinto año calendario del registro, contando el año de la presentación como el primero: registrado en 2026, vence el 31 de diciembre de 2030, y debe renovarse durante ese año de vencimiento.', explicacion_en = 'Section 865.09 provides that fictitious name registration expires on December 31 of the fifth calendar year of the registration, counting the filing year as the first: filed in 2026, it expires on December 31, 2030, and must be renewed during that expiration year.' WHERE id = 124;
UPDATE preguntas SET explicacion = 'El § 9.3.1 fija la regla: salvo pacto distinto en los Documentos del Contrato, la Solicitud de Pago desglosada se presenta al Arquitecto al menos 10 días antes de la fecha establecida para cada pago de avance. La solicitud se prepara conforme al schedule of values, refleja la retención aplicable y se acompaña de los datos que sustenten el derecho al pago, como las liberaciones de gravamen de subcontratistas y proveedores.', explicacion_en = 'Section 9.3.1 sets the rule: unless otherwise provided in the Contract Documents, the itemized Application for Payment is submitted to the Architect at least ten days before the date established for each progress payment. The Application is prepared in accordance with the schedule of values, reflects the applicable retainage, and is accompanied by the data substantiating the right to payment, such as lien releases from subcontractors and suppliers.' WHERE id = 162;
